-- Candidate dependency of recovery_approval.sql. Existing 0036 file-object
-- guards and 0017 audit-chain guards remain mandatory in the formal migration.
CREATE FUNCTION public.rsc_check_scrap_recovery_files_with_audit_0165(checked_request uuid, audit_ids uuid[])
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE app public.stock_scrap_recovery_requests%ROWTYPE; binding public.stock_scrap_recovery_files%ROWTYPE;
    file public.files%ROWTYPE; metadata jsonb; completion jsonb; expected jsonb;
    file_key text; verified timestamptz;  creation public.audit_events%ROWTYPE; completed public.audit_events%ROWTYPE;
BEGIN
    IF audit_ids IS NULL THEN
        RAISE EXCEPTION '0165 internal audit proof required' USING ERRCODE='23514'; END IF;
    SELECT * INTO app FROM public.stock_scrap_recovery_requests WHERE id=checked_request;
    IF app.id IS NULL THEN RAISE EXCEPTION '0165 recovery application required for files' USING ERRCODE='23514'; END IF;
    FOR binding IN SELECT * FROM public.stock_scrap_recovery_files WHERE recovery_request_id=app.id ORDER BY file_id LOOP
        SELECT * INTO file FROM public.files WHERE id=binding.file_id FOR SHARE;
        metadata:=file.metadata_jsonb; completion:=metadata->'completion';
        file_key:='formal-files/v1/stock_loss_evidence/'||substr(replace(file.id::text,'-',''),1,2)||'/'||replace(file.id::text,'-','');
        IF file.id IS NULL OR file.status IS DISTINCT FROM 'available'
           OR file.uploaded_by IS DISTINCT FROM app.actor_user_id
           OR file.storage_key IS DISTINCT FROM file_key
           OR NOT COALESCE(file.sha256 ~ '^[a-f0-9]{64}$' AND file.size_bytes BETWEEN 1 AND 125829120,false)
           OR NOT COALESCE(jsonb_typeof(completion)='object'
                AND completion->>'etag_sha256' ~ '^[a-f0-9]{64}$'
                AND completion->>'head_manifest_sha256' ~ '^[a-f0-9]{64}$'
                AND completion->>'verified_at' ~ '(Z|[+-][0-9]{2}:[0-9]{2})$'
                AND metadata->>'idempotency_key_hash' ~ '^[a-f0-9]{64}$',false) THEN
            RAISE EXCEPTION '0165 completed recovery upload required' USING ERRCODE='23514';
        END IF;
        BEGIN verified:=(completion->>'verified_at')::timestamptz;
        EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
            RAISE EXCEPTION '0165 recovery upload timestamp invalid' USING ERRCODE='23514';
        END;
        IF NOT COALESCE(file.created_at<=verified AND verified<=app.created_at,false)
           OR binding.created_at IS DISTINCT FROM app.created_at THEN
            RAISE EXCEPTION '0165 recovery upload must precede application' USING ERRCODE='23514';
        END IF;
        IF NOT COALESCE(length(file.original_filename) BETWEEN 1 AND 200
           AND octet_length(file.original_filename)<=255
           AND file.original_filename=normalize(file.original_filename,NFC)
           AND file.original_filename=btrim(file.original_filename)
           AND position('/' IN file.original_filename)=0 AND position(chr(92) IN file.original_filename)=0
           AND EXISTS(SELECT 1 FROM (VALUES ('application/pdf','.pdf'),('image/jpeg','.jpg'),('image/jpeg','.jpeg'),
                ('image/png','.png'),('image/webp','.webp'),('image/heic','.heic'),('image/heif','.heif'),
                ('video/mp4','.mp4'),('video/quicktime','.mov')) allowed(mime,suffix)
                WHERE file.mime_type=allowed.mime AND right(lower(file.original_filename),length(allowed.suffix))=allowed.suffix),false) THEN
            RAISE EXCEPTION '0165 recovery file shape invalid' USING ERRCODE='23514'; END IF;
        expected:=jsonb_build_object('schema','cloud_oam.formal_file_upload_intent.v1',
            'file_id',file.id::text,'storage_key',file_key,'purpose','stock_loss_evidence',
            'provider','aliyun_oss_v2','uploader_user_id',app.actor_user_id,
            'uploader_person_id',app.actor_person_id::text,'authorization_version',app.authorization_version,
            'idempotency_key_hash',metadata->>'idempotency_key_hash',
            'request_sha256',encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(
                jsonb_build_object('mime_type',file.mime_type,'original_filename',file.original_filename,
                    'purpose','stock_loss_evidence','sha256',file.sha256,'size_bytes',file.size_bytes)),'UTF8')),'hex'),
            'completion',jsonb_build_object('etag_sha256',completion->>'etag_sha256',
                'head_manifest_sha256',completion->>'head_manifest_sha256','verified_at',completion->>'verified_at'));
        IF public.rsc_canonical_reconciliation_json_0026(metadata) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(expected)
           OR binding.metadata_sha256 IS DISTINCT FROM encode(sha256(convert_to(
                public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
            RAISE EXCEPTION '0165 exact recovery upload manifest required' USING ERRCODE='23514';
        END IF;
        -- HEAD may contain extra provider metadata, so prove its exact digest
        -- against the original completed-upload audit rather than guess keys.
        SELECT * INTO creation FROM public.audit_events WHERE aggregate_type='formal_file'
            AND aggregate_id=file.id::text AND action='file.upload_intent.created';
        SELECT * INTO completed FROM public.audit_events WHERE aggregate_type='formal_file'
            AND aggregate_id=file.id::text AND action='file.upload_completed';
        expected:=jsonb_build_object('mime_type',file.mime_type,'purpose','stock_loss_evidence',
            'sha256',file.sha256,'size_bytes',file.size_bytes);
        IF (SELECT count(*) FROM public.audit_events WHERE aggregate_type='formal_file'
                AND aggregate_id=file.id::text AND action='file.upload_intent.created')<>1
           OR (SELECT count(*) FROM public.audit_events WHERE aggregate_type='formal_file'
                AND aggregate_id=file.id::text AND action='file.upload_completed')<>1
           OR NOT COALESCE(creation.id=ANY(audit_ids) AND completed.id=ANY(audit_ids)
                AND creation.actor_user_id=app.actor_user_id AND completed.actor_user_id=app.actor_user_id
                AND creation.occurred_at=file.created_at AND completed.occurred_at=verified
                AND creation.stream_version<completed.stream_version
                AND creation.created_at>=creation.occurred_at AND completed.created_at>=completed.occurred_at
                AND completed.created_at<=app.created_at,false)
           OR NOT (creation.before_jsonb IS NULL OR creation.before_jsonb='null'::jsonb)
           OR public.rsc_canonical_reconciliation_json_0026(creation.after_jsonb) IS DISTINCT FROM
                public.rsc_canonical_reconciliation_json_0026(expected||jsonb_build_object('status','pending'))
           OR completed.before_jsonb IS DISTINCT FROM jsonb_build_object('status','pending')
           OR public.rsc_canonical_reconciliation_json_0026(completed.after_jsonb) IS DISTINCT FROM
                public.rsc_canonical_reconciliation_json_0026(expected||jsonb_build_object('status','available',
                    'head_manifest_sha256',completion->>'head_manifest_sha256'))
           OR NOT EXISTS(SELECT 1 FROM public.audit_events WHERE aggregate_type='stock_scrap_recovery_apply'
                AND aggregate_id=app.id::text AND id=ANY(audit_ids) AND stream_version>completed.stream_version) THEN
            RAISE EXCEPTION '0165 original upload creation and completion audits required' USING ERRCODE='23514';
        END IF;
    END LOOP;
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_check_scrap_recovery_files_with_audit_0165(uuid,uuid[])
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

-- Only this private entry point creates the proof. Its children are read-only
-- validators: no cache, caller-supplied bypass, or reuse across SQL writes.
-- Lock inventory before audit to retain the posting serialization order.
CREATE FUNCTION public.rsc_check_scrap_recovery_files_0165(checked_request uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE audit_ids uuid[];
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 audit proof requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM id FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 inventory head required' USING ERRCODE='23514'; END IF;
    audit_ids:=public.rsc_loss_inventory_audit_members_0159();
    PERFORM public.rsc_check_scrap_recovery_files_with_audit_0165(checked_request,audit_ids);
END;
$function$;

CREATE FUNCTION public.rsc_check_scrap_recovery_events_with_audit_0165(fact jsonb, stage text, recipient uuid, audit_ids uuid[])
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE aggregate text:='stock_scrap_recovery_'||stage; kind text:='stock_scrap.recovery_'||stage;
    identifier text:=fact->>'id'; key text; at timestamptz:=(fact->>'created_at')::timestamptz;
    before_state text; after_state text; body jsonb; 
BEGIN
    IF audit_ids IS NULL THEN
        RAISE EXCEPTION '0165 internal audit proof required' USING ERRCODE='23514'; END IF;
    IF stage='apply' THEN before_state:='unsubmitted'; after_state:='awaiting_regional';
    ELSIF stage='regional' THEN before_state:='awaiting_regional';
        after_state:=CASE fact->>'decision' WHEN 'verified' THEN 'awaiting_headquarters' WHEN 'needs_evidence' THEN 'needs_evidence' END;
    ELSIF stage='headquarters' THEN before_state:='awaiting_headquarters';
        after_state:=CASE fact->>'decision' WHEN 'approve' THEN 'approved_pending_execution' WHEN 'request_regional_review' THEN 'awaiting_regional' END;
    END IF;
    IF identifier IS NULL OR after_state IS NULL OR recipient IS NULL THEN
        RAISE EXCEPTION '0165 known recovery event stage required' USING ERRCODE='23514'; END IF;
    key:=kind||':'||identifier;
    body:=jsonb_build_object('fact_id',identifier,
        'recovery_request_id',CASE WHEN stage='apply' THEN identifier ELSE fact->>'recovery_request_id' END,
        'scrap_line_id',fact->>'scrap_line_id','stage',stage,'status',after_state,'stock_effect','none',
        'actor_person_id',fact->>'actor_person_id','authorization_version',(fact->>'authorization_version')::bigint,
        'request_id',fact->>'request_id','request_hash',fact->>'request_hash','reason',fact->>'reason',
        'decision',fact->'decision','regional_review_id',CASE WHEN stage='headquarters' THEN fact->>'regional_review_id' END);
    IF (SELECT count(*) FROM public.audit_events WHERE aggregate_type=aggregate AND aggregate_id=identifier)<>1
       OR NOT EXISTS(SELECT 1 FROM public.audit_events e WHERE e.id=ANY(audit_ids)
           AND e.stream_key='inventory' AND e.aggregate_type=aggregate AND e.aggregate_id=identifier
           AND e.actor_user_id=fact->>'actor_user_id' AND e.action=kind AND e.request_id=key
           AND e.before_jsonb='{}'::jsonb AND public.rsc_canonical_reconciliation_json_0026(e.after_jsonb)=public.rsc_canonical_reconciliation_json_0026(body) AND e.created_at=at AND e.occurred_at=at)
       OR (SELECT count(*) FROM public.state_transition_events WHERE aggregate_type=aggregate AND aggregate_id=identifier)<>1
       OR NOT EXISTS(SELECT 1 FROM public.state_transition_events e WHERE e.aggregate_type=aggregate AND e.aggregate_id=identifier
           AND e.from_status=before_state AND e.to_status=after_state AND e.actor_id=fact->>'actor_user_id'
           AND e.reason=kind AND e.idempotency_key=key AND e.created_at=at AND e.occurred_at=at AND public.rsc_canonical_reconciliation_json_0026(e.metadata_jsonb)=public.rsc_canonical_reconciliation_json_0026(body))
       OR (SELECT count(*) FROM public.outbox_events WHERE aggregate_type=aggregate AND aggregate_id=identifier)<>1
       OR NOT EXISTS(SELECT 1 FROM public.outbox_events e WHERE e.aggregate_type=aggregate AND e.aggregate_id=identifier
           AND e.event_type=kind AND e.idempotency_key=key AND e.created_at=at AND public.rsc_canonical_reconciliation_json_0026(e.payload_jsonb)=public.rsc_canonical_reconciliation_json_0026(body))
       OR (SELECT count(*) FROM public.notification_events WHERE business_type=aggregate AND business_id=identifier)<>1
       OR NOT EXISTS(SELECT 1 FROM public.notification_events e WHERE e.business_type=aggregate AND e.business_id=identifier
           AND e.event_type=kind AND e.dedup_key=key AND e.created_at=at AND e.occurred_at=at AND public.rsc_canonical_reconciliation_json_0026(e.payload_jsonb)=public.rsc_canonical_reconciliation_json_0026(body)
           AND e.target_manifest_sha256=encode(sha256(convert_to('notification-person-targets.v1'||chr(10)||recipient::text,'UTF8')),'hex')
           AND (SELECT count(*) FROM public.notification_person_targets WHERE event_id=e.id)=1
           AND EXISTS(SELECT 1 FROM public.notification_person_targets WHERE event_id=e.id AND person_id=recipient AND created_at=at)) THEN
        RAISE EXCEPTION '0165 exact recovery approval event bundle required' USING ERRCODE='23514';
    END IF;
    IF EXISTS(SELECT 1 FROM public.inventory_transactions WHERE idempotency_key_hash=fact->>'idempotency_key_hash'
        OR (source_document_type=aggregate AND source_document_id=identifier)) THEN
        RAISE EXCEPTION '0165 recovery approval cannot post stock' USING ERRCODE='23514'; END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_check_scrap_recovery_events_with_audit_0165(jsonb,text,uuid,uuid[])
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

-- Only this private entry point creates the proof. Its children are read-only
-- validators: no cache, caller-supplied bypass, or reuse across SQL writes.
-- Lock inventory before audit to retain the posting serialization order.
CREATE FUNCTION public.rsc_check_scrap_recovery_events_0165(fact jsonb, stage text, recipient uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE audit_ids uuid[];
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 audit proof requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM id FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 inventory head required' USING ERRCODE='23514'; END IF;
    audit_ids:=public.rsc_loss_inventory_audit_members_0159();
    PERFORM public.rsc_check_scrap_recovery_events_with_audit_0165(fact,stage,recipient,audit_ids);
END;
$function$;

CREATE FUNCTION public.rsc_fence_scrap_recovery_events_0165()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE row_value jsonb; candidates jsonb; event_kind text; aggregate text; identifier text; checked_scrap uuid; event public.notification_events%ROWTYPE;
BEGIN
    -- Select OLD on mutation so changing an aggregate cannot hide the original
    -- immutable business binding. Worker delivery/attempt fields remain mutable.
    candidates:=CASE WHEN TG_OP='INSERT' THEN jsonb_build_array(to_jsonb(NEW))
        WHEN TG_OP='DELETE' THEN jsonb_build_array(to_jsonb(OLD))
        ELSE jsonb_build_array(to_jsonb(OLD),to_jsonb(NEW)) END;
    FOR row_value IN SELECT DISTINCT value FROM jsonb_array_elements(candidates) LOOP
    event_kind:=COALESCE(row_value->>'event_type',row_value->>'action');
    IF TG_TABLE_NAME='notification_person_targets' THEN
        SELECT * INTO event FROM public.notification_events WHERE id=(row_value->>'event_id')::uuid;
        aggregate:=event.business_type; identifier:=event.business_id;
    ELSIF TG_TABLE_NAME='notification_events' THEN
        aggregate:=row_value->>'business_type'; identifier:=row_value->>'business_id';
    ELSE aggregate:=row_value->>'aggregate_type'; identifier:=row_value->>'aggregate_id'; END IF;
    IF event_kind IN ('stock_scrap.recovery_apply','stock_scrap.recovery_regional','stock_scrap.recovery_headquarters')
       AND aggregate IS DISTINCT FROM replace(event_kind,'stock_scrap.recovery_','stock_scrap_recovery_') THEN
        RAISE EXCEPTION '0165 recovery event type and aggregate mismatch' USING ERRCODE='23514'; END IF;
    IF aggregate NOT IN ('stock_scrap_recovery_apply','stock_scrap_recovery_regional','stock_scrap_recovery_headquarters')
       OR aggregate IS NULL THEN CONTINUE; END IF;
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION '0165 recovery events cannot be deleted' USING ERRCODE='23514'; END IF;
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 recovery event writes require read committed' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 inventory head required' USING ERRCODE='23514'; END IF;
    IF aggregate='stock_scrap_recovery_apply' THEN
        SELECT scrap_line_id INTO checked_scrap FROM public.stock_scrap_recovery_requests WHERE id::text=identifier;
    ELSIF aggregate='stock_scrap_recovery_regional' THEN
        SELECT scrap_line_id INTO checked_scrap FROM public.stock_scrap_recovery_regional_reviews WHERE id::text=identifier;
    ELSE SELECT scrap_line_id INTO checked_scrap FROM public.stock_scrap_recovery_headquarters_reviews WHERE id::text=identifier; END IF;
    IF checked_scrap IS NULL THEN
        RAISE EXCEPTION '0165 detached recovery event has no request' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_check_scrap_recovery_approvals_0165(checked_scrap);
    END LOOP;
    RETURN NULL;
END;
$function$;

REVOKE ALL ON FUNCTION public.rsc_check_scrap_recovery_files_0165(uuid),
    public.rsc_check_scrap_recovery_events_0165(jsonb,text,uuid),public.rsc_fence_scrap_recovery_events_0165()
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

DO $block$
DECLARE name text;
BEGIN
    FOREACH name IN ARRAY ARRAY['audit_events','outbox_events','state_transition_events',
        'notification_events','notification_person_targets'] LOOP
        EXECUTE format('CREATE CONSTRAINT TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON public.%I '
            'DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.rsc_fence_scrap_recovery_events_0165()',
            'trg_'||name||'_scrap_recovery_0165',name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER %I',name,'trg_'||name||'_scrap_recovery_0165');
    END LOOP;
END;
$block$;

-- Candidate component, not a release migration or a posting authorization.
-- Proves ordered recovery requests against their exact original/corrected scrap.
-- Requires recovery_evidence.sql plus retained file/audit guards. Historical
-- stock/SN, current authority and typed request seals still require proofs.
CREATE FUNCTION public.rsc_check_scrap_recovery_command_0165(fact jsonb, expected jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE n integer;
BEGIN
    IF NOT COALESCE(
        fact->>'request_id' ~ '^[A-Za-z0-9._:-]{8,160}$'
        AND fact->>'request_hash' ~ '^[a-f0-9]{64}$'
        AND fact->>'idempotency_key_hash' ~ '^[a-f0-9]{64}$'
        AND fact->>'actor_user_id' ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
        AND fact->>'actor_user_id'<>'00000000-0000-0000-0000-000000000000'
        AND fact->>'actor_person_id'<>'00000000-0000-0000-0000-000000000000'
        AND (fact->>'authorization_version')::bigint>0
        AND (fact->>'created_at')::timestamptz<=clock_timestamp()
        AND length(fact->>'reason') BETWEEN 1 AND 500
        AND btrim(fact->>'reason',chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(28)||chr(29)||chr(30)||chr(31)||chr(32)||chr(133)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288))=fact->>'reason',false)
       OR EXISTS(SELECT 1 FROM generate_series(1,length(fact->>'reason')) p
           WHERE ascii(substr(fact->>'reason',p,1))<32 AND ascii(substr(fact->>'reason',p,1)) NOT IN (9,10))
       OR fact->'command_jsonb' IS DISTINCT FROM expected
       OR public.rsc_canonical_reconciliation_json_0026(fact->'command_jsonb') IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(expected)
       OR fact->>'request_hash' IS DISTINCT FROM encode(sha256(convert_to(
           public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
        RAISE EXCEPTION '0165 exact canonical recovery command required' USING ERRCODE='23514';
    END IF;
    SELECT count(*) INTO n FROM (
        SELECT actor_user_id,request_id,idempotency_key_hash FROM public.stock_scrap_recovery_requests
        UNION ALL SELECT actor_user_id,request_id,idempotency_key_hash FROM public.stock_scrap_recovery_regional_reviews
        UNION ALL SELECT actor_user_id,request_id,idempotency_key_hash FROM public.stock_scrap_recovery_headquarters_reviews
        UNION ALL SELECT actor_user_id,request_id,idempotency_key_hash FROM public.stock_scrap_recovery_executions
    ) r WHERE r.idempotency_key_hash=fact->>'idempotency_key_hash'
        OR (r.actor_user_id=fact->>'actor_user_id' AND r.request_id=fact->>'request_id');
    IF n<>1 THEN
        RAISE EXCEPTION '0165 recovery request coordinates reused' USING ERRCODE='23514';
    END IF;
END;
$function$;

CREATE FUNCTION public.rsc_check_scrap_recovery_approvals_with_audit_0165(checked_scrap uuid, audit_ids uuid[])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE line public.stock_scrap_lines%ROWTYPE; root public.stock_loss_dispositions%ROWTYPE;
    parent public.stock_operation_orders%ROWTYPE; source_fact jsonb; source jsonb; command jsonb;
    app public.stock_scrap_recovery_requests%ROWTYPE;
    region public.stock_scrap_recovery_regional_reviews%ROWTYPE;
    hq public.stock_scrap_recovery_headquarters_reviews%ROWTYPE;
    execution public.stock_scrap_recovery_executions%ROWTYPE;
    stage text; previous_at timestamptz; closed_at timestamptz; evidence jsonb;
    consumed uuid[]; result jsonb:='[]'::jsonb; final_hq uuid; terminal boolean:=false;
BEGIN
    IF audit_ids IS NULL THEN
        RAISE EXCEPTION '0165 internal audit proof required' USING ERRCODE='23514'; END IF;
    SELECT * INTO line FROM public.stock_scrap_lines WHERE id=checked_scrap;
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=line.root_disposition_id;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    IF line.source_kind='original' THEN source_fact:=to_jsonb(root);
    ELSIF line.source_kind='correction' THEN
        SELECT to_jsonb(c) INTO source_fact FROM public.stock_loss_correction_executions c
            WHERE c.id=line.correction_execution_id AND c.root_disposition_id=root.id;
    END IF;
    IF line.id IS NULL OR parent.id IS NULL OR source_fact IS NULL
       OR source_fact->>'disposition' IS DISTINCT FROM 'scrap'
       OR source_fact->>'scrap_operation_id' IS DISTINCT FROM line.operation_id::text
       OR source_fact->>'posting_transaction_id' IS DISTINCT FROM line.posting_transaction_id::text
       OR source_fact->>'posting_movement_id' IS DISTINCT FROM line.posting_movement_id::text
       OR source_fact->>'source_account_id' IS DISTINCT FROM line.frozen_account_id::text
       OR (source_fact->>'quantity')::numeric IS DISTINCT FROM line.quantity
       OR source_fact->>'request_hash' !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION '0165 exact recovery scrap source required' USING ERRCODE='23514';
    END IF;
    source:=jsonb_build_object('scrap_line_id',line.id::text,
        'expected_scrap_request_hash',source_fact->>'request_hash');
    closed_at:=line.created_at;
    FOR app IN SELECT * FROM public.stock_scrap_recovery_requests WHERE scrap_line_id=line.id ORDER BY created_at,id LOOP
        IF terminal OR app.created_at<=closed_at OR app.actor_person_id IS DISTINCT FROM parent.requester_id
           OR app.expected_scrap_request_hash IS DISTINCT FROM source_fact->>'request_hash' THEN
            RAISE EXCEPTION '0165 new application requires closed previous application and exact requester' USING ERRCODE='23514';
        END IF;
        SELECT jsonb_agg(f.file_id::text ORDER BY f.file_id::text) INTO evidence
            FROM public.stock_scrap_recovery_files f WHERE f.recovery_request_id=app.id;
        IF evidence IS NULL OR jsonb_array_length(evidence) NOT BETWEEN 1 AND 20
           OR EXISTS(SELECT 1 FROM public.stock_scrap_recovery_files f WHERE f.recovery_request_id=app.id
                AND (f.created_at<>app.created_at OR f.metadata_sha256 !~ '^[a-f0-9]{64}$')) THEN
            RAISE EXCEPTION '0165 exact recovery evidence bindings required' USING ERRCODE='23514';
        END IF;
        command:=jsonb_build_object('action','apply_scrap_recovery','source',source,'request_id',app.request_id,
            'reason',app.reason,'evidence_file_ids',evidence);
        PERFORM public.rsc_check_scrap_recovery_command_0165(to_jsonb(app),command);
        PERFORM public.rsc_check_scrap_recovery_files_with_audit_0165(app.id,audit_ids);
        PERFORM public.rsc_check_scrap_recovery_events_with_audit_0165(to_jsonb(app),'apply',app.actor_person_id,audit_ids);
        stage:='awaiting_regional'; previous_at:=app.created_at; consumed:='{}'::uuid[]; final_hq:=NULL;
        FOR region IN SELECT * FROM public.stock_scrap_recovery_regional_reviews
            WHERE recovery_request_id=app.id ORDER BY created_at,id LOOP
            IF stage<>'awaiting_regional' OR region.created_at<=previous_at OR region.scrap_line_id<>line.id
               OR region.actor_user_id=app.actor_user_id OR region.actor_person_id=app.actor_person_id
               OR region.expected_request_hash IS DISTINCT FROM app.request_hash
               OR region.decision NOT IN ('verified','needs_evidence') THEN
                RAISE EXCEPTION '0165 independent ordered regional recovery review required' USING ERRCODE='23514';
            END IF;
            command:=jsonb_build_object('action','review_scrap_recovery_region','source',source,
                'request_id',region.request_id,'reason',region.reason,'recovery_request_id',app.id::text,
                'expected_request_hash',app.request_hash,'decision',region.decision);
            PERFORM public.rsc_check_scrap_recovery_command_0165(to_jsonb(region),command);
            PERFORM public.rsc_check_scrap_recovery_events_with_audit_0165(to_jsonb(region),'regional',app.actor_person_id,audit_ids);
            stage:=CASE region.decision WHEN 'verified' THEN 'awaiting_headquarters' ELSE 'needs_evidence' END;
            previous_at:=region.created_at; final_hq:=NULL;
            SELECT * INTO hq FROM public.stock_scrap_recovery_headquarters_reviews
                WHERE regional_review_id=region.id;
            IF hq.id IS NOT NULL THEN
                IF stage<>'awaiting_headquarters' OR hq.created_at<=previous_at
                   OR hq.recovery_request_id<>app.id OR hq.scrap_line_id<>line.id
                   OR hq.regional_decision IS DISTINCT FROM 'verified'
                   OR hq.actor_user_id IN (app.actor_user_id,region.actor_user_id)
                   OR hq.actor_person_id IN (app.actor_person_id,region.actor_person_id)
                   OR hq.expected_regional_hash IS DISTINCT FROM region.request_hash
                   OR hq.decision NOT IN ('approve','request_regional_review') THEN
                    RAISE EXCEPTION '0165 independent ordered headquarters recovery review required' USING ERRCODE='23514';
                END IF;
                command:=jsonb_build_object('action','review_scrap_recovery_headquarters','source',source,
                    'request_id',hq.request_id,'reason',hq.reason,'recovery_request_id',app.id::text,
                    'expected_request_hash',app.request_hash,'regional_review_id',region.id::text,
                    'expected_regional_hash',region.request_hash,'decision',hq.decision);
                PERFORM public.rsc_check_scrap_recovery_command_0165(to_jsonb(hq),command);
                PERFORM public.rsc_check_scrap_recovery_events_with_audit_0165(to_jsonb(hq),'headquarters',app.actor_person_id,audit_ids);
                stage:=CASE hq.decision WHEN 'approve' THEN 'approved_pending_execution' ELSE 'awaiting_regional' END;
                previous_at:=hq.created_at; final_hq:=hq.id; consumed:=array_append(consumed,hq.id);
            END IF;
        END LOOP;
        IF EXISTS(SELECT 1 FROM public.stock_scrap_recovery_headquarters_reviews
            WHERE recovery_request_id=app.id AND NOT(id=ANY(consumed))) THEN
            RAISE EXCEPTION '0165 detached headquarters recovery review' USING ERRCODE='23514';
        END IF;
        FOR execution IN SELECT * FROM public.stock_scrap_recovery_executions WHERE recovery_request_id=app.id LOOP
            IF stage<>'approved_pending_execution' OR execution.headquarters_review_id IS DISTINCT FROM final_hq
               OR execution.scrap_line_id<>line.id OR execution.created_at<=previous_at
               OR execution.headquarters_decision IS DISTINCT FROM 'approve'
               OR execution.expected_headquarters_hash IS DISTINCT FROM hq.request_hash
               OR execution.plan_hash !~ '^[a-f0-9]{64}$' THEN
                RAISE EXCEPTION '0165 recovery execution requires exact final independent approval' USING ERRCODE='23514';
            END IF;
            command:=jsonb_build_object('action','execute_scrap_recovery','source',source,
                'request_id',execution.request_id,'reason',execution.reason,'recovery_request_id',app.id::text,
                'expected_request_hash',app.request_hash,'headquarters_review_id',hq.id::text,
                'expected_headquarters_hash',hq.request_hash,'expected_plan_hash',execution.plan_hash);
            PERFORM public.rsc_check_scrap_recovery_command_0165(to_jsonb(execution),command);
            stage:='executed'; previous_at:=execution.created_at;
        END LOOP;
        terminal:=stage<>'needs_evidence'; closed_at:=previous_at;
        result:=result||jsonb_build_array(jsonb_build_object('recovery_request_id',app.id::text,
            'status',stage,'headquarters_review_id',final_hq));
    END LOOP;
    RETURN result;
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_check_scrap_recovery_approvals_with_audit_0165(uuid,uuid[])
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

-- Only this private entry point creates the proof. Its children are read-only
-- validators: no cache, caller-supplied bypass, or reuse across SQL writes.
-- Lock inventory before audit to retain the posting serialization order.
CREATE FUNCTION public.rsc_check_scrap_recovery_approvals_0165(checked_scrap uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE audit_ids uuid[];
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 audit proof requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM id FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 inventory head required' USING ERRCODE='23514'; END IF;
    audit_ids:=public.rsc_loss_inventory_audit_members_0159();
    RETURN public.rsc_check_scrap_recovery_approvals_with_audit_0165(checked_scrap,audit_ids);
END;
$function$;

CREATE FUNCTION public.rsc_fence_scrap_recovery_approvals_0165()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE checked_scrap uuid;
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 recovery writes require read committed' USING ERRCODE='23514';
    END IF;
    -- Same serialization root as inventory posting. Waiting here establishes a
    -- fresh RC snapshot before checking other transactions' stage/key inserts.
    PERFORM 1 FROM public.inventory_ledger_heads FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 inventory head required' USING ERRCODE='23514'; END IF;
    IF TG_TABLE_NAME='stock_scrap_recovery_files' THEN
        SELECT scrap_line_id INTO checked_scrap FROM public.stock_scrap_recovery_requests WHERE id=NEW.recovery_request_id;
    ELSE checked_scrap:=NEW.scrap_line_id;
    END IF;
    PERFORM public.rsc_check_scrap_recovery_approvals_0165(checked_scrap);
    RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.rsc_check_scrap_recovery_command_0165(jsonb,jsonb),
    public.rsc_check_scrap_recovery_approvals_0165(uuid),
    public.rsc_fence_scrap_recovery_approvals_0165()
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

CREATE FUNCTION public.rsc_scrap_facts_append_only_0165()
RETURNS trigger LANGUAGE plpgsql SET search_path TO pg_catalog, public
AS $function$
BEGIN
    RAISE EXCEPTION '0165 scrap and recovery facts are append only' USING ERRCODE='23514';
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_scrap_facts_append_only_0165()
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

DO $block$
DECLARE name text;
BEGIN
    FOREACH name IN ARRAY ARRAY['stock_scrap_recovery_requests','stock_scrap_recovery_files',
        'stock_scrap_recovery_regional_reviews','stock_scrap_recovery_headquarters_reviews',
        'stock_scrap_recovery_executions'] LOOP
        EXECUTE format('CREATE CONSTRAINT TRIGGER %I AFTER INSERT ON public.%I '
            'DEFERRABLE INITIALLY DEFERRED FOR EACH ROW '
            'EXECUTE FUNCTION public.rsc_fence_scrap_recovery_approvals_0165()',
            'trg_'||name||'_approval_0165',name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER %I',name,'trg_'||name||'_approval_0165');
    END LOOP;
    FOREACH name IN ARRAY ARRAY['stock_scrap_lines','stock_scrap_serials','stock_scrap_files',
        'stock_scrap_recovery_requests','stock_scrap_recovery_files',
        'stock_scrap_recovery_regional_reviews','stock_scrap_recovery_headquarters_reviews',
        'stock_scrap_recovery_executions'] LOOP
        EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON public.%I '
            'FOR EACH ROW EXECUTE FUNCTION public.rsc_scrap_facts_append_only_0165()',
            'trg_'||name||'_immutable_0165',name);
        EXECUTE format('CREATE TRIGGER %I BEFORE TRUNCATE ON public.%I '
            'FOR EACH STATEMENT EXECUTE FUNCTION public.rsc_scrap_facts_append_only_0165()',
            'trg_'||name||'_truncate_0165',name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER %I',name,'trg_'||name||'_immutable_0165');
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER %I',name,'trg_'||name||'_truncate_0165');
    END LOOP;
END;
$block$;

-- Current-authority component. The eventual admission trigger must derive
-- owner/location/requester from the exact scrap source, never client input.
-- Historical graph and delivery checks must NOT call this function: retained
-- approvals remain facts after an old approver's permission expires.
CREATE FUNCTION public.rsc_assert_scrap_recovery_authority_0165(
    actor_id text, actor_version bigint, actor_person uuid, owner_id uuid,
    location_id uuid, requester_id uuid, required_stage text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE actor public.users%ROWTYPE; person public.people%ROWTYPE; actor_org public.organizations%ROWTYPE;
    location public.stock_locations%ROWTYPE; at timestamptz; ancestors uuid[]; latest uuid[];
    invalid_tree boolean; target_org uuid; required_role text; required_scope text; required_scope_id text;
    required_action text;
BEGIN
    IF current_setting('transaction_isolation')<>'read committed'
       OR required_stage IS NULL OR required_stage NOT IN ('apply','regional','headquarters','execute') THEN
        RAISE EXCEPTION '0165 explicit recovery stage and read committed required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_lock_formal_principal_graph_0026(ARRAY[actor_id]::text[]);
    SELECT * INTO actor FROM public.users WHERE id=actor_id;
    SELECT * INTO person FROM public.people WHERE id=actor.person_id;
    SELECT * INTO actor_org FROM public.organizations WHERE id=person.organization_id FOR SHARE;
    IF actor.id IS NULL OR person.id IS NULL OR actor_org.id IS NULL
       OR NOT actor.is_active OR actor.account_status IS DISTINCT FROM 'active'
       OR person.employment_status IS DISTINCT FROM 'active'
       OR actor.person_id IS DISTINCT FROM actor_person OR actor.authorization_version IS DISTINCT FROM actor_version
       OR actor_org.status IS DISTINCT FROM 'active' OR actor_org.org_type NOT IN ('headquarters','region_company','department')
       OR NOT EXISTS(SELECT 1 FROM public.auth_identities WHERE user_id=actor.id
            AND status='active' AND verified_at IS NOT NULL AND revoked_at IS NULL) THEN
        RAISE EXCEPTION '0165 current recovery identity invalid' USING ERRCODE='23514'; END IF;
    IF required_stage='apply' THEN
        IF actor_person IS DISTINCT FROM requester_id THEN
            RAISE EXCEPTION '0165 recovery applicant must be original custodian' USING ERRCODE='23514'; END IF;
        required_role:='technician'; required_scope:='person'; required_scope_id:=requester_id::text;
        required_action:='apply_scrap_recovery'; target_org:=person.organization_id;
    ELSIF required_stage='regional' THEN
        required_role:='provincial_manager'; required_scope:='organization'; required_scope_id:=owner_id::text;
        required_action:='review_scrap_recovery_regional'; target_org:=owner_id;
    ELSE
        required_role:='admin'; required_scope:='national'; required_scope_id:='*'; target_org:=owner_id;
        required_action:=CASE required_stage WHEN 'headquarters' THEN 'review_scrap_recovery_headquarters'
            ELSE 'execute_scrap_recovery' END;
    END IF;
    -- Organization-deny semantics follow the target: the applicant's person
    -- scope uses their organization; regional/HQ actions use the asset owner.
    WITH RECURSIVE tree AS (
        SELECT id,parent_id,status,ARRAY[id] visited,false cycle FROM public.organizations WHERE id=target_org
        UNION ALL SELECT o.id,o.parent_id,o.status,t.visited||o.id,o.id=ANY(t.visited)
            FROM public.organizations o JOIN tree t ON o.id=t.parent_id WHERE NOT t.cycle
    ) SELECT array_agg(id ORDER BY id),bool_or(cycle OR status<>'active') INTO ancestors,invalid_tree FROM tree;
    IF COALESCE(invalid_tree,true) THEN
        RAISE EXCEPTION '0165 recovery scope hierarchy invalid' USING ERRCODE='23514'; END IF;
    PERFORM id FROM public.organizations WHERE id=ANY(ancestors) OR id=owner_id
       OR id::text IN (SELECT scope_id FROM public.role_assignments WHERE user_id=actor_id AND scope_type='organization')
       ORDER BY id FOR SHARE;
    WITH RECURSIVE tree AS (
        SELECT id,parent_id,status,ARRAY[id] visited,false cycle FROM public.organizations WHERE id=target_org
        UNION ALL SELECT o.id,o.parent_id,o.status,t.visited||o.id,o.id=ANY(t.visited)
            FROM public.organizations o JOIN tree t ON o.id=t.parent_id WHERE NOT t.cycle
    ) SELECT array_agg(id ORDER BY id),bool_or(cycle OR status<>'active') INTO latest,invalid_tree FROM tree;
    IF COALESCE(invalid_tree,true) OR ancestors IS DISTINCT FROM latest
       OR NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=owner_id AND org_type='region_company' AND status='active') THEN
        RAISE EXCEPTION '0165 recovery owner or scope changed' USING ERRCODE='23514'; END IF;
    SELECT * INTO location FROM public.stock_locations WHERE id=location_id FOR UPDATE;
    IF location.id IS NULL OR location.status IS DISTINCT FROM 'active' OR location.location_type IS DISTINCT FROM 'personal'
       OR location.owner_org_id IS DISTINCT FROM owner_id OR location.custodian_person_id IS DISTINCT FROM requester_id THEN
        RAISE EXCEPTION '0165 exact current recovery personal location required' USING ERRCODE='23514'; END IF;
    -- The location lock also prevents a new FK-bound assignment from entering
    -- while the current assignment rows are held through the transaction.
    PERFORM id FROM public.custody_assignments WHERE custody_assignments.location_id=location.id ORDER BY id FOR SHARE;
    at:=clock_timestamp();
    IF (SELECT count(*) FROM public.custody_assignments WHERE custody_assignments.location_id=location.id
            AND valid_from<=at AND (valid_to IS NULL OR valid_to>at))<>1
       OR NOT EXISTS(SELECT 1 FROM public.custody_assignments WHERE custody_assignments.location_id=location.id
            AND custodian_person_id=requester_id AND valid_from<=at AND (valid_to IS NULL OR valid_to>at)) THEN
        RAISE EXCEPTION '0165 unique current recovery custody required' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.role_assignments a JOIN public.roles r ON r.id=a.role_id
        LEFT JOIN public.organizations scope ON scope.id::text=a.scope_id
        WHERE a.user_id=actor.id AND a.status IN ('active','scheduled') AND a.revoked_at IS NULL
          AND a.valid_from<=at AND (a.valid_to IS NULL OR a.valid_to>at) AND r.status='active'
          AND NOT CASE r.code
            WHEN 'admin' THEN NOT r.is_external AND a.scope_type='national' AND a.scope_id='*' AND actor_org.org_type='headquarters'
            WHEN 'provincial_manager' THEN NOT r.is_external AND a.scope_type='organization' AND scope.id IS NOT NULL
                AND scope.org_type='region_company' AND scope.status='active'
            WHEN 'technician' THEN NOT r.is_external AND a.scope_type='person' AND a.scope_id=person.id::text
            ELSE false END) THEN
        RAISE EXCEPTION '0165 recovery role graph invalid' USING ERRCODE='23514'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.role_assignments a JOIN public.roles r ON r.id=a.role_id
        JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id
        WHERE a.user_id=actor.id AND a.status IN ('active','scheduled') AND a.revoked_at IS NULL
          AND a.valid_from<=at AND (a.valid_to IS NULL OR a.valid_to>at)
          AND r.status='active' AND r.code=required_role AND NOT r.is_external
          AND a.scope_type=required_scope AND a.scope_id=required_scope_id
          AND rp.effect='allow' AND p.resource='stock_operation' AND p.action=required_action AND p.field_code='')
       OR EXISTS(SELECT 1 FROM public.role_assignments a JOIN public.roles r ON r.id=a.role_id
        JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id
        WHERE a.user_id=actor.id AND a.status IN ('active','scheduled') AND a.revoked_at IS NULL
          AND a.valid_from<=at AND (a.valid_to IS NULL OR a.valid_to>at) AND r.status='active'
          AND rp.effect='deny' AND p.resource='stock_operation' AND p.action=required_action AND p.field_code=''
          AND ((a.scope_type='national' AND a.scope_id='*')
            OR (a.scope_type='organization' AND a.scope_id IN (SELECT value::text FROM unnest(ancestors) value))
            OR (required_stage='apply' AND a.scope_type='person' AND a.scope_id=requester_id::text))) THEN
        RAISE EXCEPTION '0165 current stage-specific recovery permission required' USING ERRCODE='23514'; END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_assert_scrap_recovery_authority_0165(text,bigint,uuid,uuid,uuid,uuid,text)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

-- Candidate admission component. Install only with the complete 0165 stock,
-- SN, immutable-history, approval/evidence and request-recovery guards.
-- This file neither enables production grants nor replaces the 0164 guards.
CREATE FUNCTION public.rsc_scrap_recovery_source_0165(checked_scrap uuid)
RETURNS TABLE(owner_org_id uuid, location_id uuid, requester_id uuid, request_hash text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE line public.stock_scrap_lines%ROWTYPE; root public.stock_loss_dispositions%ROWTYPE;
    loss_line public.stock_operation_lines%ROWTYPE; loss_order public.stock_operation_orders%ROWTYPE;
    scrap_order public.stock_operation_orders%ROWTYPE; account public.stock_accounts%ROWTYPE;
    custody public.custody_assignments%ROWTYPE; fact jsonb;
BEGIN
    SELECT * INTO line FROM public.stock_scrap_lines WHERE id=checked_scrap;
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=line.root_disposition_id;
    SELECT * INTO loss_line FROM public.stock_operation_lines WHERE id=line.loss_line_id;
    SELECT * INTO loss_order FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT * INTO scrap_order FROM public.stock_operation_orders WHERE id=line.operation_id;
    SELECT * INTO account FROM public.stock_accounts WHERE id=line.frozen_account_id;
    SELECT * INTO custody FROM public.custody_assignments WHERE id=line.custody_assignment_id;
    IF NOT COALESCE(line.id IS NOT NULL AND root.id IS NOT NULL AND loss_line.id IS NOT NULL
        AND loss_order.id IS NOT NULL AND scrap_order.id IS NOT NULL AND account.id IS NOT NULL
        AND custody.id IS NOT NULL AND line.operation_type='scrap'
        AND root.line_id=loss_line.id AND root.operation_id=loss_line.operation_id
        AND root.source_account_id=account.id AND root.quantity=line.quantity AND line.quantity>0
        AND loss_line.operation_type='loss_report' AND loss_order.operation_type='loss_report'
        AND loss_order.status='submitted' AND loss_line.quantity=line.quantity
        AND loss_line.reserved_account_id=account.id AND loss_line.material_id=account.material_id
        AND loss_line.target_condition=account.condition_code AND account.availability_bucket='frozen'
        AND account.condition_code IN ('new','used','damaged')
        AND account.custodian_person_id=loss_order.requester_id
        AND account.location_id=loss_order.source_location_id
        AND scrap_order.id<>loss_order.id AND scrap_order.operation_type='scrap' AND scrap_order.status='posted'
        AND scrap_order.requester_id=loss_order.requester_id AND scrap_order.source_location_id=account.location_id
        AND scrap_order.posting_transaction_id=line.posting_transaction_id
        AND custody.location_id=account.location_id AND custody.custodian_person_id=loss_order.requester_id
        AND custody.valid_from<=line.created_at AND (custody.valid_to IS NULL OR custody.valid_to>line.created_at),false)
        OR scrap_order.oam_work_order_id IS NOT NULL OR scrap_order.target_location_id IS NOT NULL
        OR scrap_order.transit_location_id IS NOT NULL OR scrap_order.target_custody_assignment_id IS NOT NULL THEN
        RAISE EXCEPTION '0165 exact loss, scrap and frozen custody source required' USING ERRCODE='23514';
    END IF;
    IF line.source_kind='original' THEN
        IF line.original_decision_id IS DISTINCT FROM root.headquarters_decision_id
            OR scrap_order.loss_headquarters_decision_id IS DISTINCT FROM line.original_decision_id
            OR scrap_order.loss_correction_decision_id IS NOT NULL
            OR line.correction_execution_id IS NOT NULL OR line.correction_decision_id IS NOT NULL
            OR line.predecessor_reversal_id IS NOT NULL THEN
            RAISE EXCEPTION '0165 original scrap source binding invalid' USING ERRCODE='23514'; END IF;
        fact:=to_jsonb(root);
    ELSIF line.source_kind='correction' THEN
        SELECT to_jsonb(c) INTO fact FROM public.stock_loss_correction_executions c
            WHERE c.id=line.correction_execution_id AND c.root_disposition_id=root.id
              AND c.reversal_id=line.predecessor_reversal_id AND c.correction_decision_id=line.correction_decision_id;
        IF line.original_decision_id IS NOT NULL OR scrap_order.loss_headquarters_decision_id IS NOT NULL
            OR scrap_order.loss_correction_decision_id IS DISTINCT FROM line.correction_decision_id THEN
            RAISE EXCEPTION '0165 corrected scrap source binding invalid' USING ERRCODE='23514'; END IF;
    ELSE
        RAISE EXCEPTION '0165 explicit scrap source kind required' USING ERRCODE='23514';
    END IF;
    IF NOT COALESCE(fact IS NOT NULL AND fact->>'disposition'='scrap'
        AND fact->>'scrap_operation_id'=line.operation_id::text
        AND fact->>'source_account_id'=account.id::text
        AND fact->>'custody_assignment_id'=custody.id::text
        AND (fact->>'quantity')::numeric=line.quantity
        AND fact->>'posting_transaction_id'=line.posting_transaction_id::text
        AND fact->>'posting_movement_id'=line.posting_movement_id::text
        AND fact->>'request_hash' ~ '^[a-f0-9]{64}$'
        AND fact->>'request_hash'=scrap_order.request_hash
        AND (fact->>'created_at')::timestamptz=line.created_at AND scrap_order.created_at=line.created_at,false)
        OR fact->>'target_account_id' IS NOT NULL OR fact->>'return_operation_id' IS NOT NULL THEN
        RAISE EXCEPTION '0165 exact original or corrected scrap execution required' USING ERRCODE='23514';
    END IF;
    RETURN QUERY SELECT account.owner_org_id,account.location_id,loss_order.requester_id,fact->>'request_hash';
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_scrap_recovery_source_0165(uuid)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

CREATE FUNCTION public.rsc_admit_scrap_recovery_0165()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE source record; stage text;
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 recovery admission requires read committed' USING ERRCODE='23514'; END IF;
    stage:=CASE TG_TABLE_NAME WHEN 'stock_scrap_recovery_requests' THEN 'apply'
        WHEN 'stock_scrap_recovery_regional_reviews' THEN 'regional'
        WHEN 'stock_scrap_recovery_headquarters_reviews' THEN 'headquarters'
        WHEN 'stock_scrap_recovery_executions' THEN 'execute' END;
    IF stage IS NULL OR TG_OP<>'INSERT' THEN
        RAISE EXCEPTION '0165 exact recovery admission table required' USING ERRCODE='23514'; END IF;
    -- Match the writer lock order. No client-provided owner, location or
    -- requester can influence current authority. Recheck only NEW at COMMIT;
    -- historical approval/event validation must never reauthorize old actors.
    PERFORM id FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION '0165 inventory serialization head required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_lock_formal_principal_graph_0026(ARRAY[NEW.actor_user_id]::text[]);
    SELECT * INTO source FROM public.rsc_scrap_recovery_source_0165(NEW.scrap_line_id);
    IF NEW.command_jsonb->'source' IS DISTINCT FROM jsonb_build_object(
        'scrap_line_id',NEW.scrap_line_id::text,'expected_scrap_request_hash',source.request_hash) THEN
        RAISE EXCEPTION '0165 recovery command must bind exact scrap source' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_assert_scrap_recovery_authority_0165(NEW.actor_user_id,NEW.authorization_version,
        NEW.actor_person_id,source.owner_org_id,source.location_id,source.requester_id,stage);
    RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_admit_scrap_recovery_0165()
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

DO $install$
DECLARE name text;
BEGIN
    FOREACH name IN ARRAY ARRAY['stock_scrap_recovery_requests','stock_scrap_recovery_regional_reviews',
        'stock_scrap_recovery_headquarters_reviews','stock_scrap_recovery_executions'] LOOP
        EXECUTE format('CREATE TRIGGER trg_recovery_admission_before_0165 BEFORE INSERT ON public.%I '
            'FOR EACH ROW EXECUTE FUNCTION public.rsc_admit_scrap_recovery_0165()',name);
        EXECUTE format('CREATE CONSTRAINT TRIGGER trg_recovery_admission_commit_0165 AFTER INSERT ON public.%I '
            'DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.rsc_admit_scrap_recovery_0165()',name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER trg_recovery_admission_before_0165',name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER trg_recovery_admission_commit_0165',name);
    END LOOP;
END;
$install$;

-- Exact historical ledger edges. This composes with (does not replace) the
-- complete loss-hold, opening, plan, event, balance and serial-history proofs.
-- No runtime grants or migration activation are supplied here.
CREATE FUNCTION public.rsc_assert_scrap_tracking_0165(checked_account uuid, amount numeric, serial_count integer, at timestamptz)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE account public.stock_accounts%ROWTYPE; policy public.material_inventory_policies%ROWTYPE;
BEGIN
    SELECT * INTO account FROM public.stock_accounts WHERE id=checked_account;
    SELECT * INTO policy FROM public.material_inventory_policies WHERE material_id=account.material_id
        AND effective_from<=at AND (effective_to IS NULL OR effective_to>at);
    IF NOT COALESCE(account.id IS NOT NULL AND policy.id IS NOT NULL AND amount>0
        AND amount<1000000000000000 AND serial_count>=0
        AND policy.tracking_mode IN ('none','lot','serial','lot_and_serial')
        AND scale(trim_scale(amount))<=policy.quantity_scale
        AND (policy.allow_fraction OR amount=trunc(amount)),false)
        OR (SELECT count(*) FROM public.material_inventory_policies WHERE material_id=account.material_id
            AND effective_from<=at AND (effective_to IS NULL OR effective_to>at))<>1
        OR (policy.tracking_mode IN ('serial','lot_and_serial') AND amount<>serial_count)
        OR (policy.tracking_mode IN ('none','lot') AND serial_count<>0)
        OR (policy.tracking_mode IN ('lot','lot_and_serial') AND account.lot_id IS NULL)
        OR (policy.tracking_mode IN ('none','serial') AND account.lot_id IS NOT NULL) THEN
        RAISE EXCEPTION '0165 historical scrap quantity and tracking policy required' USING ERRCODE='23514'; END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_assert_scrap_tracking_0165(uuid,numeric,integer,timestamptz)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

CREATE FUNCTION public.rsc_check_scrap_inventory_edges_with_audit_0165(checked_scrap uuid, audit_ids uuid[])
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE line public.stock_scrap_lines%ROWTYPE; fact jsonb; source record;
    tx public.inventory_transactions%ROWTYPE; move public.inventory_movements%ROWTYPE;
    inverse public.stock_loss_disposition_reversals%ROWTYPE;
    recovery public.stock_scrap_recovery_executions%ROWTYPE;
    inverse_tx public.inventory_transactions%ROWTYPE; inverse_move public.inventory_movements%ROWTYPE;
    account public.stock_accounts%ROWTYPE; sn record; prior record; admission record;
    ids jsonb; actual jsonb; expected jsonb; actor jsonb; command jsonb;
    kind text; key text; inverse_json jsonb; recovery_json jsonb;
BEGIN
    IF audit_ids IS NULL THEN
        RAISE EXCEPTION '0165 internal audit proof required' USING ERRCODE='23514'; END IF;
    SELECT * INTO source FROM public.rsc_scrap_recovery_source_0165(checked_scrap);
    SELECT * INTO line FROM public.stock_scrap_lines WHERE id=checked_scrap;
    SELECT * INTO account FROM public.stock_accounts WHERE id=line.frozen_account_id;
    IF line.source_kind='original' THEN
        SELECT to_jsonb(f) INTO fact FROM public.stock_loss_dispositions f WHERE id=line.root_disposition_id;
        kind:='stock_loss_disposition';
    ELSE
        SELECT to_jsonb(f) INTO fact FROM public.stock_loss_correction_executions f WHERE id=line.correction_execution_id;
        kind:='stock_loss_correction_execution';
    END IF;
    SELECT * INTO tx FROM public.inventory_transactions WHERE id=line.posting_transaction_id;
    SELECT * INTO move FROM public.inventory_movements WHERE id=line.posting_movement_id;
    SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb)
        INTO ids FROM public.stock_scrap_serials WHERE scrap_line_id=line.id;
    SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb)
        INTO actual FROM public.stock_operation_serials WHERE line_id=line.loss_line_id;
    IF actual IS DISTINCT FROM ids THEN
        RAISE EXCEPTION '0165 scrap serial set must equal the exact loss line' USING ERRCODE='23514'; END IF;
    IF NOT COALESCE(tx.id IS NOT NULL AND move.id IS NOT NULL AND tx.status='posted' AND tx.movement_type='scrap'
        AND tx.source_document_type=kind AND tx.source_document_id=fact->>'id'
        AND tx.actor_user_id=fact->>'actor_user_id' AND tx.idempotency_key_hash=fact->>'idempotency_key_hash'
        AND tx.transaction_no='INV-SCRAP-'||upper(left(fact->>'idempotency_key_hash',24))
        AND tx.posting_key='stock-scrap:'||(fact->>'id')||':'||(fact->>'idempotency_key_hash')
        AND tx.effective_at=line.created_at AND tx.created_at=tx.posted_at AND tx.posted_at>=line.created_at
        AND move.transaction_id=tx.id AND move.line_no=1 AND move.from_account_id=account.id
        AND move.quantity=line.quantity AND move.external_boundary_code='stock_operation_scrap'
        AND move.created_at=tx.posted_at,false) OR tx.reversed_transaction_id IS NOT NULL OR move.to_account_id IS NOT NULL
        OR (SELECT count(*) FROM public.inventory_movements WHERE transaction_id=tx.id)<>1
        OR (SELECT count(*) FROM public.inventory_transactions WHERE source_document_type=kind AND source_document_id=fact->>'id')<>1 THEN
        RAISE EXCEPTION '0165 exact single scrap posting edge required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb) INTO actual
        FROM public.inventory_movement_serials WHERE movement_id=move.id;
    IF actual IS DISTINCT FROM ids OR EXISTS(SELECT 1 FROM public.inventory_movement_serials
        WHERE movement_id=move.id AND (transaction_id<>tx.id OR created_at<>tx.posted_at))
        OR EXISTS(SELECT 1 FROM public.stock_scrap_serials WHERE scrap_line_id=line.id AND created_at<>line.created_at) THEN
        RAISE EXCEPTION '0165 scrap movement serial bindings required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_assert_scrap_tracking_0165(account.id,line.quantity,jsonb_array_length(ids),tx.effective_at);
    actor:=jsonb_build_object('user_id',fact->>'actor_user_id','person_id',
        CASE line.source_kind WHEN 'original' THEN fact->>'executor_person_id' ELSE fact->>'actor_person_id' END,
        'authorization_version',(fact->>'authorization_version')::bigint);
    command:=jsonb_build_object('effective_at',to_char(tx.effective_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        'movement_type','scrap','movements',jsonb_build_array(jsonb_build_object(
            'external_boundary_code','stock_operation_scrap','from_account_id',account.id::text,
            'to_account_id',NULL,'quantity',trim_scale(line.quantity)::text,'serial_ids',ids)),
        'posting_key',tx.posting_key,'source_document_id',fact->>'id','source_document_type',kind,
        'transaction_no',tx.transaction_no);
    expected:=jsonb_build_object('operation','post','actor',actor,'command',command);
    IF tx.request_hash IS DISTINCT FROM encode(sha256(convert_to(
        public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
        RAISE EXCEPTION '0165 exact canonical scrap posting request required' USING ERRCODE='23514'; END IF;
    FOR sn IN SELECT s.*,i.material_id,i.lot_id FROM public.stock_scrap_serials s
        JOIN public.inventory_serials i ON i.id=s.serial_id WHERE s.scrap_line_id=line.id ORDER BY s.serial_id LOOP
        SELECT m.*,t.ledger_cursor,t.status,t.movement_type INTO prior
            FROM public.inventory_movement_serials s JOIN public.inventory_movements m ON m.id=s.movement_id
            JOIN public.inventory_transactions t ON t.id=m.transaction_id
            WHERE s.serial_id=sn.serial_id AND t.ledger_cursor<tx.ledger_cursor
            ORDER BY t.ledger_cursor DESC,m.line_no DESC LIMIT 1;
        SELECT m.*,t.ledger_cursor,t.status INTO admission
            FROM public.inventory_movement_serials s JOIN public.inventory_movements m ON m.id=s.movement_id
            JOIN public.inventory_transactions t ON t.id=m.transaction_id
            WHERE s.serial_id=sn.serial_id AND t.ledger_cursor<tx.ledger_cursor
            ORDER BY t.ledger_cursor,m.line_no LIMIT 1;
        IF NOT COALESCE(prior.id IS NOT NULL AND prior.id=sn.previous_movement_id AND prior.to_account_id=account.id
            AND prior.status='posted' AND prior.movement_type<>'scrap' AND admission.id IS NOT NULL
            AND admission.id=sn.admission_movement_id AND admission.status='posted'
            AND admission.ledger_cursor<=prior.ledger_cursor AND sn.material_id=account.material_id,false)
            OR admission.from_account_id IS NOT NULL OR admission.to_account_id IS NULL
            OR sn.lot_id IS DISTINCT FROM account.lot_id THEN
            RAISE EXCEPTION '0165 exact previous and first-admission serial edges required' USING ERRCODE='23514'; END IF;
    END LOOP;
    SELECT * INTO recovery FROM public.stock_scrap_recovery_executions WHERE scrap_line_id=line.id;
    IF recovery.id IS NULL THEN
        IF EXISTS(SELECT 1 FROM public.inventory_transactions WHERE reversed_transaction_id=tx.id)
            OR EXISTS(SELECT 1 FROM public.stock_loss_disposition_reversals
                WHERE original_transaction_id=tx.id OR scrap_line_id=line.id) THEN
            RAISE EXCEPTION '0165 scrap inverse requires independent recovery execution' USING ERRCODE='23514'; END IF;
        RETURN;
    END IF;
    PERFORM public.rsc_check_scrap_recovery_approvals_with_audit_0165(line.id,audit_ids);
    SELECT * INTO inverse FROM public.stock_loss_disposition_reversals WHERE id=recovery.reversal_id;
    SELECT * INTO inverse_tx FROM public.inventory_transactions WHERE id=inverse.posting_transaction_id;
    SELECT * INTO inverse_move FROM public.inventory_movements WHERE id=inverse.posting_movement_id;
    IF NOT COALESCE(inverse.id IS NOT NULL AND inverse.scrap_recovery_execution_id=recovery.id
        AND inverse.scrap_line_id=line.id AND inverse.scrap_source_kind=line.source_kind
        AND inverse.root_disposition_id=line.root_disposition_id AND inverse.original_transaction_id=tx.id
        AND inverse.original_movement_id=move.id AND inverse.target_account_id=account.id AND inverse.quantity=line.quantity
        AND inverse_tx.id IS NOT NULL AND inverse_move.id IS NOT NULL AND inverse_tx.status='posted'
        AND inverse_tx.movement_type='reversal' AND inverse_tx.reversed_transaction_id=tx.id
        AND inverse_tx.ledger_cursor>tx.ledger_cursor AND inverse.created_at>line.created_at
        AND inverse_tx.source_document_type='stock_loss_disposition_reversal' AND inverse_tx.source_document_id=inverse.id::text
        AND inverse_tx.actor_user_id=inverse.actor_user_id AND inverse_tx.idempotency_key_hash=inverse.idempotency_key_hash
        AND inverse_tx.transaction_no='INV-LOSS-REV-'||upper(left(inverse.idempotency_key_hash,20))
        AND inverse_tx.posting_key='stock-loss:reverse_loss:'||inverse.id::text||':'||inverse.idempotency_key_hash
        AND inverse_tx.effective_at=inverse.created_at AND inverse_tx.created_at=inverse_tx.posted_at
        AND inverse_tx.posted_at>=inverse.created_at AND inverse_move.created_at=inverse_tx.posted_at
        AND inverse_move.transaction_id=inverse_tx.id AND inverse_move.line_no=move.line_no
        AND inverse_move.to_account_id=account.id AND inverse_move.quantity=move.quantity
        AND inverse_move.external_boundary_code=move.external_boundary_code,false)
        OR inverse.reversed_correction_id IS DISTINCT FROM line.correction_execution_id
        OR inverse.source_account_id IS NOT NULL OR inverse_move.from_account_id IS NOT NULL
        OR (SELECT count(*) FROM public.inventory_movements WHERE transaction_id=inverse_tx.id)<>1
        OR (SELECT count(*) FROM public.inventory_transactions WHERE source_document_type='stock_loss_disposition_reversal'
            AND source_document_id=inverse.id::text)<>1 THEN
        RAISE EXCEPTION '0165 exact single approved scrap inverse edge required' USING ERRCODE='23514'; END IF;
    inverse_json:=to_jsonb(inverse); recovery_json:=to_jsonb(recovery);
    FOREACH key IN ARRAY ARRAY['created_at','actor_user_id','actor_person_id','authorization_version','request_id',
        'request_hash','idempotency_key_hash','reason','command_jsonb','plan_hash','plan_jsonb'] LOOP
        IF (inverse_json->key)::text IS DISTINCT FROM (recovery_json->key)::text THEN
            RAISE EXCEPTION '0165 recovery and inverse command context must agree' USING ERRCODE='23514'; END IF;
    END LOOP;
    actor:=jsonb_build_object('user_id',inverse.actor_user_id,'person_id',inverse.actor_person_id::text,
        'authorization_version',inverse.authorization_version);
    command:=jsonb_build_object('effective_at',to_char(inverse_tx.effective_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        'original_transaction_id',tx.id::text,'posting_key',inverse_tx.posting_key,'source_document_id',inverse.id::text,
        'source_document_type','stock_loss_disposition_reversal','transaction_no',inverse_tx.transaction_no);
    expected:=jsonb_build_object('operation','reverse','actor',actor,'command',command);
    IF inverse_tx.request_hash IS DISTINCT FROM encode(sha256(convert_to(
        public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
        RAISE EXCEPTION '0165 exact canonical scrap inverse request required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb) INTO actual
        FROM public.inventory_movement_serials WHERE movement_id=inverse_move.id;
    IF actual IS DISTINCT FROM ids OR EXISTS(SELECT 1 FROM public.inventory_movement_serials
        WHERE movement_id=inverse_move.id AND (transaction_id<>inverse_tx.id OR created_at<>inverse_tx.posted_at)) THEN
        RAISE EXCEPTION '0165 inverse must restore exactly the scrapped serial set' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_assert_scrap_tracking_0165(account.id,inverse.quantity,jsonb_array_length(ids),inverse_tx.effective_at);
    FOR sn IN SELECT serial_id FROM public.stock_scrap_serials WHERE scrap_line_id=line.id LOOP
        SELECT m.id INTO prior FROM public.inventory_movement_serials s
            JOIN public.inventory_movements m ON m.id=s.movement_id JOIN public.inventory_transactions t ON t.id=m.transaction_id
            WHERE s.serial_id=sn.serial_id AND t.ledger_cursor<inverse_tx.ledger_cursor
            ORDER BY t.ledger_cursor DESC,m.line_no DESC LIMIT 1;
        IF prior.id IS DISTINCT FROM move.id THEN
            RAISE EXCEPTION '0165 recovery must reverse the last exact serial scrap' USING ERRCODE='23514'; END IF;
    END LOOP;
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_check_scrap_inventory_edges_with_audit_0165(uuid,uuid[])
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

-- Only this private entry point creates the proof. Its children are read-only
-- validators: no cache, caller-supplied bypass, or reuse across SQL writes.
-- Lock inventory before audit to retain the posting serialization order.
CREATE FUNCTION public.rsc_check_scrap_inventory_edges_0165(checked_scrap uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE audit_ids uuid[];
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 audit proof requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM id FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 inventory head required' USING ERRCODE='23514'; END IF;
    audit_ids:=public.rsc_loss_inventory_audit_members_0159();
    PERFORM public.rsc_check_scrap_inventory_edges_with_audit_0165(checked_scrap,audit_ids);
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_check_scrap_inventory_edges_0165(uuid)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

CREATE FUNCTION public.rsc_fence_scrap_inventory_edges_0165()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE old_row jsonb; new_row jsonb; identifiers uuid[]; transactions uuid[]; checked uuid; tx_id uuid;
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 scrap inventory proof requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM id FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 inventory serialization head required' USING ERRCODE='23514'; END IF;
    IF TG_OP<>'INSERT' THEN old_row:=to_jsonb(OLD); END IF;
    IF TG_OP<>'DELETE' THEN new_row:=to_jsonb(NEW); END IF;
    identifiers:=ARRAY[(old_row->>'id')::uuid,(new_row->>'id')::uuid];
    transactions:=CASE WHEN TG_TABLE_NAME='inventory_transactions' THEN identifiers ELSE
        ARRAY[(old_row->>'transaction_id')::uuid,(new_row->>'transaction_id')::uuid,
            (old_row->>'posting_transaction_id')::uuid,(new_row->>'posting_transaction_id')::uuid] END;
    -- Orphan transactions using the scrap boundary must never hide behind a
    -- missing business child. Reverse checks cover both OLD and NEW bindings.
    FOREACH tx_id IN ARRAY transactions LOOP
        IF tx_id IS NOT NULL AND (EXISTS(SELECT 1 FROM public.inventory_transactions WHERE id=tx_id AND movement_type='scrap')
            OR EXISTS(SELECT 1 FROM public.inventory_movements WHERE transaction_id=tx_id AND external_boundary_code='stock_operation_scrap'))
            AND NOT EXISTS(SELECT 1 FROM public.stock_scrap_lines WHERE posting_transaction_id=tx_id)
            AND NOT EXISTS(SELECT 1 FROM public.stock_scrap_recovery_executions r
                JOIN public.stock_loss_disposition_reversals i ON i.id=r.reversal_id WHERE i.posting_transaction_id=tx_id) THEN
            RAISE EXCEPTION '0165 scrap boundary requires exact business fact' USING ERRCODE='23514'; END IF;
    END LOOP;
    FOR checked IN SELECT DISTINCT l.id FROM public.stock_scrap_lines l
        LEFT JOIN public.stock_scrap_recovery_executions r ON r.scrap_line_id=l.id
        LEFT JOIN public.stock_loss_disposition_reversals i ON i.id=r.reversal_id
        WHERE l.id=ANY(identifiers) OR l.root_disposition_id=ANY(identifiers) OR l.correction_execution_id=ANY(identifiers)
            OR l.frozen_account_id=ANY(identifiers) OR r.id=ANY(identifiers) OR i.id=ANY(identifiers)
            OR l.posting_transaction_id=ANY(transactions) OR i.posting_transaction_id=ANY(transactions)
            OR l.id IN ((old_row->>'scrap_line_id')::uuid,(new_row->>'scrap_line_id')::uuid)
            OR (TG_TABLE_NAME='stock_operation_serials' AND l.loss_line_id IN (
                (old_row->>'line_id')::uuid,(new_row->>'line_id')::uuid))
            OR (TG_TABLE_NAME='material_inventory_policies' AND EXISTS(SELECT 1 FROM public.stock_accounts a
                WHERE a.id=l.frozen_account_id AND a.material_id IN ((old_row->>'material_id')::uuid,(new_row->>'material_id')::uuid)))
            OR EXISTS(SELECT 1 FROM public.stock_scrap_serials s WHERE s.scrap_line_id=l.id AND (
                s.previous_movement_id=ANY(identifiers) OR s.admission_movement_id=ANY(identifiers)
                OR (TG_TABLE_NAME='inventory_serials' AND s.serial_id=ANY(identifiers))
                OR s.serial_id IN ((old_row->>'serial_id')::uuid,(new_row->>'serial_id')::uuid)
                OR EXISTS(SELECT 1 FROM public.inventory_movement_serials link
                    WHERE link.serial_id=s.serial_id AND link.transaction_id=ANY(transactions))))
        ORDER BY l.id LOOP
        PERFORM public.rsc_check_scrap_inventory_edges_0165(checked);
    END LOOP;
    RETURN COALESCE(NEW,OLD);
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_fence_scrap_inventory_edges_0165()
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

DO $install$
DECLARE name text;
BEGIN
    FOREACH name IN ARRAY ARRAY['stock_scrap_lines','stock_scrap_serials','stock_scrap_recovery_executions',
        'stock_loss_dispositions','stock_loss_correction_executions','stock_loss_disposition_reversals',
        'inventory_transactions','inventory_movements','inventory_movement_serials','stock_accounts',
        'stock_operation_serials','material_inventory_policies','inventory_serials'] LOOP
        EXECUTE format('CREATE CONSTRAINT TRIGGER trg_scrap_inventory_edges_0165 AFTER INSERT OR UPDATE OR DELETE ON public.%I '
            'DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.rsc_fence_scrap_inventory_edges_0165()',name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER trg_scrap_inventory_edges_0165',name);
    END LOOP;
END;
$install$;

-- Candidate historical plans, reconstructed at each transaction's original
-- cursor. Compose with full upstream/event/lifecycle guards before activation.
CREATE FUNCTION public.rsc_scrap_policy_basis_0165(checked_account uuid, at timestamptz, recorded jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE policy public.material_inventory_policies%ROWTYPE; material uuid; expected jsonb; start_text text; end_text text;
BEGIN
    SELECT material_id INTO material FROM public.stock_accounts WHERE id=checked_account;
    SELECT * INTO policy FROM public.material_inventory_policies WHERE material_id=material
        AND effective_from<=at AND (effective_to IS NULL OR effective_to>at);
    IF policy.id IS NULL OR (SELECT count(*) FROM public.material_inventory_policies WHERE material_id=material
        AND effective_from<=at AND (effective_to IS NULL OR effective_to>at))<>1 THEN
        RAISE EXCEPTION '0165 unique historical scrap policy required' USING ERRCODE='23514'; END IF;
    start_text:=to_char(policy.effective_from AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||
        CASE WHEN extract(microseconds FROM policy.effective_from)::bigint%1000000=0 THEN ''
        ELSE to_char(policy.effective_from AT TIME ZONE 'UTC','.US') END||'+00:00';
    end_text:=CASE WHEN policy.effective_to IS NULL THEN NULL ELSE
        to_char(policy.effective_to AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||
        CASE WHEN extract(microseconds FROM policy.effective_to)::bigint%1000000=0 THEN ''
        ELSE to_char(policy.effective_to AT TIME ZONE 'UTC','.US') END||'+00:00' END;
    expected:=jsonb_build_array(jsonb_build_array(material::text,policy.id::text,policy.tracking_mode,
        policy.quantity_scale,policy.allow_fraction,start_text,recorded#>'{0,6}'));
    -- A later policy closure may add an end date. It cannot rewrite the six
    -- original fields or a non-null end date recorded in the original plan.
    IF public.rsc_canonical_reconciliation_json_0026(recorded) IS DISTINCT FROM
        public.rsc_canonical_reconciliation_json_0026(expected)
        OR (recorded#>'{0,6}' IS DISTINCT FROM 'null'::jsonb AND recorded#>>'{0,6}' IS DISTINCT FROM end_text) THEN
        RAISE EXCEPTION '0165 exact historical scrap policy fingerprint required' USING ERRCODE='23514'; END IF;
    RETURN expected;
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_scrap_policy_basis_0165(uuid,timestamptz,jsonb)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

CREATE FUNCTION public.rsc_check_scrap_historical_plans_with_audit_0165(checked_scrap uuid, audit_ids uuid[])
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE line public.stock_scrap_lines%ROWTYPE; root public.stock_loss_dispositions%ROWTYPE;
    parent public.stock_operation_orders%ROWTYPE; header public.stock_operation_orders%ROWTYPE;
    account public.stock_accounts%ROWTYPE; tx public.inventory_transactions%ROWTYPE;
    inverse public.stock_loss_disposition_reversals%ROWTYPE; inverse_tx public.inventory_transactions%ROWTYPE;
    decision public.stock_loss_headquarters_decisions%ROWTYPE; review public.stock_loss_headquarters_reviews%ROWTYPE;
    correction public.stock_loss_correction_decisions%ROWTYPE; predecessor public.stock_loss_disposition_reversals%ROWTYPE;
    custody public.custody_assignments%ROWTYPE; file public.files%ROWTYPE; binding record;
    fact jsonb; holds jsonb; share jsonb; source jsonb; intent jsonb; command jsonb; expected jsonb;
    serials jsonb; ids jsonb; evidence jsonb:='[]'::jsonb; file_ids jsonb; fingerprint jsonb;
    person text; key text; request_hash text; plan_hash text; metadata_hash text; cutoff bigint; at timestamptz;
BEGIN
    IF audit_ids IS NULL THEN
        RAISE EXCEPTION '0165 internal audit proof required' USING ERRCODE='23514'; END IF;
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 historical scrap proof requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM id FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 inventory head required' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.rsc_scrap_recovery_source_0165(checked_scrap);
    SELECT * INTO line FROM public.stock_scrap_lines WHERE id=checked_scrap;
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=line.root_disposition_id;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT * INTO header FROM public.stock_operation_orders WHERE id=line.operation_id;
    SELECT * INTO account FROM public.stock_accounts WHERE id=line.frozen_account_id;
    SELECT * INTO tx FROM public.inventory_transactions WHERE id=line.posting_transaction_id;
    SELECT * INTO decision FROM public.stock_loss_headquarters_decisions WHERE id=root.headquarters_decision_id;
    SELECT * INTO review FROM public.stock_loss_headquarters_reviews WHERE id=decision.review_id;
    IF line.source_kind='original' THEN
        fact:=to_jsonb(root);person:=root.executor_person_id::text;
        source:=jsonb_build_object('kind','original','headquarters_decision_id',decision.id::text,
            'expected_headquarters_review_hash',review.request_hash,'expected_submission_plan_hash',parent.plan_hash);
        IF NOT COALESCE(decision.disposition='scrap' AND decision.line_id=root.line_id
            AND review.operation_id=parent.id AND review.created_at<=line.created_at,false) THEN
            RAISE EXCEPTION '0165 exact original scrap approval required' USING ERRCODE='23514'; END IF;
    ELSE
        SELECT to_jsonb(c) INTO fact FROM public.stock_loss_correction_executions c WHERE id=line.correction_execution_id;
        person:=fact->>'actor_person_id';
        SELECT * INTO correction FROM public.stock_loss_correction_decisions WHERE id=line.correction_decision_id;
        SELECT * INTO predecessor FROM public.stock_loss_disposition_reversals WHERE id=line.predecessor_reversal_id;
        source:=jsonb_build_object('kind','correction','root_disposition_id',root.id::text,
            'expected_root_request_hash',root.request_hash,'expected_submission_plan_hash',parent.plan_hash,
            'reversal_id',predecessor.id::text,'expected_reversal_hash',predecessor.request_hash,
            'correction_decision_id',correction.id::text,'expected_correction_decision_hash',correction.request_hash);
        IF NOT COALESCE(correction.disposition='scrap' AND correction.root_disposition_id=root.id
            AND predecessor.root_disposition_id=root.id AND correction.reversal_id=predecessor.id
            AND correction.expected_reversal_hash=predecessor.request_hash
            AND predecessor.created_at<=correction.created_at AND correction.created_at<=line.created_at
            AND fact->>'reason'=header.reason,false) THEN
            RAISE EXCEPTION '0165 exact corrected scrap approval required' USING ERRCODE='23514'; END IF;
    END IF;
    at:=line.created_at;cutoff:=tx.ledger_cursor-1;
    SELECT COALESCE(jsonb_agg(file_id::text ORDER BY file_id::text),'[]'::jsonb) INTO file_ids
        FROM public.stock_scrap_files WHERE scrap_line_id=line.id;
    intent:=jsonb_build_object('source',source,'execution_reason',header.reason,'evidence_file_ids',file_ids);
    command:=jsonb_build_object('schema_version',1,'action','scrap','intent',intent,
        'request_id',fact->>'request_id','expected_plan_hash',fact->>'plan_hash');
    SELECT * INTO custody FROM public.custody_assignments WHERE location_id=account.location_id
        AND valid_from<=at AND (valid_to IS NULL OR valid_to>at);
    IF NOT COALESCE(custody.id=line.custody_assignment_id AND custody.id::text=fact->>'custody_assignment_id'
        AND custody.custodian_person_id=account.custodian_person_id,false)
        OR (SELECT count(*) FROM public.custody_assignments WHERE location_id=account.location_id
            AND valid_from<=at AND (valid_to IS NULL OR valid_to>at))<>1 THEN
        RAISE EXCEPTION '0165 unique historical scrap custody required' USING ERRCODE='23514'; END IF;
    holds:=public.rsc_loss_hold_projection_0159(account.id,cutoff);
    SELECT value INTO share FROM jsonb_array_elements(holds->'lines') WHERE value->>'line_id'=root.line_id::text;
    IF share IS NULL OR share->>'active_execution_id' IS NOT NULL
        OR share->>'pending_reversal_id' IS DISTINCT FROM line.predecessor_reversal_id::text
        OR (share->>'frozen_quantity')::numeric IS DISTINCT FROM line.quantity
        OR (holds->>'balance_quantity')::numeric<line.quantity THEN
        RAISE EXCEPTION '0165 exact original-cursor scrap frozen share required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(jsonb_agg(jsonb_build_object('serial_id',s.serial_id::text,
        'previous_movement_id',s.previous_movement_id::text,'admission_movement_id',s.admission_movement_id::text,
        'previous_ledger_cursor',t.ledger_cursor,'lifecycle_before','active','lifecycle_after','scrapped') ORDER BY s.serial_id::text),'[]'::jsonb)
        INTO serials FROM public.stock_scrap_serials s JOIN public.inventory_movements m ON m.id=s.previous_movement_id
        JOIN public.inventory_transactions t ON t.id=m.transaction_id WHERE s.scrap_line_id=line.id;
    ids:=share->'frozen_serial_ids';
    FOR binding IN SELECT * FROM public.stock_scrap_files WHERE scrap_line_id=line.id ORDER BY file_id LOOP
        SELECT * INTO file FROM public.files WHERE id=binding.file_id;
        metadata_hash:=encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(file.metadata_jsonb),'UTF8')),'hex');
        IF NOT COALESCE(file.status='available' AND file.uploaded_by=fact->>'actor_user_id'
            AND file.metadata_jsonb->>'purpose'='stock_loss_evidence' AND file.metadata_jsonb->>'provider'='aliyun_oss_v2'
            AND file.metadata_jsonb->>'uploader_person_id'=person
            AND file.metadata_jsonb->'authorization_version'=fact->'authorization_version'
            AND file.created_at<=(file.metadata_jsonb#>>'{completion,verified_at}')::timestamptz
            AND (file.metadata_jsonb#>>'{completion,verified_at}')::timestamptz<=at
            AND binding.created_at=at AND binding.metadata_sha256=metadata_hash,false) THEN
            RAISE EXCEPTION '0165 historical scrap attachment metadata required' USING ERRCODE='23514'; END IF;
        evidence:=evidence||jsonb_build_array(jsonb_build_object('file_id',file.id::text,'original_filename',file.original_filename,
            'sha256',file.sha256,'size_bytes',file.size_bytes,'mime_type',file.mime_type,'metadata_sha256',metadata_hash));
    END LOOP;
    fingerprint:=public.rsc_scrap_policy_basis_0165(account.id,at,fact#>'{plan_jsonb,policy_fingerprint}');
    expected:=jsonb_build_object('schema_version','1.0','stage','scrap_stock_preparation_only','stock_effect','none',
        'intent',intent,'actor_user_id',fact->>'actor_user_id','actor_person_id',person,
        'authorization_version',fact->'authorization_version','operation_id',parent.id::text,'line_id',root.line_id::text,
        'decision_id',COALESCE(line.correction_decision_id,line.original_decision_id)::text,
        'predecessor_reversal_id',line.predecessor_reversal_id::text,'source_account_id',account.id::text,'target_account_id',NULL,
        'owner_org_id',account.owner_org_id::text,'custodian_person_id',account.custodian_person_id::text,
        'location_id',account.location_id::text,'material_id',account.material_id::text,'lot_id',account.lot_id::text,
        'source_condition',account.condition_code,'custody_assignment_id',custody.id::text,
        'quantity',to_char(line.quantity,'FM999999999999990.000'),'serial_ids',ids,'serials',serials,
        'movement_type','scrap','external_boundary_code','stock_operation_scrap','ledger_cursor',cutoff,
        'source_balance_version',holds->'balance_version','source_balance_quantity',holds->'balance_quantity',
        'frozen_holds_before',holds,'policy_fingerprint',fingerprint,'evidence',evidence);
    plan_hash:=encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex');
    IF fact->>'plan_hash' IS DISTINCT FROM plan_hash OR line.plan_hash IS DISTINCT FROM plan_hash
        OR public.rsc_canonical_reconciliation_json_0026(fact->'plan_jsonb') IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(expected)
        OR public.rsc_canonical_reconciliation_json_0026(line.plan_jsonb) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(expected) THEN
        RAISE EXCEPTION '0165 complete historical scrap plan required' USING ERRCODE='23514'; END IF;
    request_hash:=encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(command),'UTF8')),'hex');
    IF public.rsc_canonical_reconciliation_json_0026(fact->'command_jsonb') IS DISTINCT FROM
        public.rsc_canonical_reconciliation_json_0026(command)
        OR fact->>'request_hash' IS DISTINCT FROM request_hash
        OR line.source_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(source),'UTF8')),'hex')
        OR NOT COALESCE(fact->>'request_id' ~ '^[A-Za-z0-9._:-]{8,160}$'
            AND fact->>'idempotency_key_hash' ~ '^[a-f0-9]{64}$' AND (fact->>'authorization_version')::bigint>0
            AND (fact->>'actor_user_id')::uuid::text=fact->>'actor_user_id'
            AND (fact->>'actor_user_id')::uuid<>'00000000-0000-0000-0000-000000000000'::uuid
            AND person::uuid<>'00000000-0000-0000-0000-000000000000'::uuid
            AND length(header.reason) BETWEEN 1 AND 500 AND header.reason=btrim(header.reason,E' \t\n\r')
            AND header.reason !~ '[\x01-\x08\x0B-\x1F]' AND jsonb_array_length(file_ids) BETWEEN 1 AND 20
            AND header.operation_no='SCRAP-'||upper(left(fact->>'idempotency_key_hash',24)),false) THEN
        RAISE EXCEPTION '0165 canonical source-bound scrap command required' USING ERRCODE='23514'; END IF;
    FOREACH key IN ARRAY ARRAY['actor_user_id','authorization_version','request_id','idempotency_key_hash',
        'request_hash','plan_hash','command_jsonb','plan_jsonb','posting_transaction_id'] LOOP
        IF public.rsc_canonical_reconciliation_json_0026(to_jsonb(header)->key) IS DISTINCT FROM
            public.rsc_canonical_reconciliation_json_0026(fact->key) THEN
            RAISE EXCEPTION '0165 scrap parent context must agree' USING ERRCODE='23514'; END IF;
    END LOOP;
    SELECT i.* INTO inverse FROM public.stock_loss_disposition_reversals i
        JOIN public.stock_scrap_recovery_executions r ON r.reversal_id=i.id WHERE r.scrap_line_id=line.id;
    IF inverse.id IS NULL THEN
        PERFORM public.rsc_check_scrap_inventory_edges_with_audit_0165(checked_scrap,audit_ids); RETURN; END IF;
    SELECT * INTO inverse_tx FROM public.inventory_transactions WHERE id=inverse.posting_transaction_id;
    cutoff:=inverse_tx.ledger_cursor-1;at:=inverse.created_at;
    holds:=public.rsc_loss_hold_projection_0159(account.id,cutoff);
    SELECT value INTO share FROM jsonb_array_elements(holds->'lines') WHERE value->>'line_id'=root.line_id::text;
    IF share IS NULL OR share->>'active_execution_id' IS DISTINCT FROM fact->>'id'
        OR share->>'pending_reversal_id' IS NOT NULL OR (share->>'frozen_quantity')::numeric IS DISTINCT FROM 0::numeric THEN
        RAISE EXCEPTION '0165 exact original-cursor recovery share required' USING ERRCODE='23514'; END IF;
    SELECT * INTO custody FROM public.custody_assignments WHERE location_id=account.location_id
        AND valid_from<=at AND (valid_to IS NULL OR valid_to>at);
    IF NOT COALESCE(custody.id=inverse.custody_assignment_id AND custody.custodian_person_id=account.custodian_person_id,false)
        OR (SELECT count(*) FROM public.custody_assignments WHERE location_id=account.location_id
            AND valid_from<=at AND (valid_to IS NULL OR valid_to>at))<>1 THEN
        RAISE EXCEPTION '0165 unique historical recovery custody required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(jsonb_agg((value-'lifecycle_before'-'lifecycle_after')||jsonb_build_object(
        'original_movement_id',line.posting_movement_id::text,'lifecycle_before','scrapped','lifecycle_after','active')
        ORDER BY value->>'serial_id'),'[]'::jsonb) INTO serials FROM jsonb_array_elements(serials);
    fingerprint:=public.rsc_scrap_policy_basis_0165(account.id,at,inverse.plan_jsonb->'policy_fingerprint');
    intent:=inverse.command_jsonb-ARRAY['action','request_id','expected_plan_hash'];
    expected:=jsonb_build_object('schema_version','1.0','stage','scrap_recovery_stock_preparation_only','stock_effect','none',
        'intent',intent,'actor_user_id',inverse.actor_user_id,'actor_person_id',inverse.actor_person_id::text,
        'authorization_version',inverse.authorization_version,'root_disposition_id',root.id::text,
        'original_execution_id',fact->>'id','original_transaction_id',tx.id::text,
        'original_movement_id',line.posting_movement_id::text,'original_ledger_cursor',tx.ledger_cursor,
        'source_account_id',NULL,'target_account_id',account.id::text,'quantity',to_char(line.quantity,'FM999999999999990.000'),
        'custody_assignment_id',custody.id::text,'owner_org_id',account.owner_org_id::text,
        'custodian_person_id',account.custodian_person_id::text,'location_id',account.location_id::text,
        'material_id',account.material_id::text,'lot_id',account.lot_id::text,'target_condition',account.condition_code,
        'ledger_cursor',cutoff,'target_balance_quantity',holds->'balance_quantity','target_balance_version',holds->'balance_version',
        'frozen_holds_before',holds,'restored_line_id',root.line_id::text,'restored_frozen_quantity',to_char(line.quantity,'FM999999999999990.000'),
        'serials',serials,'serial_ids',ids,'policy_fingerprint',fingerprint);
    plan_hash:=encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex');
    IF inverse.plan_hash IS DISTINCT FROM plan_hash OR public.rsc_canonical_reconciliation_json_0026(inverse.plan_jsonb)
        IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(expected) THEN
        RAISE EXCEPTION '0165 complete historical recovery plan required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_check_scrap_inventory_edges_with_audit_0165(checked_scrap,audit_ids);
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_check_scrap_historical_plans_with_audit_0165(uuid,uuid[])
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

-- Only this private entry point creates the proof. Its children are read-only
-- validators: no cache, caller-supplied bypass, or reuse across SQL writes.
-- Lock inventory before audit to retain the posting serialization order.
CREATE FUNCTION public.rsc_check_scrap_historical_plans_0165(checked_scrap uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE audit_ids uuid[];
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 audit proof requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM id FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 inventory head required' USING ERRCODE='23514'; END IF;
    audit_ids:=public.rsc_loss_inventory_audit_members_0159();
    PERFORM public.rsc_check_scrap_historical_plans_with_audit_0165(checked_scrap,audit_ids);
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_check_scrap_historical_plans_0165(uuid)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

CREATE FUNCTION public.rsc_fence_scrap_historical_plans_0165()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE before_row jsonb; after_row jsonb; identifiers uuid[]; accounts uuid[]; transactions uuid[]; checked uuid;
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 historical plans require read committed' USING ERRCODE='23514'; END IF;
    PERFORM id FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 inventory head required' USING ERRCODE='23514'; END IF;
    IF TG_OP<>'INSERT' THEN before_row:=to_jsonb(OLD); END IF;
    IF TG_OP<>'DELETE' THEN after_row:=to_jsonb(NEW); END IF;
    identifiers:=ARRAY[(before_row->>'id')::uuid,(after_row->>'id')::uuid];
    transactions:=ARRAY[(before_row->>'transaction_id')::uuid,(after_row->>'transaction_id')::uuid,
        (before_row->>'posting_transaction_id')::uuid,(after_row->>'posting_transaction_id')::uuid]||
        CASE WHEN TG_TABLE_NAME='inventory_transactions' THEN identifiers ELSE ARRAY[]::uuid[] END;
    accounts:=ARRAY[(before_row->>'from_account_id')::uuid,(after_row->>'from_account_id')::uuid,
        (before_row->>'to_account_id')::uuid,(after_row->>'to_account_id')::uuid,
        (before_row->>'frozen_account_id')::uuid,(after_row->>'frozen_account_id')::uuid,
        (before_row->>'reserved_account_id')::uuid,(after_row->>'reserved_account_id')::uuid,
        (before_row->>'source_account_id')::uuid,(after_row->>'source_account_id')::uuid,
        (before_row->>'target_account_id')::uuid,(after_row->>'target_account_id')::uuid]||
        CASE WHEN TG_TABLE_NAME='stock_accounts' THEN identifiers ELSE ARRAY[]::uuid[] END;
    SELECT accounts||COALESCE(array_agg(DISTINCT a),ARRAY[]::uuid[]) INTO accounts
        FROM public.inventory_movements m CROSS JOIN LATERAL unnest(ARRAY[m.from_account_id,m.to_account_id]) a
        WHERE m.transaction_id=ANY(transactions) OR m.id IN ((before_row->>'movement_id')::uuid,(after_row->>'movement_id')::uuid)
            OR m.id=ANY(identifiers);
    FOR checked IN SELECT DISTINCT s.id FROM public.stock_scrap_lines s JOIN public.stock_accounts a ON a.id=s.frozen_account_id
        WHERE s.id=ANY(identifiers) OR s.operation_id=ANY(identifiers) OR s.loss_line_id=ANY(identifiers)
            OR s.root_disposition_id=ANY(identifiers) OR s.correction_execution_id=ANY(identifiers)
            OR s.correction_decision_id=ANY(identifiers) OR s.original_decision_id=ANY(identifiers)
            OR s.predecessor_reversal_id=ANY(identifiers) OR s.frozen_account_id=ANY(accounts)
            OR s.root_disposition_id IN ((before_row->>'root_disposition_id')::uuid,(after_row->>'root_disposition_id')::uuid)
            OR s.id IN ((before_row->>'scrap_line_id')::uuid,(after_row->>'scrap_line_id')::uuid)
            OR (TG_TABLE_NAME='stock_operation_orders' AND EXISTS(SELECT 1 FROM public.stock_operation_lines l
                WHERE l.operation_id=ANY(identifiers) AND l.reserved_account_id=s.frozen_account_id))
            OR (TG_TABLE_NAME='stock_operation_serials' AND EXISTS(SELECT 1 FROM public.stock_operation_lines l
                WHERE l.id IN ((before_row->>'line_id')::uuid,(after_row->>'line_id')::uuid) AND l.reserved_account_id=s.frozen_account_id))
            OR (TG_TABLE_NAME='stock_loss_headquarters_reviews' AND EXISTS(SELECT 1 FROM public.stock_loss_headquarters_decisions d
                WHERE d.id=s.original_decision_id AND d.review_id=ANY(identifiers)))
            OR (TG_TABLE_NAME='material_inventory_policies' AND a.material_id IN (
                (before_row->>'material_id')::uuid,(after_row->>'material_id')::uuid))
            OR (TG_TABLE_NAME='custody_assignments' AND a.location_id IN (
                (before_row->>'location_id')::uuid,(after_row->>'location_id')::uuid))
            OR (TG_TABLE_NAME='files' AND EXISTS(SELECT 1 FROM public.stock_scrap_files f WHERE f.scrap_line_id=s.id AND f.file_id=ANY(identifiers)))
        ORDER BY s.id LOOP
        PERFORM public.rsc_check_scrap_historical_plans_0165(checked);
    END LOOP;
    RETURN COALESCE(NEW,OLD);
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_fence_scrap_historical_plans_0165()
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

DO $install$
DECLARE name text;
BEGIN
    FOREACH name IN ARRAY ARRAY['stock_scrap_lines','stock_scrap_serials','stock_scrap_files','stock_scrap_recovery_executions',
        'stock_loss_dispositions','stock_loss_correction_executions','stock_loss_disposition_reversals','stock_loss_correction_decisions',
        'stock_loss_headquarters_decisions','stock_loss_headquarters_reviews','stock_operation_orders','stock_operation_lines',
        'stock_operation_serials','inventory_transactions','inventory_movements','inventory_movement_serials',
        'stock_accounts','material_inventory_policies','custody_assignments','files'] LOOP
        EXECUTE format('CREATE CONSTRAINT TRIGGER trg_scrap_historical_plans_0165 AFTER INSERT OR UPDATE OR DELETE ON public.%I '
            'DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.rsc_fence_scrap_historical_plans_0165()',name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER trg_scrap_historical_plans_0165',name);
    END LOOP;
END;
$install$;

-- Candidate execution evidence; retains the original upload-audit proof.
CREATE FUNCTION public.rsc_check_scrap_execution_files_with_audit_0165(checked_scrap uuid, audit_ids uuid[])
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE app record; binding public.stock_scrap_files%ROWTYPE;
    file public.files%ROWTYPE; metadata jsonb; completion jsonb; expected jsonb;
    file_key text; verified timestamptz;  creation public.audit_events%ROWTYPE; completed public.audit_events%ROWTYPE;
BEGIN
    IF audit_ids IS NULL THEN
        RAISE EXCEPTION '0165 internal audit proof required' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.rsc_scrap_recovery_source_0165(checked_scrap);
    SELECT o.*,CASE WHEN l.source_kind='original' THEN r.executor_person_id ELSE c.actor_person_id END AS actor_person_id
        INTO app FROM public.stock_scrap_lines l JOIN public.stock_operation_orders o ON o.id=l.operation_id
        JOIN public.stock_loss_dispositions r ON r.id=l.root_disposition_id
        LEFT JOIN public.stock_loss_correction_executions c ON c.id=l.correction_execution_id WHERE l.id=checked_scrap;
    IF app.id IS NULL THEN RAISE EXCEPTION '0165 scrap execution required for files' USING ERRCODE='23514'; END IF;
    FOR binding IN SELECT * FROM public.stock_scrap_files WHERE scrap_line_id=checked_scrap ORDER BY file_id LOOP
        SELECT * INTO file FROM public.files WHERE id=binding.file_id FOR SHARE;
        metadata:=file.metadata_jsonb; completion:=metadata->'completion';
        file_key:='formal-files/v1/stock_loss_evidence/'||substr(replace(file.id::text,'-',''),1,2)||'/'||replace(file.id::text,'-','');
        IF file.id IS NULL OR file.status IS DISTINCT FROM 'available'
           OR file.uploaded_by IS DISTINCT FROM app.actor_user_id
           OR file.storage_key IS DISTINCT FROM file_key
           OR NOT COALESCE(file.sha256 ~ '^[a-f0-9]{64}$' AND file.size_bytes BETWEEN 1 AND 125829120,false)
           OR NOT COALESCE(jsonb_typeof(completion)='object'
                AND completion->>'etag_sha256' ~ '^[a-f0-9]{64}$'
                AND completion->>'head_manifest_sha256' ~ '^[a-f0-9]{64}$'
                AND completion->>'verified_at' ~ '(Z|[+-][0-9]{2}:[0-9]{2})$'
                AND metadata->>'idempotency_key_hash' ~ '^[a-f0-9]{64}$',false) THEN
            RAISE EXCEPTION '0165 completed scrap upload required' USING ERRCODE='23514';
        END IF;
        BEGIN verified:=(completion->>'verified_at')::timestamptz;
        EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
            RAISE EXCEPTION '0165 scrap upload timestamp invalid' USING ERRCODE='23514';
        END;
        IF NOT COALESCE(file.created_at<=verified AND verified<=app.created_at,false)
           OR binding.created_at IS DISTINCT FROM app.created_at THEN
            RAISE EXCEPTION '0165 scrap upload must precede execution' USING ERRCODE='23514';
        END IF;
        IF NOT COALESCE(length(file.original_filename) BETWEEN 1 AND 200
           AND octet_length(file.original_filename)<=255
           AND file.original_filename=normalize(file.original_filename,NFC)
           AND file.original_filename=btrim(file.original_filename)
           AND position('/' IN file.original_filename)=0 AND position(chr(92) IN file.original_filename)=0
           AND EXISTS(SELECT 1 FROM (VALUES ('application/pdf','.pdf'),('image/jpeg','.jpg'),('image/jpeg','.jpeg'),
                ('image/png','.png'),('image/webp','.webp'),('image/heic','.heic'),('image/heif','.heif'),
                ('video/mp4','.mp4'),('video/quicktime','.mov')) allowed(mime,suffix)
                WHERE file.mime_type=allowed.mime AND right(lower(file.original_filename),length(allowed.suffix))=allowed.suffix),false) THEN
            RAISE EXCEPTION '0165 scrap file shape invalid' USING ERRCODE='23514'; END IF;
        expected:=jsonb_build_object('schema','cloud_oam.formal_file_upload_intent.v1',
            'file_id',file.id::text,'storage_key',file_key,'purpose','stock_loss_evidence',
            'provider','aliyun_oss_v2','uploader_user_id',app.actor_user_id,
            'uploader_person_id',app.actor_person_id::text,'authorization_version',app.authorization_version,
            'idempotency_key_hash',metadata->>'idempotency_key_hash',
            'request_sha256',encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(
                jsonb_build_object('mime_type',file.mime_type,'original_filename',file.original_filename,
                    'purpose','stock_loss_evidence','sha256',file.sha256,'size_bytes',file.size_bytes)),'UTF8')),'hex'),
            'completion',jsonb_build_object('etag_sha256',completion->>'etag_sha256',
                'head_manifest_sha256',completion->>'head_manifest_sha256','verified_at',completion->>'verified_at'));
        IF public.rsc_canonical_reconciliation_json_0026(metadata) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(expected)
           OR binding.metadata_sha256 IS DISTINCT FROM encode(sha256(convert_to(
                public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
            RAISE EXCEPTION '0165 exact scrap upload manifest required' USING ERRCODE='23514';
        END IF;
        -- HEAD may contain extra provider metadata, so prove its exact digest
        -- against the original completed-upload audit rather than guess keys.
        SELECT * INTO creation FROM public.audit_events WHERE aggregate_type='formal_file'
            AND aggregate_id=file.id::text AND action='file.upload_intent.created';
        SELECT * INTO completed FROM public.audit_events WHERE aggregate_type='formal_file'
            AND aggregate_id=file.id::text AND action='file.upload_completed';
        expected:=jsonb_build_object('mime_type',file.mime_type,'purpose','stock_loss_evidence',
            'sha256',file.sha256,'size_bytes',file.size_bytes);
        IF (SELECT count(*) FROM public.audit_events WHERE aggregate_type='formal_file'
                AND aggregate_id=file.id::text AND action='file.upload_intent.created')<>1
           OR (SELECT count(*) FROM public.audit_events WHERE aggregate_type='formal_file'
                AND aggregate_id=file.id::text AND action='file.upload_completed')<>1
           OR NOT COALESCE(creation.id=ANY(audit_ids) AND completed.id=ANY(audit_ids)
                AND creation.actor_user_id=app.actor_user_id AND completed.actor_user_id=app.actor_user_id
                AND creation.occurred_at=file.created_at AND completed.occurred_at=verified
                AND creation.stream_version<completed.stream_version
                AND creation.created_at>=creation.occurred_at AND completed.created_at>=completed.occurred_at
                AND completed.created_at<=app.created_at,false)
           OR NOT (creation.before_jsonb IS NULL OR creation.before_jsonb='null'::jsonb)
           OR public.rsc_canonical_reconciliation_json_0026(creation.after_jsonb) IS DISTINCT FROM
                public.rsc_canonical_reconciliation_json_0026(expected||jsonb_build_object('status','pending'))
           OR completed.before_jsonb IS DISTINCT FROM jsonb_build_object('status','pending')
           OR public.rsc_canonical_reconciliation_json_0026(completed.after_jsonb) IS DISTINCT FROM
                public.rsc_canonical_reconciliation_json_0026(expected||jsonb_build_object('status','available',
                    'head_manifest_sha256',completion->>'head_manifest_sha256'))
           OR NOT EXISTS(SELECT 1 FROM public.audit_events WHERE aggregate_type='stock_operation_scrap'
                AND aggregate_id=app.id::text AND id=ANY(audit_ids) AND stream_version>completed.stream_version) THEN
            RAISE EXCEPTION '0165 original upload creation and completion audits required' USING ERRCODE='23514';
        END IF;
    END LOOP;
END;
$function$;
