-- Private values scoped to one read-only history-graph call. The original
-- complete proof runs for every distinct fact; no session or table cache.
CREATE FUNCTION public.rsc_build_scrap_history_proof_0165(checked_root uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE item record; plans jsonb:='{}'::jsonb; key text; plan jsonb; audit_ids uuid[];
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 history proof requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM id FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 inventory head required' USING ERRCODE='23514'; END IF;
    IF checked_root IS NULL OR NOT EXISTS(SELECT 1 FROM public.stock_loss_dispositions WHERE id=checked_root) THEN
        RAISE EXCEPTION '0165 retained proof root required' USING ERRCODE='23514'; END IF;
    audit_ids:=public.rsc_loss_inventory_audit_members_0159();
    PERFORM public.rsc_scrap_upstream_with_audit_0165(checked_root,audit_ids);
    FOR item IN
        SELECT 'original' AS kind,id FROM public.stock_loss_dispositions
            WHERE id=checked_root AND disposition='scrap'
        UNION ALL SELECT 'correction',id FROM public.stock_loss_correction_executions
            WHERE root_disposition_id=checked_root AND disposition='scrap'
        UNION ALL SELECT 'inverse',id FROM public.stock_loss_disposition_reversals
            WHERE root_disposition_id=checked_root AND scrap_line_id IS NOT NULL
        ORDER BY kind,id
    LOOP
        key:=item.kind||':'||item.id::text;
        IF plans ? key THEN RAISE EXCEPTION '0165 duplicate proof fact' USING ERRCODE='23514'; END IF;
        plan:=public.rsc_scrap_fact_with_root_proof_0165(item.kind,item.id,checked_root,audit_ids);
        IF jsonb_typeof(plan) IS DISTINCT FROM 'object' THEN
            RAISE EXCEPTION '0165 complete fact plan required' USING ERRCODE='23514'; END IF;
        plans:=plans||jsonb_build_object(key,plan);
    END LOOP;
    RETURN jsonb_build_object('schema','rsc.private_scrap_history_proof.v1',
        'root_disposition_id',checked_root::text,'plans',plans);
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_build_scrap_history_proof_0165(uuid)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox,star_oam_backup;

CREATE FUNCTION public.rsc_scrap_history_from_proof_0165(kind text, checked_fact uuid, checked_root uuid, checked_proof jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE plan jsonb;
BEGIN
    IF kind IS NULL OR kind NOT IN ('original','correction','inverse') OR checked_fact IS NULL
       OR checked_root IS NULL OR checked_proof IS NULL
       OR checked_proof->>'schema' IS DISTINCT FROM 'rsc.private_scrap_history_proof.v1'
       OR checked_proof->>'root_disposition_id' IS DISTINCT FROM checked_root::text THEN
        RAISE EXCEPTION '0165 exact private history proof scope required' USING ERRCODE='23514'; END IF;
    plan:=checked_proof->'plans'->(kind||':'||checked_fact::text);
    IF jsonb_typeof(plan) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION '0165 verified history fact required' USING ERRCODE='23514'; END IF;
    RETURN plan;
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_scrap_history_from_proof_0165(text,uuid,uuid,jsonb)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox,star_oam_backup;

CREATE FUNCTION public.rsc_loss_requests_with_proof_0165(checked_root uuid, checked_proof jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE root public.stock_loss_dispositions%ROWTYPE; parent public.stock_operation_orders%ROWTYPE;
    inverse public.stock_loss_disposition_reversals%ROWTYPE;
    approval public.stock_loss_correction_decisions%ROWTYPE;
    target jsonb; item record; body jsonb; intent jsonb; expected jsonb; snapshot jsonb;
    all_requests jsonb; returned_requests jsonb:='[]'::jsonb;
BEGIN
    -- This also takes the shared inventory head lock and validates all future
    -- edges; an early historical cursor cannot conceal a malformed successor.
    snapshot:=public.rsc_loss_chain_projection_0159(checked_root,NULL);
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=checked_root;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT jsonb_agg(q.body ORDER BY q.kind,q.body->>'id') INTO all_requests FROM (
        SELECT 'reverse_loss' AS kind,to_jsonb(r) AS body FROM public.stock_loss_disposition_reversals r
        UNION ALL SELECT 'approve_loss_correction',to_jsonb(d) FROM public.stock_loss_correction_decisions d
        UNION ALL SELECT 'correct_loss',to_jsonb(c) FROM public.stock_loss_correction_executions c) q;
    FOR item IN
        SELECT 'reverse_loss' AS kind,to_jsonb(r) AS body FROM public.stock_loss_disposition_reversals r WHERE root_disposition_id=root.id
        UNION ALL SELECT 'approve_loss_correction',to_jsonb(d) FROM public.stock_loss_correction_decisions d WHERE root_disposition_id=root.id
        UNION ALL SELECT 'correct_loss',to_jsonb(c) FROM public.stock_loss_correction_executions c WHERE root_disposition_id=root.id
    LOOP
        body:=item.body;
        IF NOT COALESCE(
            body->>'request_id' ~ '^[A-Za-z0-9._:-]{8,160}$'
            AND body->>'request_hash' ~ '^[a-f0-9]{64}$'
            AND body->>'idempotency_key_hash' ~ '^[a-f0-9]{64}$'
            AND body->>'actor_user_id' ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
            AND body->>'actor_user_id'<>'00000000-0000-0000-0000-000000000000'
            AND body->>'actor_person_id'<>'00000000-0000-0000-0000-000000000000'
            AND (body->>'authorization_version')::bigint>0
            AND (body->>'created_at')::timestamptz>=root.created_at
            AND (body->>'created_at')::timestamptz<=clock_timestamp()
            AND length(body->>'reason') BETWEEN 1 AND 500
            AND btrim(body->>'reason',chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(28)||chr(29)||chr(30)||chr(31)||chr(32)||chr(133)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288))=body->>'reason',false)
           OR EXISTS(SELECT 1 FROM generate_series(1,length(body->>'reason')) p
                WHERE ascii(substr(body->>'reason',p,1))<32 AND ascii(substr(body->>'reason',p,1)) NOT IN (9,10))
           OR (SELECT count(*) FROM jsonb_array_elements(all_requests) r WHERE
                r->>'idempotency_key_hash'=body->>'idempotency_key_hash')<>1
           OR (SELECT count(*) FROM jsonb_array_elements(all_requests) r WHERE
                r->>'actor_user_id'=body->>'actor_user_id' AND r->>'request_id'=body->>'request_id')<>1 THEN
            RAISE EXCEPTION '0159 complete unique historical request context required' USING ERRCODE='23514'; END IF;
        IF (item.kind='reverse_loss' AND body->>'scrap_line_id' IS NOT NULL)
            OR (item.kind='correct_loss' AND body->>'disposition'='scrap') THEN
            PERFORM public.rsc_scrap_history_from_proof_0165(
                CASE item.kind WHEN 'reverse_loss' THEN 'inverse' ELSE 'correction' END,(body->>'id')::uuid,root.id,checked_proof);
            returned_requests:=returned_requests||jsonb_build_array(jsonb_build_object(
                'id',body->>'id','action',body#>>'{command_jsonb,action}','request_hash',body->>'request_hash'));
            CONTINUE;
        END IF;
        intent:=jsonb_build_object('root_disposition_id',root.id::text,'expected_root_request_hash',root.request_hash,
            'expected_submission_plan_hash',parent.plan_hash,'reason',body->>'reason');
        IF item.kind='reverse_loss' THEN
            IF body->>'reversed_correction_id' IS NULL THEN target:=to_jsonb(root);
            ELSE SELECT to_jsonb(c) INTO target FROM public.stock_loss_correction_executions c
                WHERE c.id=(body->>'reversed_correction_id')::uuid AND c.root_disposition_id=root.id; END IF;
            IF target IS NULL OR body->>'original_transaction_id' IS DISTINCT FROM target->>'posting_transaction_id'
               OR body->>'original_movement_id' IS DISTINCT FROM target->>'posting_movement_id'
               OR (body->>'created_at')::timestamptz<(target->>'created_at')::timestamptz THEN
                RAISE EXCEPTION '0159 exact reversed execution request required' USING ERRCODE='23514'; END IF;
            intent:=intent||jsonb_build_object('reversed_correction_id',body->'reversed_correction_id',
                'expected_execution_request_hash',target->>'request_hash');
        ELSE
            SELECT * INTO inverse FROM public.stock_loss_disposition_reversals
                WHERE id=(body->>'reversal_id')::uuid AND root_disposition_id=root.id;
            IF inverse.id IS NULL OR (body->>'created_at')::timestamptz<inverse.created_at THEN
                RAISE EXCEPTION '0159 exact inverse request parent required' USING ERRCODE='23514'; END IF;
            intent:=intent||jsonb_build_object('reversal_id',inverse.id::text,'expected_reversal_hash',inverse.request_hash);
            IF item.kind='approve_loss_correction' THEN
                IF body->>'expected_reversal_hash' IS DISTINCT FROM inverse.request_hash
                   OR body->>'actor_user_id'=parent.actor_user_id OR body->>'actor_person_id'=parent.requester_id::text THEN
                    RAISE EXCEPTION '0159 independent correction approval required' USING ERRCODE='23514'; END IF;
                intent:=intent||jsonb_build_object('disposition',body->>'disposition');
            ELSE
                SELECT * INTO approval FROM public.stock_loss_correction_decisions
                    WHERE id=(body->>'correction_decision_id')::uuid AND root_disposition_id=root.id AND reversal_id=inverse.id;
                IF approval.id IS NULL OR approval.expected_reversal_hash IS DISTINCT FROM inverse.request_hash
                   OR body->>'disposition' IS DISTINCT FROM approval.disposition
                   OR (body->>'created_at')::timestamptz<approval.created_at THEN
                    RAISE EXCEPTION '0159 exact independent decision request required' USING ERRCODE='23514'; END IF;
                intent:=intent||jsonb_build_object('correction_decision_id',approval.id::text,
                    'expected_correction_decision_hash',approval.request_hash);
            END IF;
        END IF;
        expected:=jsonb_build_object('schema_version',1,'action',item.kind,'request_id',body->>'request_id','intent',intent);
        IF item.kind<>'approve_loss_correction' THEN
            IF NOT COALESCE(body->>'plan_hash' ~ '^[a-f0-9]{64}$',false) THEN
                RAISE EXCEPTION '0159 exact plan fingerprint required' USING ERRCODE='23514'; END IF;
            expected:=expected||jsonb_build_object('expected_plan_hash',body->>'plan_hash');
        END IF;
        IF body->'command_jsonb' IS DISTINCT FROM expected
           OR public.rsc_canonical_reconciliation_json_0026(body->'command_jsonb') IS DISTINCT FROM
                public.rsc_canonical_reconciliation_json_0026(expected)
           OR body->>'request_hash' IS DISTINCT FROM encode(sha256(convert_to(
                public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
            RAISE EXCEPTION '0159 canonical historical command mismatch' USING ERRCODE='23514'; END IF;
        returned_requests:=returned_requests||jsonb_build_array(jsonb_build_object(
            'id',body->>'id','action',item.kind,'request_hash',body->>'request_hash'));
    END LOOP;
    IF snapshot IS DISTINCT FROM public.rsc_loss_chain_projection_0159(checked_root,NULL) THEN
        RAISE EXCEPTION '0159 request graph changed during proof' USING ERRCODE='23514'; END IF;
    RETURN (SELECT COALESCE(jsonb_agg(r ORDER BY r->>'id'),'[]'::jsonb) FROM jsonb_array_elements(returned_requests) r);
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_loss_requests_with_proof_0165(uuid,jsonb)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox,star_oam_backup;

CREATE FUNCTION public.rsc_loss_events_with_proof_0165(checked_root uuid, checked_proof jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE root public.stock_loss_dispositions%ROWTYPE; parent public.stock_operation_orders%ROWTYPE;
    tx public.inventory_transactions%ROWTYPE; item record; fact jsonb; body jsonb; common jsonb;
    aggregate text; kind text; from_state text; to_state text; key text; reference text; suffix text;
    at timestamptz; identifier uuid; actual jsonb; audit_ids uuid[]; requests jsonb; audit_version bigint;
    inventory_body jsonb; state_body jsonb; outbox_body jsonb; posting_count integer:=0;
BEGIN
    requests:=public.rsc_loss_requests_with_proof_0165(checked_root,checked_proof);
    audit_ids:=public.rsc_loss_inventory_audit_members_0159();
    SELECT version INTO audit_version FROM public.audit_chain_heads WHERE stream_key='inventory';
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=checked_root;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    FOR item IN
        SELECT 'inverse' AS category,to_jsonb(r) AS fact FROM public.stock_loss_disposition_reversals r WHERE root_disposition_id=root.id
        UNION ALL SELECT 'approval',to_jsonb(d) FROM public.stock_loss_correction_decisions d WHERE root_disposition_id=root.id
        UNION ALL SELECT 'correction',to_jsonb(c) FROM public.stock_loss_correction_executions c WHERE root_disposition_id=root.id
    LOOP
        fact:=item.fact;identifier:=(fact->>'id')::uuid;at:=(fact->>'created_at')::timestamptz;
        IF (item.category='inverse' AND fact->>'scrap_line_id' IS NOT NULL)
            OR (item.category='correction' AND fact->>'disposition'='scrap') THEN
            PERFORM public.rsc_scrap_history_from_proof_0165(item.category,identifier,root.id,checked_proof);
            CONTINUE;
        END IF;
        common:=jsonb_build_object('root_disposition_id',root.id::text,'operation_id',parent.id::text,
            'line_id',root.line_id::text,'original_headquarters_decision_id',root.headquarters_decision_id::text,
            'requester_person_id',parent.requester_id::text,'actor_user_id',fact->>'actor_user_id',
            'actor_person_id',fact->>'actor_person_id','authorization_version',(fact->>'authorization_version')::bigint,
            'reason',fact->>'reason','request_id',fact->>'request_id','request_hash',fact->>'request_hash');
        IF item.category='approval' THEN
            aggregate:='stock_loss_correction_decision';kind:='stock_loss.correction_approved';
            from_state:='awaiting_headquarters';to_state:='approved';
            body:=common||jsonb_build_object('correction_decision_id',identifier::text,'reversal_id',fact->>'reversal_id',
                'expected_reversal_hash',fact->>'expected_reversal_hash','disposition',fact->>'disposition',
                'approval_stage','approved','stock_effect','none');
            IF EXISTS(SELECT 1 FROM public.inventory_transactions WHERE idempotency_key_hash=fact->>'idempotency_key_hash'
                OR (source_document_type=aggregate AND source_document_id=identifier::text)) THEN
                RAISE EXCEPTION '0159 approval cannot post inventory' USING ERRCODE='23514'; END IF;
        ELSE
            common:=common||jsonb_build_object('posting_transaction_id',fact->>'posting_transaction_id',
                'posting_movement_id',fact->>'posting_movement_id','source_account_id',fact->'source_account_id',
                'target_account_id',fact->'target_account_id','quantity',to_char((fact->>'quantity')::numeric,'FM999999999999990.000'),
                'plan_hash',fact->>'plan_hash','status','posted');
            from_state:='pending';to_state:='posted';
            IF item.category='inverse' THEN
                aggregate:='stock_loss_disposition_reversal';kind:='stock_loss.disposition_reversed';
                body:=common||jsonb_build_object('reversal_id',identifier::text,
                    'original_execution_id',COALESCE(fact->>'reversed_correction_id',root.id::text),
                    'reversed_correction_id',fact->'reversed_correction_id','original_transaction_id',fact->>'original_transaction_id',
                    'original_movement_id',fact->>'original_movement_id','stock_effect','restores_original_frozen_share');
            ELSE
                aggregate:='stock_loss_correction_execution';kind:='stock_loss.correction_posted';
                body:=common||jsonb_build_object('correction_execution_id',identifier::text,
                    'correction_decision_id',fact->>'correction_decision_id','reversal_id',fact->>'reversal_id',
                    'disposition',fact->>'disposition','return_operation_id',fact->'return_operation_id',
                    'return_fulfillment_required',fact->>'disposition'='return_to_region',
                    'stock_effect',CASE fact->>'disposition' WHEN 'restore_available' THEN 'frozen_to_available'
                        WHEN 'convert_used' THEN 'frozen_to_used' WHEN 'convert_damaged' THEN 'frozen_to_damaged'
                        WHEN 'return_to_region' THEN 'frozen_to_return_pending' WHEN 'scrap' THEN 'removed_from_managed_assets' END);
            END IF;
        END IF;
        key:=kind||':'||identifier::text;
        IF (SELECT count(*) FROM public.audit_events WHERE aggregate_type=aggregate AND aggregate_id=identifier::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.audit_events e WHERE e.id=ANY(audit_ids) AND e.stream_key='inventory'
                AND e.aggregate_type=aggregate AND e.aggregate_id=identifier::text AND e.action=kind
                AND e.actor_user_id=fact->>'actor_user_id' AND e.request_id=fact->>'request_id'
                AND e.before_jsonb='{}'::jsonb AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.after_jsonb)=public.rsc_canonical_reconciliation_json_0026(body))
           OR (SELECT count(*) FROM public.state_transition_events WHERE aggregate_type=aggregate AND aggregate_id=identifier::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.state_transition_events e WHERE e.aggregate_type=aggregate AND e.aggregate_id=identifier::text
                AND e.from_status=from_state AND e.to_status=to_state AND e.actor_id=fact->>'actor_user_id'
                AND e.reason=kind AND e.idempotency_key=key AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.metadata_jsonb)=public.rsc_canonical_reconciliation_json_0026(body))
           OR (SELECT count(*) FROM public.outbox_events WHERE aggregate_type=aggregate AND aggregate_id=identifier::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.outbox_events e WHERE e.aggregate_type=aggregate AND e.aggregate_id=identifier::text
                AND e.event_type=kind AND e.idempotency_key=key AND e.created_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.payload_jsonb)=public.rsc_canonical_reconciliation_json_0026(body))
           OR (SELECT count(*) FROM public.notification_events WHERE business_type=aggregate AND business_id=identifier::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.notification_events e WHERE e.business_type=aggregate AND e.business_id=identifier::text
                AND e.event_type=kind AND e.dedup_key=key AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.payload_jsonb)=public.rsc_canonical_reconciliation_json_0026(body)
                AND e.target_manifest_sha256=encode(sha256(convert_to('notification-person-targets.v1'||chr(10)||parent.requester_id::text,'UTF8')),'hex')
                AND (SELECT count(*) FROM public.notification_person_targets WHERE event_id=e.id)=1
                AND EXISTS(SELECT 1 FROM public.notification_person_targets WHERE event_id=e.id AND person_id=parent.requester_id)) THEN
            RAISE EXCEPTION '0159 exact canonical domain event bundle required' USING ERRCODE='23514'; END IF;
    END LOOP;
    FOR item IN
        SELECT false AS inverse,to_jsonb(r) AS fact FROM public.stock_loss_dispositions r WHERE id=root.id
        UNION ALL SELECT true,to_jsonb(r) FROM public.stock_loss_disposition_reversals r WHERE root_disposition_id=root.id
        UNION ALL SELECT false,to_jsonb(c) FROM public.stock_loss_correction_executions c WHERE root_disposition_id=root.id
    LOOP
        fact:=item.fact;SELECT * INTO tx FROM public.inventory_transactions WHERE id=(fact->>'posting_transaction_id')::uuid;
        at:=tx.posted_at;suffix:=CASE WHEN item.inverse THEN 'reversed' ELSE 'posted' END;
        kind:='inventory.transaction.'||suffix;
        IF tx.posted_at IS NULL OR tx.created_at IS DISTINCT FROM tx.posted_at
           OR tx.idempotency_key_hash IS DISTINCT FROM fact->>'idempotency_key_hash'
           OR (fact->>'created_at')::timestamptz>tx.posted_at
           OR NOT EXISTS(SELECT 1 FROM public.inventory_movements WHERE id=(fact->>'posting_movement_id')::uuid AND created_at=at)
           OR EXISTS(SELECT 1 FROM public.inventory_movement_serials WHERE movement_id=(fact->>'posting_movement_id')::uuid
                AND created_at IS DISTINCT FROM at) THEN
            RAISE EXCEPTION '0159 exact posting time and request key required' USING ERRCODE='23514'; END IF;
        reference:='inventory-request-'||encode(sha256(convert_to('cloud_oam.inventory.request.v1','UTF8')||decode('00','hex')||convert_to(fact->>'request_id','UTF8')),'hex');
        inventory_body:=jsonb_build_object('ledger_cursor',tx.ledger_cursor,'movement_count',1,'movement_type',tx.movement_type,
            'posting_key',tx.posting_key,'reversed_transaction_id',tx.reversed_transaction_id::text,'status','posted');
        state_body:=jsonb_build_object('ledger_cursor',tx.ledger_cursor,'movement_type',tx.movement_type,'request_reference',reference);
        outbox_body:=jsonb_build_object('transaction_id',tx.id::text,'transaction_no',tx.transaction_no,'movement_type',tx.movement_type,
            'ledger_cursor',tx.ledger_cursor,'reversed_transaction_id',tx.reversed_transaction_id::text);
        IF (SELECT count(*) FROM public.audit_events WHERE aggregate_type='inventory_transaction' AND aggregate_id=tx.id::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.audit_events e WHERE e.id=ANY(audit_ids) AND e.stream_key='inventory'
                AND e.aggregate_type='inventory_transaction' AND e.aggregate_id=tx.id::text AND e.action=kind
                AND e.actor_user_id=tx.actor_user_id AND e.request_id=reference
                AND (e.before_jsonb IS NULL OR e.before_jsonb='null'::jsonb) AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.after_jsonb)=public.rsc_canonical_reconciliation_json_0026(inventory_body))
           OR (SELECT count(*) FROM public.state_transition_events WHERE aggregate_type='inventory_transaction' AND aggregate_id=tx.id::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.state_transition_events e WHERE e.aggregate_type='inventory_transaction' AND e.aggregate_id=tx.id::text
                AND e.from_status IS NULL AND e.to_status='posted' AND e.actor_id=tx.actor_user_id AND e.reason='inventory_transaction_'||suffix
                AND e.idempotency_key='inventory-state-'||encode(sha256(convert_to('cloud_oam.inventory.state.v1','UTF8')||decode('00','hex')||convert_to(tx.id::text,'UTF8')||decode('00','hex')||convert_to(suffix,'UTF8')),'hex')
                AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.metadata_jsonb)=public.rsc_canonical_reconciliation_json_0026(state_body))
           OR (SELECT count(*) FROM public.outbox_events WHERE aggregate_type='inventory_transaction' AND aggregate_id=tx.id::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.outbox_events e WHERE e.aggregate_type='inventory_transaction' AND e.aggregate_id=tx.id::text
                AND e.event_type=kind AND e.idempotency_key='inventory-outbox-'||encode(sha256(convert_to('cloud_oam.inventory.outbox.v1','UTF8')||decode('00','hex')||convert_to(tx.id::text,'UTF8')||decode('00','hex')||convert_to(suffix,'UTF8')),'hex')
                AND e.created_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.payload_jsonb)=public.rsc_canonical_reconciliation_json_0026(outbox_body)) THEN
            RAISE EXCEPTION '0159 exact canonical inventory posting bundle required' USING ERRCODE='23514'; END IF;
        posting_count:=posting_count+1;
    END LOOP;
    IF requests IS DISTINCT FROM public.rsc_loss_requests_with_proof_0165(checked_root,checked_proof)
       OR audit_version IS DISTINCT FROM (SELECT version FROM public.audit_chain_heads WHERE stream_key='inventory') THEN
        RAISE EXCEPTION '0159 changed event proof snapshot' USING ERRCODE='23514'; END IF;
    RETURN jsonb_build_object('root_disposition_id',root.id::text,'candidate_events',jsonb_array_length(requests),
        'posting_events',posting_count,'audit_version',audit_version);
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_loss_events_with_proof_0165(uuid,jsonb)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox,star_oam_backup;

CREATE FUNCTION public.rsc_loss_inverse_with_proof_0165(checked_inverse uuid, checked_proof jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE inverse public.stock_loss_disposition_reversals%ROWTYPE; root public.stock_loss_dispositions%ROWTYPE;
    parent public.stock_operation_orders%ROWTYPE; tx public.inventory_transactions%ROWTYPE;
    original_tx public.inventory_transactions%ROWTYPE; source public.stock_accounts%ROWTYPE; target public.stock_accounts%ROWTYPE;
    custody public.custody_assignments%ROWTYPE; policy public.material_inventory_policies%ROWTYPE;
    observed bigint; cutoff bigint; source_amount numeric; target_amount numeric; source_version bigint; target_version bigint;
    serial_ids jsonb; serial_basis jsonb:='[]'::jsonb; holds jsonb; share jsonb; recorded jsonb; fingerprint jsonb;
    expected jsonb; command jsonb; identifier uuid; current_sn record; prior_sn record;
    effective_from_text text; effective_to_text text;
    selected_execution uuid; selected_transaction uuid; selected_movement uuid;
    selected_target uuid; selected_kind text; selected_quantity numeric;
    correction public.stock_loss_correction_executions%ROWTYPE; return_boundary jsonb:=NULL;
BEGIN
    SELECT * INTO inverse FROM public.stock_loss_disposition_reversals WHERE id=checked_inverse;
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=inverse.root_disposition_id;
    IF inverse.id IS NULL OR root.id IS NULL THEN
        RAISE EXCEPTION 'later inverse retained root required' USING ERRCODE='23514'; END IF;
    IF inverse.reversed_correction_id IS NULL THEN
        selected_execution:=root.id; selected_transaction:=root.posting_transaction_id;
        selected_movement:=root.posting_movement_id; selected_target:=root.target_account_id;
        selected_kind:=root.disposition; selected_quantity:=root.quantity;
    ELSE
        SELECT * INTO correction FROM public.stock_loss_correction_executions WHERE id=inverse.reversed_correction_id;
        IF correction.id IS NULL OR correction.root_disposition_id IS DISTINCT FROM root.id THEN
            RAISE EXCEPTION 'later inverse exact selected correction required' USING ERRCODE='23514'; END IF;
        selected_execution:=correction.id; selected_transaction:=correction.posting_transaction_id;
        selected_movement:=correction.posting_movement_id; selected_target:=correction.target_account_id;
        selected_kind:=correction.disposition; selected_quantity:=correction.quantity;
    END IF;
    IF selected_kind='scrap' THEN
        RETURN public.rsc_scrap_history_from_proof_0165('inverse',inverse.id,root.id,checked_proof);
    END IF;
    IF selected_kind NOT IN ('restore_available','convert_used','convert_damaged','return_to_region')
       OR (selected_kind='return_to_region' AND inverse.reversed_correction_id IS NOT NULL)
       OR selected_transaction IS NULL OR selected_movement IS NULL OR selected_target IS NULL
       OR selected_quantity IS DISTINCT FROM root.quantity OR inverse.quantity IS DISTINCT FROM root.quantity
       OR inverse.original_transaction_id IS DISTINCT FROM selected_transaction
       OR inverse.original_movement_id IS DISTINCT FROM selected_movement THEN
        RAISE EXCEPTION 'later inverse exact account posting required' USING ERRCODE='23514'; END IF;
    IF selected_kind='return_to_region' THEN
        return_boundary:=public.rsc_check_loss_return_stop_0163(inverse.id);
    END IF;
    PERFORM public.rsc_loss_events_with_proof_0165(root.id,checked_proof);
    SELECT COALESCE(max(ledger_cursor),0) INTO observed FROM public.inventory_transactions;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT * INTO tx FROM public.inventory_transactions WHERE id=inverse.posting_transaction_id;
    SELECT * INTO original_tx FROM public.inventory_transactions WHERE id=selected_transaction;
    SELECT * INTO source FROM public.stock_accounts WHERE id=inverse.source_account_id;
    SELECT * INTO target FROM public.stock_accounts WHERE id=inverse.target_account_id;
    cutoff:=tx.ledger_cursor-1;
    IF source.id IS NULL OR target.id IS NULL OR target.availability_bucket IS DISTINCT FROM 'frozen'
       OR source.availability_bucket IS DISTINCT FROM (CASE WHEN selected_kind='return_to_region' THEN 'return_pending' ELSE 'available' END) OR source.id IS DISTINCT FROM selected_target
       OR target.id IS DISTINCT FROM root.source_account_id OR source.id=target.id
       OR source.owner_org_id IS DISTINCT FROM target.owner_org_id OR source.location_id IS DISTINCT FROM target.location_id
       OR source.custodian_person_id IS DISTINCT FROM target.custodian_person_id
       OR target.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR source.material_id IS DISTINCT FROM target.material_id OR source.lot_id IS DISTINCT FROM target.lot_id
       OR original_tx.ledger_cursor>cutoff THEN
        RAISE EXCEPTION '0159 exact historical inverse accounts required' USING ERRCODE='23514'; END IF;
    SELECT * INTO custody FROM public.custody_assignments WHERE location_id=target.location_id
        AND valid_from<=inverse.created_at AND (valid_to IS NULL OR valid_to>inverse.created_at);
    IF custody.id IS DISTINCT FROM inverse.custody_assignment_id OR custody.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR (SELECT count(*) FROM public.custody_assignments WHERE location_id=target.location_id
            AND valid_from<=inverse.created_at AND (valid_to IS NULL OR valid_to>inverse.created_at))<>1 THEN
        RAISE EXCEPTION '0159 unique historical inverse custody required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=source.id THEN m.quantity ELSE -m.quantity END),0),count(DISTINCT t.id)
        INTO source_amount,source_version FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND source.id IN (m.from_account_id,m.to_account_id);
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=target.id THEN m.quantity ELSE -m.quantity END),0),count(DISTINCT t.id)
        INTO target_amount,target_version FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND target.id IN (m.from_account_id,m.to_account_id);
    IF source_amount<inverse.quantity OR target_amount<0 THEN
        RAISE EXCEPTION '0159 sufficient historical inverse balances required' USING ERRCODE='23514'; END IF;
    holds:=public.rsc_loss_hold_projection_0159(target.id,cutoff);
    SELECT value INTO share FROM jsonb_array_elements(holds->'lines') WHERE value->>'line_id'=root.line_id::text;
    IF share IS NULL OR share->>'active_execution_id' IS DISTINCT FROM selected_execution::text
       OR share->'pending_reversal_id' IS DISTINCT FROM 'null'::jsonb OR share->>'frozen_quantity' IS DISTINCT FROM '0.000' THEN
        RAISE EXCEPTION '0159 exact pre-inverse released share required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb) INTO serial_ids
        FROM public.stock_operation_serials WHERE line_id=root.line_id;
    FOR identifier IN SELECT value::uuid FROM jsonb_array_elements_text(serial_ids) LOOP
        SELECT m.id,m.to_account_id,m.external_boundary_code,t.ledger_cursor INTO current_sn
            FROM public.inventory_movement_serials s JOIN public.inventory_movements m ON m.id=s.movement_id
            JOIN public.inventory_transactions t ON t.id=m.transaction_id WHERE s.serial_id=identifier
                AND s.transaction_id=t.id AND t.status='posted' AND t.ledger_cursor<=cutoff
            ORDER BY t.ledger_cursor DESC,m.line_no DESC LIMIT 1;
        SELECT m.id,m.to_account_id,m.external_boundary_code,t.ledger_cursor INTO prior_sn
            FROM public.inventory_movement_serials s JOIN public.inventory_movements m ON m.id=s.movement_id
            JOIN public.inventory_transactions t ON t.id=m.transaction_id WHERE s.serial_id=identifier
                AND s.transaction_id=t.id AND t.status='posted' AND t.ledger_cursor<original_tx.ledger_cursor
            ORDER BY t.ledger_cursor DESC,m.line_no DESC LIMIT 1;
        IF current_sn.id IS DISTINCT FROM selected_movement OR current_sn.to_account_id IS DISTINCT FROM source.id
           OR prior_sn.id IS NULL OR prior_sn.to_account_id IS DISTINCT FROM target.id
           OR current_sn.external_boundary_code IS NOT NULL OR prior_sn.external_boundary_code IS NOT NULL
           OR NOT EXISTS(SELECT 1 FROM public.inventory_serials WHERE id=identifier AND material_id=source.material_id
                AND lot_id IS NOT DISTINCT FROM source.lot_id) THEN
            RAISE EXCEPTION '0159 exact active inverse serial lineage required' USING ERRCODE='23514'; END IF;
        serial_basis:=serial_basis||jsonb_build_array(jsonb_build_object('serial_id',identifier::text,
            'original_movement_id',selected_movement::text,'lifecycle_before','active','lifecycle_after','active',
            'previous_movement_id',prior_sn.id::text,'previous_ledger_cursor',prior_sn.ledger_cursor));
    END LOOP;
    SELECT * INTO policy FROM public.material_inventory_policies WHERE material_id=target.material_id
        AND effective_from<=inverse.created_at AND (effective_to IS NULL OR effective_to>inverse.created_at);
    IF policy.id IS NULL OR (SELECT count(*) FROM public.material_inventory_policies WHERE material_id=target.material_id
            AND effective_from<=inverse.created_at AND (effective_to IS NULL OR effective_to>inverse.created_at))<>1
       OR policy.tracking_mode NOT IN ('none','lot','serial','lot_and_serial') OR policy.quantity_scale NOT BETWEEN 0 AND 3
       OR inverse.quantity<>trunc(inverse.quantity,policy.quantity_scale)
       OR (NOT policy.allow_fraction AND inverse.quantity<>trunc(inverse.quantity))
       OR (policy.tracking_mode IN ('none','serial') AND source.lot_id IS NOT NULL)
       OR (policy.tracking_mode IN ('lot','lot_and_serial') AND source.lot_id IS NULL)
       OR (policy.tracking_mode IN ('serial','lot_and_serial') AND jsonb_array_length(serial_ids)<>inverse.quantity)
       OR (policy.tracking_mode IN ('none','lot') AND serial_ids<>'[]'::jsonb) THEN
        RAISE EXCEPTION '0159 exact historical inverse tracking policy required' USING ERRCODE='23514'; END IF;
    effective_from_text:=to_char(policy.effective_from AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||
        CASE WHEN extract(microseconds FROM policy.effective_from)::bigint % 1000000=0 THEN ''
            ELSE '.'||to_char(policy.effective_from AT TIME ZONE 'UTC','US') END||'+00:00';
    effective_to_text:=CASE WHEN policy.effective_to IS NULL THEN NULL ELSE
        to_char(policy.effective_to AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||
        CASE WHEN extract(microseconds FROM policy.effective_to)::bigint % 1000000=0 THEN ''
            ELSE '.'||to_char(policy.effective_to AT TIME ZONE 'UTC','US') END||'+00:00' END;
    recorded:=inverse.plan_jsonb->'policy_fingerprint';
    fingerprint:=jsonb_build_array(jsonb_build_array(target.material_id::text,policy.id::text,policy.tracking_mode,
        policy.quantity_scale,policy.allow_fraction,effective_from_text,recorded->0->6));
    IF jsonb_typeof(recorded) IS DISTINCT FROM 'array' OR jsonb_array_length(recorded)<>1
       OR jsonb_typeof(recorded->0) IS DISTINCT FROM 'array' OR jsonb_array_length(recorded->0)<>7
       OR (recorded->0->6<>'null'::jsonb AND recorded->0->6 IS DISTINCT FROM to_jsonb(effective_to_text))
       OR public.rsc_canonical_reconciliation_json_0026(recorded) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(fingerprint) THEN
        RAISE EXCEPTION '0159 exact inverse policy fingerprint required' USING ERRCODE='23514'; END IF;
    expected:=jsonb_build_object('schema_version','1.0','stage','stock_preparation_only','intent',inverse.command_jsonb->'intent',
        'actor_user_id',inverse.actor_user_id,'actor_person_id',inverse.actor_person_id::text,'authorization_version',inverse.authorization_version,
        'root_disposition_id',root.id::text,'original_execution_id',selected_execution::text,'original_transaction_id',original_tx.id::text,
        'original_movement_id',selected_movement::text,'original_ledger_cursor',original_tx.ledger_cursor,
        'source_account_id',source.id::text,'target_account_id',target.id::text,'quantity',to_char(inverse.quantity,'FM999999999999990.000'),
        'serial_ids',serial_ids,'serials',serial_basis,'source_condition',source.condition_code,'target_condition',target.condition_code,
        'custody_assignment_id',custody.id::text,'ledger_cursor',cutoff,'source_balance_quantity',to_char(source_amount,'FM999999999999990.000'),
        'source_balance_version',source_version,'target_balance_quantity',to_char(target_amount,'FM999999999999990.000'),
        'target_balance_version',target_version,'frozen_holds_before',holds,'restored_line_id',root.line_id::text,
        'restored_frozen_quantity',to_char(inverse.quantity,'FM999999999999990.000'),'return_boundary',return_boundary,'policy_fingerprint',fingerprint);
    IF public.rsc_canonical_reconciliation_json_0026(inverse.plan_jsonb) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(expected)
       OR inverse.plan_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
        RAISE EXCEPTION '0159 full historical inverse plan mismatch' USING ERRCODE='23514'; END IF;
    command:=jsonb_build_object('operation','reverse','actor',jsonb_build_object('authorization_version',inverse.authorization_version,
        'person_id',inverse.actor_person_id::text,'user_id',inverse.actor_user_id),'command',jsonb_build_object(
        'effective_at',to_char(inverse.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        'original_transaction_id',original_tx.id::text,'posting_key','stock-loss:reverse_loss:'||inverse.id::text||':'||inverse.idempotency_key_hash,
        'source_document_id',inverse.id::text,'source_document_type','stock_loss_disposition_reversal',
        'transaction_no','INV-LOSS-REV-'||upper(substr(inverse.idempotency_key_hash,1,20))));
    IF tx.posting_key IS DISTINCT FROM command->'command'->>'posting_key'
       OR tx.transaction_no IS DISTINCT FROM command->'command'->>'transaction_no'
       OR tx.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(command),'UTF8')),'hex')
       OR observed<>(SELECT COALESCE(max(ledger_cursor),0) FROM public.inventory_transactions) THEN
        RAISE EXCEPTION '0159 canonical inverse posting command mismatch' USING ERRCODE='23514'; END IF;
    RETURN expected;
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_loss_inverse_with_proof_0165(uuid,jsonb)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox,star_oam_backup;

CREATE FUNCTION public.rsc_loss_correction_with_proof_0165(checked_correction uuid, checked_proof jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE correction public.stock_loss_correction_executions%ROWTYPE;
    inverse public.stock_loss_disposition_reversals%ROWTYPE; decision public.stock_loss_correction_decisions%ROWTYPE;
    root public.stock_loss_dispositions%ROWTYPE; parent public.stock_operation_orders%ROWTYPE;
    tx public.inventory_transactions%ROWTYPE; source public.stock_accounts%ROWTYPE; target public.stock_accounts%ROWTYPE;
    custody public.custody_assignments%ROWTYPE; policy public.material_inventory_policies%ROWTYPE;
    observed bigint; cutoff bigint; source_amount numeric; target_amount numeric; source_version bigint; target_version bigint;
    serial_ids jsonb; holds jsonb; share jsonb; recorded jsonb; fingerprint jsonb; dimensions jsonb;
    expected jsonb; command jsonb; identifier uuid; current_sn record; new_target boolean; target_id uuid;
    movement text; effective_from_text text; effective_to_text text;
BEGIN
    SELECT * INTO correction FROM public.stock_loss_correction_executions WHERE id=checked_correction;
    SELECT * INTO inverse FROM public.stock_loss_disposition_reversals WHERE id=correction.reversal_id;
    SELECT * INTO decision FROM public.stock_loss_correction_decisions WHERE id=correction.correction_decision_id;
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=correction.root_disposition_id;
    IF correction.disposition='scrap' THEN
        PERFORM public.rsc_loss_inverse_with_proof_0165(correction.reversal_id,checked_proof);
        RETURN public.rsc_scrap_history_from_proof_0165('correction',correction.id,root.id,checked_proof);
    END IF;
    IF correction.id IS NULL OR root.id IS NULL OR inverse.id IS NULL OR decision.id IS NULL
       OR inverse.root_disposition_id IS DISTINCT FROM root.id
       OR decision.root_disposition_id IS DISTINCT FROM root.id
       OR decision.reversal_id IS DISTINCT FROM inverse.id
       OR correction.disposition NOT IN ('restore_available','convert_used','convert_damaged')
       OR decision.disposition IS DISTINCT FROM correction.disposition THEN
        RAISE EXCEPTION 'later correction exact account plan required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_loss_inverse_with_proof_0165(inverse.id,checked_proof);
    SELECT COALESCE(max(ledger_cursor),0) INTO observed FROM public.inventory_transactions;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT * INTO tx FROM public.inventory_transactions WHERE id=correction.posting_transaction_id;
    SELECT * INTO source FROM public.stock_accounts WHERE id=correction.source_account_id;
    SELECT * INTO target FROM public.stock_accounts WHERE id=correction.target_account_id;
    cutoff:=tx.ledger_cursor-1;
    IF source.id IS NULL OR target.id IS NULL OR source.availability_bucket IS DISTINCT FROM 'frozen'
       OR target.availability_bucket IS DISTINCT FROM 'available' OR source.id IS DISTINCT FROM root.source_account_id
       OR correction.quantity IS DISTINCT FROM root.quantity OR source.id=target.id
       OR source.owner_org_id IS DISTINCT FROM target.owner_org_id OR source.location_id IS DISTINCT FROM target.location_id
       OR source.custodian_person_id IS DISTINCT FROM target.custodian_person_id
       OR source.custodian_person_id IS DISTINCT FROM parent.requester_id OR source.material_id IS DISTINCT FROM target.material_id
       OR source.lot_id IS DISTINCT FROM target.lot_id OR target.created_at IS NULL OR target.created_at>correction.created_at
       OR target.condition_code IS DISTINCT FROM (CASE correction.disposition WHEN 'restore_available' THEN source.condition_code
           WHEN 'convert_used' THEN 'used' ELSE 'damaged' END) THEN
        RAISE EXCEPTION '0159 exact historical correction accounts required' USING ERRCODE='23514'; END IF;
    SELECT * INTO custody FROM public.custody_assignments WHERE location_id=source.location_id
        AND valid_from<=correction.created_at AND (valid_to IS NULL OR valid_to>correction.created_at);
    IF custody.id IS DISTINCT FROM correction.custody_assignment_id OR custody.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR (SELECT count(*) FROM public.custody_assignments WHERE location_id=source.location_id
            AND valid_from<=correction.created_at AND (valid_to IS NULL OR valid_to>correction.created_at))<>1 THEN
        RAISE EXCEPTION '0159 unique historical correction custody required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=source.id THEN m.quantity ELSE -m.quantity END),0),count(DISTINCT t.id)
        INTO source_amount,source_version FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND source.id IN (m.from_account_id,m.to_account_id);
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=target.id THEN m.quantity ELSE -m.quantity END),0),count(DISTINCT t.id)
        INTO target_amount,target_version FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND target.id IN (m.from_account_id,m.to_account_id);
    new_target:=target.created_at=correction.created_at;
    IF new_target THEN
        dimensions:=jsonb_build_object('owner_org_id',target.owner_org_id::text,'location_id',target.location_id::text,
            'custodian_person_id',target.custodian_person_id::text,'material_id',target.material_id::text,
            'lot_id',target.lot_id::text,'condition_code',target.condition_code,'availability_bucket',target.availability_bucket);
        target_id:=rsc_loss_uuid_0159.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid,
            'rsc:stock-loss-disposition-account:v1:'||encode(sha256(convert_to(
                public.rsc_canonical_reconciliation_json_0026(dimensions),'UTF8')),'hex'));
        IF target.id IS DISTINCT FROM target_id OR target_amount<>0 OR target_version<>0 THEN
            RAISE EXCEPTION '0159 exact newly created correction account required' USING ERRCODE='23514'; END IF;
    END IF;
    IF source_amount<correction.quantity OR target_amount<0 THEN
        RAISE EXCEPTION '0159 sufficient historical correction balances required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb) INTO serial_ids
        FROM public.stock_operation_serials WHERE line_id=root.line_id;
    holds:=public.rsc_loss_hold_projection_0159(source.id,cutoff);
    SELECT value INTO share FROM jsonb_array_elements(holds->'lines') WHERE value->>'line_id'=root.line_id::text;
    IF share IS NULL OR share->'active_execution_id' IS DISTINCT FROM 'null'::jsonb
       OR share->>'pending_reversal_id' IS DISTINCT FROM inverse.id::text
       OR share->>'frozen_quantity' IS DISTINCT FROM to_char(root.quantity,'FM999999999999990.000')
       OR share->'frozen_serial_ids' IS DISTINCT FROM serial_ids THEN
        RAISE EXCEPTION '0159 exact pre-correction restored share required' USING ERRCODE='23514'; END IF;
    FOR identifier IN SELECT value::uuid FROM jsonb_array_elements_text(serial_ids) LOOP
        SELECT m.id,m.to_account_id,m.external_boundary_code,t.movement_type INTO current_sn
            FROM public.inventory_movement_serials s JOIN public.inventory_movements m ON m.id=s.movement_id
            JOIN public.inventory_transactions t ON t.id=m.transaction_id WHERE s.serial_id=identifier
                AND s.transaction_id=t.id AND t.status='posted' AND t.ledger_cursor<=cutoff
            ORDER BY t.ledger_cursor DESC,m.line_no DESC LIMIT 1;
        IF current_sn.id IS DISTINCT FROM inverse.posting_movement_id OR current_sn.to_account_id IS DISTINCT FROM source.id
           OR current_sn.external_boundary_code IS NOT NULL OR current_sn.movement_type IS DISTINCT FROM 'reversal'
           OR NOT EXISTS(SELECT 1 FROM public.inventory_serials WHERE id=identifier AND material_id=source.material_id
                AND lot_id IS NOT DISTINCT FROM source.lot_id) THEN
            RAISE EXCEPTION '0159 exact active correction serial lineage required' USING ERRCODE='23514'; END IF;
    END LOOP;
    SELECT * INTO policy FROM public.material_inventory_policies WHERE material_id=source.material_id
        AND effective_from<=correction.created_at AND (effective_to IS NULL OR effective_to>correction.created_at);
    IF policy.id IS NULL OR (SELECT count(*) FROM public.material_inventory_policies WHERE material_id=source.material_id
            AND effective_from<=correction.created_at AND (effective_to IS NULL OR effective_to>correction.created_at))<>1
       OR policy.tracking_mode NOT IN ('none','lot','serial','lot_and_serial') OR policy.quantity_scale NOT BETWEEN 0 AND 3
       OR correction.quantity<>trunc(correction.quantity,policy.quantity_scale)
       OR (NOT policy.allow_fraction AND correction.quantity<>trunc(correction.quantity))
       OR (policy.tracking_mode IN ('none','serial') AND source.lot_id IS NOT NULL)
       OR (policy.tracking_mode IN ('lot','lot_and_serial') AND source.lot_id IS NULL)
       OR (policy.tracking_mode IN ('serial','lot_and_serial') AND jsonb_array_length(serial_ids)<>correction.quantity)
       OR (policy.tracking_mode IN ('none','lot') AND serial_ids<>'[]'::jsonb) THEN
        RAISE EXCEPTION '0159 exact historical correction tracking policy required' USING ERRCODE='23514'; END IF;
    effective_from_text:=to_char(policy.effective_from AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||
        CASE WHEN extract(microseconds FROM policy.effective_from)::bigint % 1000000=0 THEN ''
            ELSE '.'||to_char(policy.effective_from AT TIME ZONE 'UTC','US') END||'+00:00';
    effective_to_text:=CASE WHEN policy.effective_to IS NULL THEN NULL ELSE
        to_char(policy.effective_to AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||
        CASE WHEN extract(microseconds FROM policy.effective_to)::bigint % 1000000=0 THEN ''
            ELSE '.'||to_char(policy.effective_to AT TIME ZONE 'UTC','US') END||'+00:00' END;
    recorded:=correction.plan_jsonb->'policy_fingerprint';
    fingerprint:=jsonb_build_array(jsonb_build_array(source.material_id::text,policy.id::text,policy.tracking_mode,
        policy.quantity_scale,policy.allow_fraction,effective_from_text,recorded->0->6));
    IF jsonb_typeof(recorded) IS DISTINCT FROM 'array' OR jsonb_array_length(recorded)<>1
       OR jsonb_typeof(recorded->0) IS DISTINCT FROM 'array' OR jsonb_array_length(recorded->0)<>7
       OR (recorded->0->6<>'null'::jsonb AND recorded->0->6 IS DISTINCT FROM to_jsonb(effective_to_text))
       OR public.rsc_canonical_reconciliation_json_0026(recorded) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(fingerprint) THEN
        RAISE EXCEPTION '0159 exact correction policy fingerprint required' USING ERRCODE='23514'; END IF;

    movement:=CASE decision.disposition WHEN 'restore_available' THEN 'unfreeze' ELSE 'status_change' END;
    expected:=jsonb_build_object('schema_version','1.0','stage','correction_execution_plan','intent',correction.command_jsonb->'intent',
        'actor_user_id',correction.actor_user_id,'actor_person_id',correction.actor_person_id::text,'authorization_version',correction.authorization_version,
        'root_disposition_id',root.id::text,'reversal_id',inverse.id::text,'correction_decision_id',decision.id::text,
        'disposition',decision.disposition,'source_account_id',source.id::text,'target_account_id',target.id::text,
        'source_condition',source.condition_code,'target_condition',target.condition_code,'target_requires_creation',new_target,
        'custody_assignment_id',custody.id::text,'quantity',to_char(correction.quantity,'FM999999999999990.000'),
        'serial_ids',serial_ids,'movement_type',movement,'ledger_cursor',cutoff,
        'source_balance_quantity',to_char(source_amount,'FM999999999999990.000'),'source_balance_version',source_version,
        'target_balance_quantity',to_char(target_amount,'FM999999999999990.000'),'target_balance_version',target_version,
        'frozen_holds_before',holds,'policy_fingerprint',fingerprint);
    IF public.rsc_canonical_reconciliation_json_0026(correction.plan_jsonb) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(expected)
       OR correction.plan_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
        RAISE EXCEPTION '0159 full historical correction plan mismatch' USING ERRCODE='23514'; END IF;
    command:=jsonb_build_object('operation','post','actor',jsonb_build_object('authorization_version',correction.authorization_version,
        'person_id',correction.actor_person_id::text,'user_id',correction.actor_user_id),'command',jsonb_build_object(
        'effective_at',to_char(correction.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        'movement_type',movement,'posting_key','stock-loss:correct_loss:'||correction.id::text||':'||correction.idempotency_key_hash,
        'source_document_id',correction.id::text,'source_document_type','stock_loss_correction_execution',
        'transaction_no','INV-LOSS-CORR-'||upper(substr(correction.idempotency_key_hash,1,20)),
        'movements',jsonb_build_array(jsonb_build_object('external_boundary_code',NULL,'from_account_id',source.id::text,
            'to_account_id',target.id::text,'quantity',trim_scale(correction.quantity)::text,'serial_ids',serial_ids))));
    IF tx.posting_key IS DISTINCT FROM command->'command'->>'posting_key'
       OR tx.transaction_no IS DISTINCT FROM command->'command'->>'transaction_no'
       OR tx.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(command),'UTF8')),'hex')
       OR observed<>(SELECT COALESCE(max(ledger_cursor),0) FROM public.inventory_transactions) THEN
        RAISE EXCEPTION '0159 canonical correction posting command mismatch' USING ERRCODE='23514'; END IF;
    RETURN expected;
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_loss_correction_with_proof_0165(uuid,jsonb)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox,star_oam_backup;

CREATE OR REPLACE FUNCTION public.rsc_check_loss_history_graph_0159(checked_root uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE pending uuid[]:=ARRAY[checked_root]; visited uuid[]:=ARRAY[]::uuid[];
    inverse_ids uuid[]:=ARRAY[]::uuid[]; correction_ids uuid[]:=ARRAY[]::uuid[];
    queue_index integer:=1; identifier uuid; ancestor uuid; cursor_item bigint; inverse_id uuid; correction_id uuid;
    root public.stock_loss_dispositions%ROWTYPE; projected jsonb; piece jsonb;
    checked_proof jsonb;
    observed bigint; heads jsonb; final_heads jsonb; edge record;
BEGIN
    IF checked_root IS NULL OR checked_root='00000000-0000-0000-0000-000000000000'::uuid THEN
        RAISE EXCEPTION '0159 normal history root required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(max(ledger_cursor),0) INTO observed FROM public.inventory_transactions;
    SELECT COALESCE(jsonb_agg(jsonb_build_array(stream_key,version,last_event_id::text,last_hash) ORDER BY stream_key),'[]'::jsonb)
        INTO heads FROM public.audit_chain_heads WHERE stream_key IN ('inventory','material_request');
    WHILE queue_index<=cardinality(pending) LOOP
        identifier:=pending[queue_index];queue_index:=queue_index+1;
        SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=identifier;
        IF root.id IS NULL THEN
            RAISE EXCEPTION '0159 retained loss root required' USING ERRCODE='23514'; END IF;
        checked_proof:=public.rsc_build_scrap_history_proof_0165(root.id);
        IF root.disposition IN ('restore_available','convert_used','convert_damaged') THEN
            PERFORM public.rsc_check_loss_versioned_normal_original_0159(root.id);
        ELSIF root.disposition='return_to_region' THEN
            -- Each inverse below proves its original stop or supported correction.
            PERFORM public.rsc_check_loss_return_0152(root.id,false);
        ELSIF root.disposition='scrap' THEN
            PERFORM public.rsc_scrap_history_from_proof_0165('original',root.id,root.id,checked_proof);
        ELSE
            RAISE EXCEPTION '0159 dedicated scrap history proof required' USING ERRCODE='23514';
        END IF;
        -- The fresh root proof above includes the complete upstream history.
        PERFORM public.rsc_loss_events_with_proof_0165(root.id,checked_proof);
        -- Prove the actual predecessor before its inverse, in ledger order.
        -- Chain projection independently rejects forks, cycles and disconnected edges.
        FOR edge IN SELECT x.id,x.kind FROM (
            SELECT id,posting_transaction_id,'inverse'::text AS kind
                FROM public.stock_loss_disposition_reversals WHERE root_disposition_id=root.id
            UNION ALL SELECT id,posting_transaction_id,'correction'::text
                FROM public.stock_loss_correction_executions WHERE root_disposition_id=root.id) x
            JOIN public.inventory_transactions t ON t.id=x.posting_transaction_id ORDER BY t.ledger_cursor LOOP
            IF edge.kind='inverse' THEN
                PERFORM public.rsc_loss_inverse_with_proof_0165(edge.id,checked_proof);
                inverse_ids:=array_append(inverse_ids,edge.id);
            ELSE
                PERFORM public.rsc_loss_correction_with_proof_0165(edge.id,checked_proof);
                correction_ids:=array_append(correction_ids,edge.id);
            END IF;
        END LOOP;
        -- An inverse or correction may occur after another original report.
        -- Its own earlier holds are dependencies too, even when they were not
        -- present at this root's first posting.
        FOR cursor_item IN SELECT ledger_cursor FROM public.inventory_transactions
            WHERE id=root.posting_transaction_id OR id IN (
                SELECT posting_transaction_id FROM public.stock_loss_disposition_reversals WHERE root_disposition_id=root.id
                UNION SELECT posting_transaction_id FROM public.stock_loss_correction_executions WHERE root_disposition_id=root.id)
            UNION SELECT observed+1 ORDER BY ledger_cursor LOOP
            projected:=public.rsc_loss_hold_projection_0159(root.source_account_id,cursor_item-1);
            FOR piece IN SELECT value FROM jsonb_array_elements(projected->'lines') LOOP
                ancestor:=(piece->>'root_disposition_id')::uuid;
                IF ancestor IS NOT NULL AND NOT ancestor=ANY(pending) THEN
                    pending:=array_append(pending,ancestor);
                END IF;
            END LOOP;
        END LOOP;
        visited:=array_append(visited,root.id);
    END LOOP;
    SELECT COALESCE(jsonb_agg(jsonb_build_array(stream_key,version,last_event_id::text,last_hash) ORDER BY stream_key),'[]'::jsonb)
        INTO final_heads FROM public.audit_chain_heads WHERE stream_key IN ('inventory','material_request');
    IF final_heads IS DISTINCT FROM heads OR observed<>(SELECT COALESCE(max(ledger_cursor),0) FROM public.inventory_transactions) THEN
        RAISE EXCEPTION '0159 normal history changed during proof' USING ERRCODE='23514'; END IF;
    RETURN jsonb_build_object('stage','complete_supported_loss_history','root_disposition_id',checked_root::text,
        'observed_ledger_cursor',observed,
        'verified_original_ids',(SELECT COALESCE(jsonb_agg(value::text ORDER BY value),'[]'::jsonb) FROM unnest(visited) value),
        'verified_inverse_ids',(SELECT COALESCE(jsonb_agg(value::text ORDER BY value),'[]'::jsonb) FROM unnest(inverse_ids) value),
        'verified_correction_ids',(SELECT COALESCE(jsonb_agg(value::text ORDER BY value),'[]'::jsonb) FROM unnest(correction_ids) value));
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_check_loss_first_inverse_plan_0159(checked_inverse uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE inverse public.stock_loss_disposition_reversals%ROWTYPE; root public.stock_loss_dispositions%ROWTYPE;
    parent public.stock_operation_orders%ROWTYPE; tx public.inventory_transactions%ROWTYPE;
    original_tx public.inventory_transactions%ROWTYPE; source public.stock_accounts%ROWTYPE; target public.stock_accounts%ROWTYPE;
    custody public.custody_assignments%ROWTYPE; policy public.material_inventory_policies%ROWTYPE;
    observed bigint; cutoff bigint; source_amount numeric; target_amount numeric; source_version bigint; target_version bigint;
    serial_ids jsonb; serial_basis jsonb:='[]'::jsonb; holds jsonb; share jsonb; recorded jsonb; fingerprint jsonb;
    expected jsonb; command jsonb; identifier uuid; current_sn record; prior_sn record;
    effective_from_text text; effective_to_text text;
    selected_execution uuid; selected_transaction uuid; selected_movement uuid;
    selected_target uuid; selected_kind text; selected_quantity numeric;
    correction public.stock_loss_correction_executions%ROWTYPE; return_boundary jsonb:=NULL;
BEGIN
    SELECT * INTO inverse FROM public.stock_loss_disposition_reversals WHERE id=checked_inverse;
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=inverse.root_disposition_id;
    IF inverse.id IS NULL OR root.id IS NULL THEN
        RAISE EXCEPTION 'later inverse retained root required' USING ERRCODE='23514'; END IF;
    IF inverse.reversed_correction_id IS NULL THEN
        selected_execution:=root.id; selected_transaction:=root.posting_transaction_id;
        selected_movement:=root.posting_movement_id; selected_target:=root.target_account_id;
        selected_kind:=root.disposition; selected_quantity:=root.quantity;
    ELSE
        SELECT * INTO correction FROM public.stock_loss_correction_executions WHERE id=inverse.reversed_correction_id;
        IF correction.id IS NULL OR correction.root_disposition_id IS DISTINCT FROM root.id THEN
            RAISE EXCEPTION 'later inverse exact selected correction required' USING ERRCODE='23514'; END IF;
        selected_execution:=correction.id; selected_transaction:=correction.posting_transaction_id;
        selected_movement:=correction.posting_movement_id; selected_target:=correction.target_account_id;
        selected_kind:=correction.disposition; selected_quantity:=correction.quantity;
    END IF;
    IF selected_kind='scrap' THEN
        RETURN public.rsc_check_scrap_history_0165('inverse',inverse.id);
    END IF;
    IF selected_kind NOT IN ('restore_available','convert_used','convert_damaged','return_to_region')
       OR (selected_kind='return_to_region' AND inverse.reversed_correction_id IS NOT NULL)
       OR selected_transaction IS NULL OR selected_movement IS NULL OR selected_target IS NULL
       OR selected_quantity IS DISTINCT FROM root.quantity OR inverse.quantity IS DISTINCT FROM root.quantity
       OR inverse.original_transaction_id IS DISTINCT FROM selected_transaction
       OR inverse.original_movement_id IS DISTINCT FROM selected_movement THEN
        RAISE EXCEPTION 'later inverse exact account posting required' USING ERRCODE='23514'; END IF;
    IF selected_kind='return_to_region' THEN
        return_boundary:=public.rsc_check_loss_return_stop_0163(inverse.id);
    END IF;
    PERFORM public.rsc_check_loss_chain_events_0159(root.id);
    SELECT COALESCE(max(ledger_cursor),0) INTO observed FROM public.inventory_transactions;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT * INTO tx FROM public.inventory_transactions WHERE id=inverse.posting_transaction_id;
    SELECT * INTO original_tx FROM public.inventory_transactions WHERE id=selected_transaction;
    SELECT * INTO source FROM public.stock_accounts WHERE id=inverse.source_account_id;
    SELECT * INTO target FROM public.stock_accounts WHERE id=inverse.target_account_id;
    cutoff:=tx.ledger_cursor-1;
    IF source.id IS NULL OR target.id IS NULL OR target.availability_bucket IS DISTINCT FROM 'frozen'
       OR source.availability_bucket IS DISTINCT FROM (CASE WHEN selected_kind='return_to_region' THEN 'return_pending' ELSE 'available' END) OR source.id IS DISTINCT FROM selected_target
       OR target.id IS DISTINCT FROM root.source_account_id OR source.id=target.id
       OR source.owner_org_id IS DISTINCT FROM target.owner_org_id OR source.location_id IS DISTINCT FROM target.location_id
       OR source.custodian_person_id IS DISTINCT FROM target.custodian_person_id
       OR target.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR source.material_id IS DISTINCT FROM target.material_id OR source.lot_id IS DISTINCT FROM target.lot_id
       OR original_tx.ledger_cursor>cutoff THEN
        RAISE EXCEPTION '0159 exact historical inverse accounts required' USING ERRCODE='23514'; END IF;
    SELECT * INTO custody FROM public.custody_assignments WHERE location_id=target.location_id
        AND valid_from<=inverse.created_at AND (valid_to IS NULL OR valid_to>inverse.created_at);
    IF custody.id IS DISTINCT FROM inverse.custody_assignment_id OR custody.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR (SELECT count(*) FROM public.custody_assignments WHERE location_id=target.location_id
            AND valid_from<=inverse.created_at AND (valid_to IS NULL OR valid_to>inverse.created_at))<>1 THEN
        RAISE EXCEPTION '0159 unique historical inverse custody required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=source.id THEN m.quantity ELSE -m.quantity END),0),count(DISTINCT t.id)
        INTO source_amount,source_version FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND source.id IN (m.from_account_id,m.to_account_id);
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=target.id THEN m.quantity ELSE -m.quantity END),0),count(DISTINCT t.id)
        INTO target_amount,target_version FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND target.id IN (m.from_account_id,m.to_account_id);
    IF source_amount<inverse.quantity OR target_amount<0 THEN
        RAISE EXCEPTION '0159 sufficient historical inverse balances required' USING ERRCODE='23514'; END IF;
    holds:=public.rsc_loss_hold_projection_0159(target.id,cutoff);
    SELECT value INTO share FROM jsonb_array_elements(holds->'lines') WHERE value->>'line_id'=root.line_id::text;
    IF share IS NULL OR share->>'active_execution_id' IS DISTINCT FROM selected_execution::text
       OR share->'pending_reversal_id' IS DISTINCT FROM 'null'::jsonb OR share->>'frozen_quantity' IS DISTINCT FROM '0.000' THEN
        RAISE EXCEPTION '0159 exact pre-inverse released share required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb) INTO serial_ids
        FROM public.stock_operation_serials WHERE line_id=root.line_id;
    FOR identifier IN SELECT value::uuid FROM jsonb_array_elements_text(serial_ids) LOOP
        SELECT m.id,m.to_account_id,m.external_boundary_code,t.ledger_cursor INTO current_sn
            FROM public.inventory_movement_serials s JOIN public.inventory_movements m ON m.id=s.movement_id
            JOIN public.inventory_transactions t ON t.id=m.transaction_id WHERE s.serial_id=identifier
                AND s.transaction_id=t.id AND t.status='posted' AND t.ledger_cursor<=cutoff
            ORDER BY t.ledger_cursor DESC,m.line_no DESC LIMIT 1;
        SELECT m.id,m.to_account_id,m.external_boundary_code,t.ledger_cursor INTO prior_sn
            FROM public.inventory_movement_serials s JOIN public.inventory_movements m ON m.id=s.movement_id
            JOIN public.inventory_transactions t ON t.id=m.transaction_id WHERE s.serial_id=identifier
                AND s.transaction_id=t.id AND t.status='posted' AND t.ledger_cursor<original_tx.ledger_cursor
            ORDER BY t.ledger_cursor DESC,m.line_no DESC LIMIT 1;
        IF current_sn.id IS DISTINCT FROM selected_movement OR current_sn.to_account_id IS DISTINCT FROM source.id
           OR prior_sn.id IS NULL OR prior_sn.to_account_id IS DISTINCT FROM target.id
           OR current_sn.external_boundary_code IS NOT NULL OR prior_sn.external_boundary_code IS NOT NULL
           OR NOT EXISTS(SELECT 1 FROM public.inventory_serials WHERE id=identifier AND material_id=source.material_id
                AND lot_id IS NOT DISTINCT FROM source.lot_id) THEN
            RAISE EXCEPTION '0159 exact active inverse serial lineage required' USING ERRCODE='23514'; END IF;
        serial_basis:=serial_basis||jsonb_build_array(jsonb_build_object('serial_id',identifier::text,
            'original_movement_id',selected_movement::text,'lifecycle_before','active','lifecycle_after','active',
            'previous_movement_id',prior_sn.id::text,'previous_ledger_cursor',prior_sn.ledger_cursor));
    END LOOP;
    SELECT * INTO policy FROM public.material_inventory_policies WHERE material_id=target.material_id
        AND effective_from<=inverse.created_at AND (effective_to IS NULL OR effective_to>inverse.created_at);
    IF policy.id IS NULL OR (SELECT count(*) FROM public.material_inventory_policies WHERE material_id=target.material_id
            AND effective_from<=inverse.created_at AND (effective_to IS NULL OR effective_to>inverse.created_at))<>1
       OR policy.tracking_mode NOT IN ('none','lot','serial','lot_and_serial') OR policy.quantity_scale NOT BETWEEN 0 AND 3
       OR inverse.quantity<>trunc(inverse.quantity,policy.quantity_scale)
       OR (NOT policy.allow_fraction AND inverse.quantity<>trunc(inverse.quantity))
       OR (policy.tracking_mode IN ('none','serial') AND source.lot_id IS NOT NULL)
       OR (policy.tracking_mode IN ('lot','lot_and_serial') AND source.lot_id IS NULL)
       OR (policy.tracking_mode IN ('serial','lot_and_serial') AND jsonb_array_length(serial_ids)<>inverse.quantity)
       OR (policy.tracking_mode IN ('none','lot') AND serial_ids<>'[]'::jsonb) THEN
        RAISE EXCEPTION '0159 exact historical inverse tracking policy required' USING ERRCODE='23514'; END IF;
    effective_from_text:=to_char(policy.effective_from AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||
        CASE WHEN extract(microseconds FROM policy.effective_from)::bigint % 1000000=0 THEN ''
            ELSE '.'||to_char(policy.effective_from AT TIME ZONE 'UTC','US') END||'+00:00';
    effective_to_text:=CASE WHEN policy.effective_to IS NULL THEN NULL ELSE
        to_char(policy.effective_to AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||
        CASE WHEN extract(microseconds FROM policy.effective_to)::bigint % 1000000=0 THEN ''
            ELSE '.'||to_char(policy.effective_to AT TIME ZONE 'UTC','US') END||'+00:00' END;
    recorded:=inverse.plan_jsonb->'policy_fingerprint';
    fingerprint:=jsonb_build_array(jsonb_build_array(target.material_id::text,policy.id::text,policy.tracking_mode,
        policy.quantity_scale,policy.allow_fraction,effective_from_text,recorded->0->6));
    IF jsonb_typeof(recorded) IS DISTINCT FROM 'array' OR jsonb_array_length(recorded)<>1
       OR jsonb_typeof(recorded->0) IS DISTINCT FROM 'array' OR jsonb_array_length(recorded->0)<>7
       OR (recorded->0->6<>'null'::jsonb AND recorded->0->6 IS DISTINCT FROM to_jsonb(effective_to_text))
       OR public.rsc_canonical_reconciliation_json_0026(recorded) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(fingerprint) THEN
        RAISE EXCEPTION '0159 exact inverse policy fingerprint required' USING ERRCODE='23514'; END IF;
    expected:=jsonb_build_object('schema_version','1.0','stage','stock_preparation_only','intent',inverse.command_jsonb->'intent',
        'actor_user_id',inverse.actor_user_id,'actor_person_id',inverse.actor_person_id::text,'authorization_version',inverse.authorization_version,
        'root_disposition_id',root.id::text,'original_execution_id',selected_execution::text,'original_transaction_id',original_tx.id::text,
        'original_movement_id',selected_movement::text,'original_ledger_cursor',original_tx.ledger_cursor,
        'source_account_id',source.id::text,'target_account_id',target.id::text,'quantity',to_char(inverse.quantity,'FM999999999999990.000'),
        'serial_ids',serial_ids,'serials',serial_basis,'source_condition',source.condition_code,'target_condition',target.condition_code,
        'custody_assignment_id',custody.id::text,'ledger_cursor',cutoff,'source_balance_quantity',to_char(source_amount,'FM999999999999990.000'),
        'source_balance_version',source_version,'target_balance_quantity',to_char(target_amount,'FM999999999999990.000'),
        'target_balance_version',target_version,'frozen_holds_before',holds,'restored_line_id',root.line_id::text,
        'restored_frozen_quantity',to_char(inverse.quantity,'FM999999999999990.000'),'return_boundary',return_boundary,'policy_fingerprint',fingerprint);
    IF public.rsc_canonical_reconciliation_json_0026(inverse.plan_jsonb) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(expected)
       OR inverse.plan_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
        RAISE EXCEPTION '0159 full historical inverse plan mismatch' USING ERRCODE='23514'; END IF;
    command:=jsonb_build_object('operation','reverse','actor',jsonb_build_object('authorization_version',inverse.authorization_version,
        'person_id',inverse.actor_person_id::text,'user_id',inverse.actor_user_id),'command',jsonb_build_object(
        'effective_at',to_char(inverse.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        'original_transaction_id',original_tx.id::text,'posting_key','stock-loss:reverse_loss:'||inverse.id::text||':'||inverse.idempotency_key_hash,
        'source_document_id',inverse.id::text,'source_document_type','stock_loss_disposition_reversal',
        'transaction_no','INV-LOSS-REV-'||upper(substr(inverse.idempotency_key_hash,1,20))));
    IF tx.posting_key IS DISTINCT FROM command->'command'->>'posting_key'
       OR tx.transaction_no IS DISTINCT FROM command->'command'->>'transaction_no'
       OR tx.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(command),'UTF8')),'hex')
       OR observed<>(SELECT COALESCE(max(ledger_cursor),0) FROM public.inventory_transactions) THEN
        RAISE EXCEPTION '0159 canonical inverse posting command mismatch' USING ERRCODE='23514'; END IF;
    RETURN expected;
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_check_loss_first_correction_plan_0159(checked_correction uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE correction public.stock_loss_correction_executions%ROWTYPE;
    inverse public.stock_loss_disposition_reversals%ROWTYPE; decision public.stock_loss_correction_decisions%ROWTYPE;
    root public.stock_loss_dispositions%ROWTYPE; parent public.stock_operation_orders%ROWTYPE;
    tx public.inventory_transactions%ROWTYPE; source public.stock_accounts%ROWTYPE; target public.stock_accounts%ROWTYPE;
    custody public.custody_assignments%ROWTYPE; policy public.material_inventory_policies%ROWTYPE;
    observed bigint; cutoff bigint; source_amount numeric; target_amount numeric; source_version bigint; target_version bigint;
    serial_ids jsonb; holds jsonb; share jsonb; recorded jsonb; fingerprint jsonb; dimensions jsonb;
    expected jsonb; command jsonb; identifier uuid; current_sn record; new_target boolean; target_id uuid;
    movement text; effective_from_text text; effective_to_text text;
BEGIN
    SELECT * INTO correction FROM public.stock_loss_correction_executions WHERE id=checked_correction;
    SELECT * INTO inverse FROM public.stock_loss_disposition_reversals WHERE id=correction.reversal_id;
    SELECT * INTO decision FROM public.stock_loss_correction_decisions WHERE id=correction.correction_decision_id;
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=correction.root_disposition_id;
    IF correction.disposition='scrap' THEN
        PERFORM public.rsc_check_loss_first_inverse_plan_0159(correction.reversal_id);
        RETURN public.rsc_check_scrap_history_0165('correction',correction.id);
    END IF;
    IF correction.id IS NULL OR root.id IS NULL OR inverse.id IS NULL OR decision.id IS NULL
       OR inverse.root_disposition_id IS DISTINCT FROM root.id
       OR decision.root_disposition_id IS DISTINCT FROM root.id
       OR decision.reversal_id IS DISTINCT FROM inverse.id
       OR correction.disposition NOT IN ('restore_available','convert_used','convert_damaged')
       OR decision.disposition IS DISTINCT FROM correction.disposition THEN
        RAISE EXCEPTION 'later correction exact account plan required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_check_loss_first_inverse_plan_0159(inverse.id);
    SELECT COALESCE(max(ledger_cursor),0) INTO observed FROM public.inventory_transactions;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT * INTO tx FROM public.inventory_transactions WHERE id=correction.posting_transaction_id;
    SELECT * INTO source FROM public.stock_accounts WHERE id=correction.source_account_id;
    SELECT * INTO target FROM public.stock_accounts WHERE id=correction.target_account_id;
    cutoff:=tx.ledger_cursor-1;
    IF source.id IS NULL OR target.id IS NULL OR source.availability_bucket IS DISTINCT FROM 'frozen'
       OR target.availability_bucket IS DISTINCT FROM 'available' OR source.id IS DISTINCT FROM root.source_account_id
       OR correction.quantity IS DISTINCT FROM root.quantity OR source.id=target.id
       OR source.owner_org_id IS DISTINCT FROM target.owner_org_id OR source.location_id IS DISTINCT FROM target.location_id
       OR source.custodian_person_id IS DISTINCT FROM target.custodian_person_id
       OR source.custodian_person_id IS DISTINCT FROM parent.requester_id OR source.material_id IS DISTINCT FROM target.material_id
       OR source.lot_id IS DISTINCT FROM target.lot_id OR target.created_at IS NULL OR target.created_at>correction.created_at
       OR target.condition_code IS DISTINCT FROM (CASE correction.disposition WHEN 'restore_available' THEN source.condition_code
           WHEN 'convert_used' THEN 'used' ELSE 'damaged' END) THEN
        RAISE EXCEPTION '0159 exact historical correction accounts required' USING ERRCODE='23514'; END IF;
    SELECT * INTO custody FROM public.custody_assignments WHERE location_id=source.location_id
        AND valid_from<=correction.created_at AND (valid_to IS NULL OR valid_to>correction.created_at);
    IF custody.id IS DISTINCT FROM correction.custody_assignment_id OR custody.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR (SELECT count(*) FROM public.custody_assignments WHERE location_id=source.location_id
            AND valid_from<=correction.created_at AND (valid_to IS NULL OR valid_to>correction.created_at))<>1 THEN
        RAISE EXCEPTION '0159 unique historical correction custody required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=source.id THEN m.quantity ELSE -m.quantity END),0),count(DISTINCT t.id)
        INTO source_amount,source_version FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND source.id IN (m.from_account_id,m.to_account_id);
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=target.id THEN m.quantity ELSE -m.quantity END),0),count(DISTINCT t.id)
        INTO target_amount,target_version FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND target.id IN (m.from_account_id,m.to_account_id);
    new_target:=target.created_at=correction.created_at;
    IF new_target THEN
        dimensions:=jsonb_build_object('owner_org_id',target.owner_org_id::text,'location_id',target.location_id::text,
            'custodian_person_id',target.custodian_person_id::text,'material_id',target.material_id::text,
            'lot_id',target.lot_id::text,'condition_code',target.condition_code,'availability_bucket',target.availability_bucket);
        target_id:=rsc_loss_uuid_0159.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid,
            'rsc:stock-loss-disposition-account:v1:'||encode(sha256(convert_to(
                public.rsc_canonical_reconciliation_json_0026(dimensions),'UTF8')),'hex'));
        IF target.id IS DISTINCT FROM target_id OR target_amount<>0 OR target_version<>0 THEN
            RAISE EXCEPTION '0159 exact newly created correction account required' USING ERRCODE='23514'; END IF;
    END IF;
    IF source_amount<correction.quantity OR target_amount<0 THEN
        RAISE EXCEPTION '0159 sufficient historical correction balances required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb) INTO serial_ids
        FROM public.stock_operation_serials WHERE line_id=root.line_id;
    holds:=public.rsc_loss_hold_projection_0159(source.id,cutoff);
    SELECT value INTO share FROM jsonb_array_elements(holds->'lines') WHERE value->>'line_id'=root.line_id::text;
    IF share IS NULL OR share->'active_execution_id' IS DISTINCT FROM 'null'::jsonb
       OR share->>'pending_reversal_id' IS DISTINCT FROM inverse.id::text
       OR share->>'frozen_quantity' IS DISTINCT FROM to_char(root.quantity,'FM999999999999990.000')
       OR share->'frozen_serial_ids' IS DISTINCT FROM serial_ids THEN
        RAISE EXCEPTION '0159 exact pre-correction restored share required' USING ERRCODE='23514'; END IF;
    FOR identifier IN SELECT value::uuid FROM jsonb_array_elements_text(serial_ids) LOOP
        SELECT m.id,m.to_account_id,m.external_boundary_code,t.movement_type INTO current_sn
            FROM public.inventory_movement_serials s JOIN public.inventory_movements m ON m.id=s.movement_id
            JOIN public.inventory_transactions t ON t.id=m.transaction_id WHERE s.serial_id=identifier
                AND s.transaction_id=t.id AND t.status='posted' AND t.ledger_cursor<=cutoff
            ORDER BY t.ledger_cursor DESC,m.line_no DESC LIMIT 1;
        IF current_sn.id IS DISTINCT FROM inverse.posting_movement_id OR current_sn.to_account_id IS DISTINCT FROM source.id
           OR current_sn.external_boundary_code IS NOT NULL OR current_sn.movement_type IS DISTINCT FROM 'reversal'
           OR NOT EXISTS(SELECT 1 FROM public.inventory_serials WHERE id=identifier AND material_id=source.material_id
                AND lot_id IS NOT DISTINCT FROM source.lot_id) THEN
            RAISE EXCEPTION '0159 exact active correction serial lineage required' USING ERRCODE='23514'; END IF;
    END LOOP;
    SELECT * INTO policy FROM public.material_inventory_policies WHERE material_id=source.material_id
        AND effective_from<=correction.created_at AND (effective_to IS NULL OR effective_to>correction.created_at);
    IF policy.id IS NULL OR (SELECT count(*) FROM public.material_inventory_policies WHERE material_id=source.material_id
            AND effective_from<=correction.created_at AND (effective_to IS NULL OR effective_to>correction.created_at))<>1
       OR policy.tracking_mode NOT IN ('none','lot','serial','lot_and_serial') OR policy.quantity_scale NOT BETWEEN 0 AND 3
       OR correction.quantity<>trunc(correction.quantity,policy.quantity_scale)
       OR (NOT policy.allow_fraction AND correction.quantity<>trunc(correction.quantity))
       OR (policy.tracking_mode IN ('none','serial') AND source.lot_id IS NOT NULL)
       OR (policy.tracking_mode IN ('lot','lot_and_serial') AND source.lot_id IS NULL)
       OR (policy.tracking_mode IN ('serial','lot_and_serial') AND jsonb_array_length(serial_ids)<>correction.quantity)
       OR (policy.tracking_mode IN ('none','lot') AND serial_ids<>'[]'::jsonb) THEN
        RAISE EXCEPTION '0159 exact historical correction tracking policy required' USING ERRCODE='23514'; END IF;
    effective_from_text:=to_char(policy.effective_from AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||
        CASE WHEN extract(microseconds FROM policy.effective_from)::bigint % 1000000=0 THEN ''
            ELSE '.'||to_char(policy.effective_from AT TIME ZONE 'UTC','US') END||'+00:00';
    effective_to_text:=CASE WHEN policy.effective_to IS NULL THEN NULL ELSE
        to_char(policy.effective_to AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||
        CASE WHEN extract(microseconds FROM policy.effective_to)::bigint % 1000000=0 THEN ''
            ELSE '.'||to_char(policy.effective_to AT TIME ZONE 'UTC','US') END||'+00:00' END;
    recorded:=correction.plan_jsonb->'policy_fingerprint';
    fingerprint:=jsonb_build_array(jsonb_build_array(source.material_id::text,policy.id::text,policy.tracking_mode,
        policy.quantity_scale,policy.allow_fraction,effective_from_text,recorded->0->6));
    IF jsonb_typeof(recorded) IS DISTINCT FROM 'array' OR jsonb_array_length(recorded)<>1
       OR jsonb_typeof(recorded->0) IS DISTINCT FROM 'array' OR jsonb_array_length(recorded->0)<>7
       OR (recorded->0->6<>'null'::jsonb AND recorded->0->6 IS DISTINCT FROM to_jsonb(effective_to_text))
       OR public.rsc_canonical_reconciliation_json_0026(recorded) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(fingerprint) THEN
        RAISE EXCEPTION '0159 exact correction policy fingerprint required' USING ERRCODE='23514'; END IF;

    movement:=CASE decision.disposition WHEN 'restore_available' THEN 'unfreeze' ELSE 'status_change' END;
    expected:=jsonb_build_object('schema_version','1.0','stage','correction_execution_plan','intent',correction.command_jsonb->'intent',
        'actor_user_id',correction.actor_user_id,'actor_person_id',correction.actor_person_id::text,'authorization_version',correction.authorization_version,
        'root_disposition_id',root.id::text,'reversal_id',inverse.id::text,'correction_decision_id',decision.id::text,
        'disposition',decision.disposition,'source_account_id',source.id::text,'target_account_id',target.id::text,
        'source_condition',source.condition_code,'target_condition',target.condition_code,'target_requires_creation',new_target,
        'custody_assignment_id',custody.id::text,'quantity',to_char(correction.quantity,'FM999999999999990.000'),
        'serial_ids',serial_ids,'movement_type',movement,'ledger_cursor',cutoff,
        'source_balance_quantity',to_char(source_amount,'FM999999999999990.000'),'source_balance_version',source_version,
        'target_balance_quantity',to_char(target_amount,'FM999999999999990.000'),'target_balance_version',target_version,
        'frozen_holds_before',holds,'policy_fingerprint',fingerprint);
    IF public.rsc_canonical_reconciliation_json_0026(correction.plan_jsonb) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(expected)
       OR correction.plan_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
        RAISE EXCEPTION '0159 full historical correction plan mismatch' USING ERRCODE='23514'; END IF;
    command:=jsonb_build_object('operation','post','actor',jsonb_build_object('authorization_version',correction.authorization_version,
        'person_id',correction.actor_person_id::text,'user_id',correction.actor_user_id),'command',jsonb_build_object(
        'effective_at',to_char(correction.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        'movement_type',movement,'posting_key','stock-loss:correct_loss:'||correction.id::text||':'||correction.idempotency_key_hash,
        'source_document_id',correction.id::text,'source_document_type','stock_loss_correction_execution',
        'transaction_no','INV-LOSS-CORR-'||upper(substr(correction.idempotency_key_hash,1,20)),
        'movements',jsonb_build_array(jsonb_build_object('external_boundary_code',NULL,'from_account_id',source.id::text,
            'to_account_id',target.id::text,'quantity',trim_scale(correction.quantity)::text,'serial_ids',serial_ids))));
    IF tx.posting_key IS DISTINCT FROM command->'command'->>'posting_key'
       OR tx.transaction_no IS DISTINCT FROM command->'command'->>'transaction_no'
       OR tx.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(command),'UTF8')),'hex')
       OR observed<>(SELECT COALESCE(max(ledger_cursor),0) FROM public.inventory_transactions) THEN
        RAISE EXCEPTION '0159 canonical correction posting command mismatch' USING ERRCODE='23514'; END IF;
    RETURN expected;
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_check_loss_chain_requests_0159(checked_root uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE root public.stock_loss_dispositions%ROWTYPE; parent public.stock_operation_orders%ROWTYPE;
    inverse public.stock_loss_disposition_reversals%ROWTYPE;
    approval public.stock_loss_correction_decisions%ROWTYPE;
    target jsonb; item record; body jsonb; intent jsonb; expected jsonb; snapshot jsonb;
    all_requests jsonb; returned_requests jsonb:='[]'::jsonb;
BEGIN
    -- This also takes the shared inventory head lock and validates all future
    -- edges; an early historical cursor cannot conceal a malformed successor.
    snapshot:=public.rsc_loss_chain_projection_0159(checked_root,NULL);
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=checked_root;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT jsonb_agg(q.body ORDER BY q.kind,q.body->>'id') INTO all_requests FROM (
        SELECT 'reverse_loss' AS kind,to_jsonb(r) AS body FROM public.stock_loss_disposition_reversals r
        UNION ALL SELECT 'approve_loss_correction',to_jsonb(d) FROM public.stock_loss_correction_decisions d
        UNION ALL SELECT 'correct_loss',to_jsonb(c) FROM public.stock_loss_correction_executions c) q;
    FOR item IN
        SELECT 'reverse_loss' AS kind,to_jsonb(r) AS body FROM public.stock_loss_disposition_reversals r WHERE root_disposition_id=root.id
        UNION ALL SELECT 'approve_loss_correction',to_jsonb(d) FROM public.stock_loss_correction_decisions d WHERE root_disposition_id=root.id
        UNION ALL SELECT 'correct_loss',to_jsonb(c) FROM public.stock_loss_correction_executions c WHERE root_disposition_id=root.id
    LOOP
        body:=item.body;
        IF NOT COALESCE(
            body->>'request_id' ~ '^[A-Za-z0-9._:-]{8,160}$'
            AND body->>'request_hash' ~ '^[a-f0-9]{64}$'
            AND body->>'idempotency_key_hash' ~ '^[a-f0-9]{64}$'
            AND body->>'actor_user_id' ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
            AND body->>'actor_user_id'<>'00000000-0000-0000-0000-000000000000'
            AND body->>'actor_person_id'<>'00000000-0000-0000-0000-000000000000'
            AND (body->>'authorization_version')::bigint>0
            AND (body->>'created_at')::timestamptz>=root.created_at
            AND (body->>'created_at')::timestamptz<=clock_timestamp()
            AND length(body->>'reason') BETWEEN 1 AND 500
            AND btrim(body->>'reason',chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(28)||chr(29)||chr(30)||chr(31)||chr(32)||chr(133)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288))=body->>'reason',false)
           OR EXISTS(SELECT 1 FROM generate_series(1,length(body->>'reason')) p
                WHERE ascii(substr(body->>'reason',p,1))<32 AND ascii(substr(body->>'reason',p,1)) NOT IN (9,10))
           OR (SELECT count(*) FROM jsonb_array_elements(all_requests) r WHERE
                r->>'idempotency_key_hash'=body->>'idempotency_key_hash')<>1
           OR (SELECT count(*) FROM jsonb_array_elements(all_requests) r WHERE
                r->>'actor_user_id'=body->>'actor_user_id' AND r->>'request_id'=body->>'request_id')<>1 THEN
            RAISE EXCEPTION '0159 complete unique historical request context required' USING ERRCODE='23514'; END IF;
        IF (item.kind='reverse_loss' AND body->>'scrap_line_id' IS NOT NULL)
            OR (item.kind='correct_loss' AND body->>'disposition'='scrap') THEN
            PERFORM public.rsc_check_scrap_history_0165(
                CASE item.kind WHEN 'reverse_loss' THEN 'inverse' ELSE 'correction' END,(body->>'id')::uuid);
            returned_requests:=returned_requests||jsonb_build_array(jsonb_build_object(
                'id',body->>'id','action',body#>>'{command_jsonb,action}','request_hash',body->>'request_hash'));
            CONTINUE;
        END IF;
        intent:=jsonb_build_object('root_disposition_id',root.id::text,'expected_root_request_hash',root.request_hash,
            'expected_submission_plan_hash',parent.plan_hash,'reason',body->>'reason');
        IF item.kind='reverse_loss' THEN
            IF body->>'reversed_correction_id' IS NULL THEN target:=to_jsonb(root);
            ELSE SELECT to_jsonb(c) INTO target FROM public.stock_loss_correction_executions c
                WHERE c.id=(body->>'reversed_correction_id')::uuid AND c.root_disposition_id=root.id; END IF;
            IF target IS NULL OR body->>'original_transaction_id' IS DISTINCT FROM target->>'posting_transaction_id'
               OR body->>'original_movement_id' IS DISTINCT FROM target->>'posting_movement_id'
               OR (body->>'created_at')::timestamptz<(target->>'created_at')::timestamptz THEN
                RAISE EXCEPTION '0159 exact reversed execution request required' USING ERRCODE='23514'; END IF;
            intent:=intent||jsonb_build_object('reversed_correction_id',body->'reversed_correction_id',
                'expected_execution_request_hash',target->>'request_hash');
        ELSE
            SELECT * INTO inverse FROM public.stock_loss_disposition_reversals
                WHERE id=(body->>'reversal_id')::uuid AND root_disposition_id=root.id;
            IF inverse.id IS NULL OR (body->>'created_at')::timestamptz<inverse.created_at THEN
                RAISE EXCEPTION '0159 exact inverse request parent required' USING ERRCODE='23514'; END IF;
            intent:=intent||jsonb_build_object('reversal_id',inverse.id::text,'expected_reversal_hash',inverse.request_hash);
            IF item.kind='approve_loss_correction' THEN
                IF body->>'expected_reversal_hash' IS DISTINCT FROM inverse.request_hash
                   OR body->>'actor_user_id'=parent.actor_user_id OR body->>'actor_person_id'=parent.requester_id::text THEN
                    RAISE EXCEPTION '0159 independent correction approval required' USING ERRCODE='23514'; END IF;
                intent:=intent||jsonb_build_object('disposition',body->>'disposition');
            ELSE
                SELECT * INTO approval FROM public.stock_loss_correction_decisions
                    WHERE id=(body->>'correction_decision_id')::uuid AND root_disposition_id=root.id AND reversal_id=inverse.id;
                IF approval.id IS NULL OR approval.expected_reversal_hash IS DISTINCT FROM inverse.request_hash
                   OR body->>'disposition' IS DISTINCT FROM approval.disposition
                   OR (body->>'created_at')::timestamptz<approval.created_at THEN
                    RAISE EXCEPTION '0159 exact independent decision request required' USING ERRCODE='23514'; END IF;
                intent:=intent||jsonb_build_object('correction_decision_id',approval.id::text,
                    'expected_correction_decision_hash',approval.request_hash);
            END IF;
        END IF;
        expected:=jsonb_build_object('schema_version',1,'action',item.kind,'request_id',body->>'request_id','intent',intent);
        IF item.kind<>'approve_loss_correction' THEN
            IF NOT COALESCE(body->>'plan_hash' ~ '^[a-f0-9]{64}$',false) THEN
                RAISE EXCEPTION '0159 exact plan fingerprint required' USING ERRCODE='23514'; END IF;
            expected:=expected||jsonb_build_object('expected_plan_hash',body->>'plan_hash');
        END IF;
        IF body->'command_jsonb' IS DISTINCT FROM expected
           OR public.rsc_canonical_reconciliation_json_0026(body->'command_jsonb') IS DISTINCT FROM
                public.rsc_canonical_reconciliation_json_0026(expected)
           OR body->>'request_hash' IS DISTINCT FROM encode(sha256(convert_to(
                public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
            RAISE EXCEPTION '0159 canonical historical command mismatch' USING ERRCODE='23514'; END IF;
        returned_requests:=returned_requests||jsonb_build_array(jsonb_build_object(
            'id',body->>'id','action',item.kind,'request_hash',body->>'request_hash'));
    END LOOP;
    IF snapshot IS DISTINCT FROM public.rsc_loss_chain_projection_0159(checked_root,NULL) THEN
        RAISE EXCEPTION '0159 request graph changed during proof' USING ERRCODE='23514'; END IF;
    RETURN (SELECT COALESCE(jsonb_agg(r ORDER BY r->>'id'),'[]'::jsonb) FROM jsonb_array_elements(returned_requests) r);
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_check_loss_chain_events_0159(checked_root uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE root public.stock_loss_dispositions%ROWTYPE; parent public.stock_operation_orders%ROWTYPE;
    tx public.inventory_transactions%ROWTYPE; item record; fact jsonb; body jsonb; common jsonb;
    aggregate text; kind text; from_state text; to_state text; key text; reference text; suffix text;
    at timestamptz; identifier uuid; actual jsonb; audit_ids uuid[]; requests jsonb; audit_version bigint;
    inventory_body jsonb; state_body jsonb; outbox_body jsonb; posting_count integer:=0;
BEGIN
    requests:=public.rsc_check_loss_chain_requests_0159(checked_root);
    audit_ids:=public.rsc_loss_inventory_audit_members_0159();
    SELECT version INTO audit_version FROM public.audit_chain_heads WHERE stream_key='inventory';
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=checked_root;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    FOR item IN
        SELECT 'inverse' AS category,to_jsonb(r) AS fact FROM public.stock_loss_disposition_reversals r WHERE root_disposition_id=root.id
        UNION ALL SELECT 'approval',to_jsonb(d) FROM public.stock_loss_correction_decisions d WHERE root_disposition_id=root.id
        UNION ALL SELECT 'correction',to_jsonb(c) FROM public.stock_loss_correction_executions c WHERE root_disposition_id=root.id
    LOOP
        fact:=item.fact;identifier:=(fact->>'id')::uuid;at:=(fact->>'created_at')::timestamptz;
        IF (item.category='inverse' AND fact->>'scrap_line_id' IS NOT NULL)
            OR (item.category='correction' AND fact->>'disposition'='scrap') THEN
            PERFORM public.rsc_check_scrap_history_0165(item.category,identifier);
            CONTINUE;
        END IF;
        common:=jsonb_build_object('root_disposition_id',root.id::text,'operation_id',parent.id::text,
            'line_id',root.line_id::text,'original_headquarters_decision_id',root.headquarters_decision_id::text,
            'requester_person_id',parent.requester_id::text,'actor_user_id',fact->>'actor_user_id',
            'actor_person_id',fact->>'actor_person_id','authorization_version',(fact->>'authorization_version')::bigint,
            'reason',fact->>'reason','request_id',fact->>'request_id','request_hash',fact->>'request_hash');
        IF item.category='approval' THEN
            aggregate:='stock_loss_correction_decision';kind:='stock_loss.correction_approved';
            from_state:='awaiting_headquarters';to_state:='approved';
            body:=common||jsonb_build_object('correction_decision_id',identifier::text,'reversal_id',fact->>'reversal_id',
                'expected_reversal_hash',fact->>'expected_reversal_hash','disposition',fact->>'disposition',
                'approval_stage','approved','stock_effect','none');
            IF EXISTS(SELECT 1 FROM public.inventory_transactions WHERE idempotency_key_hash=fact->>'idempotency_key_hash'
                OR (source_document_type=aggregate AND source_document_id=identifier::text)) THEN
                RAISE EXCEPTION '0159 approval cannot post inventory' USING ERRCODE='23514'; END IF;
        ELSE
            common:=common||jsonb_build_object('posting_transaction_id',fact->>'posting_transaction_id',
                'posting_movement_id',fact->>'posting_movement_id','source_account_id',fact->'source_account_id',
                'target_account_id',fact->'target_account_id','quantity',to_char((fact->>'quantity')::numeric,'FM999999999999990.000'),
                'plan_hash',fact->>'plan_hash','status','posted');
            from_state:='pending';to_state:='posted';
            IF item.category='inverse' THEN
                aggregate:='stock_loss_disposition_reversal';kind:='stock_loss.disposition_reversed';
                body:=common||jsonb_build_object('reversal_id',identifier::text,
                    'original_execution_id',COALESCE(fact->>'reversed_correction_id',root.id::text),
                    'reversed_correction_id',fact->'reversed_correction_id','original_transaction_id',fact->>'original_transaction_id',
                    'original_movement_id',fact->>'original_movement_id','stock_effect','restores_original_frozen_share');
            ELSE
                aggregate:='stock_loss_correction_execution';kind:='stock_loss.correction_posted';
                body:=common||jsonb_build_object('correction_execution_id',identifier::text,
                    'correction_decision_id',fact->>'correction_decision_id','reversal_id',fact->>'reversal_id',
                    'disposition',fact->>'disposition','return_operation_id',fact->'return_operation_id',
                    'return_fulfillment_required',fact->>'disposition'='return_to_region',
                    'stock_effect',CASE fact->>'disposition' WHEN 'restore_available' THEN 'frozen_to_available'
                        WHEN 'convert_used' THEN 'frozen_to_used' WHEN 'convert_damaged' THEN 'frozen_to_damaged'
                        WHEN 'return_to_region' THEN 'frozen_to_return_pending' WHEN 'scrap' THEN 'removed_from_managed_assets' END);
            END IF;
        END IF;
        key:=kind||':'||identifier::text;
        IF (SELECT count(*) FROM public.audit_events WHERE aggregate_type=aggregate AND aggregate_id=identifier::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.audit_events e WHERE e.id=ANY(audit_ids) AND e.stream_key='inventory'
                AND e.aggregate_type=aggregate AND e.aggregate_id=identifier::text AND e.action=kind
                AND e.actor_user_id=fact->>'actor_user_id' AND e.request_id=fact->>'request_id'
                AND e.before_jsonb='{}'::jsonb AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.after_jsonb)=public.rsc_canonical_reconciliation_json_0026(body))
           OR (SELECT count(*) FROM public.state_transition_events WHERE aggregate_type=aggregate AND aggregate_id=identifier::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.state_transition_events e WHERE e.aggregate_type=aggregate AND e.aggregate_id=identifier::text
                AND e.from_status=from_state AND e.to_status=to_state AND e.actor_id=fact->>'actor_user_id'
                AND e.reason=kind AND e.idempotency_key=key AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.metadata_jsonb)=public.rsc_canonical_reconciliation_json_0026(body))
           OR (SELECT count(*) FROM public.outbox_events WHERE aggregate_type=aggregate AND aggregate_id=identifier::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.outbox_events e WHERE e.aggregate_type=aggregate AND e.aggregate_id=identifier::text
                AND e.event_type=kind AND e.idempotency_key=key AND e.created_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.payload_jsonb)=public.rsc_canonical_reconciliation_json_0026(body))
           OR (SELECT count(*) FROM public.notification_events WHERE business_type=aggregate AND business_id=identifier::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.notification_events e WHERE e.business_type=aggregate AND e.business_id=identifier::text
                AND e.event_type=kind AND e.dedup_key=key AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.payload_jsonb)=public.rsc_canonical_reconciliation_json_0026(body)
                AND e.target_manifest_sha256=encode(sha256(convert_to('notification-person-targets.v1'||chr(10)||parent.requester_id::text,'UTF8')),'hex')
                AND (SELECT count(*) FROM public.notification_person_targets WHERE event_id=e.id)=1
                AND EXISTS(SELECT 1 FROM public.notification_person_targets WHERE event_id=e.id AND person_id=parent.requester_id)) THEN
            RAISE EXCEPTION '0159 exact canonical domain event bundle required' USING ERRCODE='23514'; END IF;
    END LOOP;
    FOR item IN
        SELECT false AS inverse,to_jsonb(r) AS fact FROM public.stock_loss_dispositions r WHERE id=root.id
        UNION ALL SELECT true,to_jsonb(r) FROM public.stock_loss_disposition_reversals r WHERE root_disposition_id=root.id
        UNION ALL SELECT false,to_jsonb(c) FROM public.stock_loss_correction_executions c WHERE root_disposition_id=root.id
    LOOP
        fact:=item.fact;SELECT * INTO tx FROM public.inventory_transactions WHERE id=(fact->>'posting_transaction_id')::uuid;
        at:=tx.posted_at;suffix:=CASE WHEN item.inverse THEN 'reversed' ELSE 'posted' END;
        kind:='inventory.transaction.'||suffix;
        IF tx.posted_at IS NULL OR tx.created_at IS DISTINCT FROM tx.posted_at
           OR tx.idempotency_key_hash IS DISTINCT FROM fact->>'idempotency_key_hash'
           OR (fact->>'created_at')::timestamptz>tx.posted_at
           OR NOT EXISTS(SELECT 1 FROM public.inventory_movements WHERE id=(fact->>'posting_movement_id')::uuid AND created_at=at)
           OR EXISTS(SELECT 1 FROM public.inventory_movement_serials WHERE movement_id=(fact->>'posting_movement_id')::uuid
                AND created_at IS DISTINCT FROM at) THEN
            RAISE EXCEPTION '0159 exact posting time and request key required' USING ERRCODE='23514'; END IF;
        reference:='inventory-request-'||encode(sha256(convert_to('cloud_oam.inventory.request.v1','UTF8')||decode('00','hex')||convert_to(fact->>'request_id','UTF8')),'hex');
        inventory_body:=jsonb_build_object('ledger_cursor',tx.ledger_cursor,'movement_count',1,'movement_type',tx.movement_type,
            'posting_key',tx.posting_key,'reversed_transaction_id',tx.reversed_transaction_id::text,'status','posted');
        state_body:=jsonb_build_object('ledger_cursor',tx.ledger_cursor,'movement_type',tx.movement_type,'request_reference',reference);
        outbox_body:=jsonb_build_object('transaction_id',tx.id::text,'transaction_no',tx.transaction_no,'movement_type',tx.movement_type,
            'ledger_cursor',tx.ledger_cursor,'reversed_transaction_id',tx.reversed_transaction_id::text);
        IF (SELECT count(*) FROM public.audit_events WHERE aggregate_type='inventory_transaction' AND aggregate_id=tx.id::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.audit_events e WHERE e.id=ANY(audit_ids) AND e.stream_key='inventory'
                AND e.aggregate_type='inventory_transaction' AND e.aggregate_id=tx.id::text AND e.action=kind
                AND e.actor_user_id=tx.actor_user_id AND e.request_id=reference
                AND (e.before_jsonb IS NULL OR e.before_jsonb='null'::jsonb) AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.after_jsonb)=public.rsc_canonical_reconciliation_json_0026(inventory_body))
           OR (SELECT count(*) FROM public.state_transition_events WHERE aggregate_type='inventory_transaction' AND aggregate_id=tx.id::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.state_transition_events e WHERE e.aggregate_type='inventory_transaction' AND e.aggregate_id=tx.id::text
                AND e.from_status IS NULL AND e.to_status='posted' AND e.actor_id=tx.actor_user_id AND e.reason='inventory_transaction_'||suffix
                AND e.idempotency_key='inventory-state-'||encode(sha256(convert_to('cloud_oam.inventory.state.v1','UTF8')||decode('00','hex')||convert_to(tx.id::text,'UTF8')||decode('00','hex')||convert_to(suffix,'UTF8')),'hex')
                AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.metadata_jsonb)=public.rsc_canonical_reconciliation_json_0026(state_body))
           OR (SELECT count(*) FROM public.outbox_events WHERE aggregate_type='inventory_transaction' AND aggregate_id=tx.id::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.outbox_events e WHERE e.aggregate_type='inventory_transaction' AND e.aggregate_id=tx.id::text
                AND e.event_type=kind AND e.idempotency_key='inventory-outbox-'||encode(sha256(convert_to('cloud_oam.inventory.outbox.v1','UTF8')||decode('00','hex')||convert_to(tx.id::text,'UTF8')||decode('00','hex')||convert_to(suffix,'UTF8')),'hex')
                AND e.created_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.payload_jsonb)=public.rsc_canonical_reconciliation_json_0026(outbox_body)) THEN
            RAISE EXCEPTION '0159 exact canonical inventory posting bundle required' USING ERRCODE='23514'; END IF;
        posting_count:=posting_count+1;
    END LOOP;
    IF requests IS DISTINCT FROM public.rsc_check_loss_chain_requests_0159(checked_root)
       OR audit_version IS DISTINCT FROM (SELECT version FROM public.audit_chain_heads WHERE stream_key='inventory') THEN
        RAISE EXCEPTION '0159 changed event proof snapshot' USING ERRCODE='23514'; END IF;
    RETURN jsonb_build_object('root_disposition_id',root.id::text,'candidate_events',jsonb_array_length(requests),
        'posting_events',posting_count,'audit_version',audit_version);
END;
$function$

-- Current authority applies only to the fact being admitted, never to a
-- historical approver. Historical proof remains independently reconstructible.
CREATE FUNCTION public.rsc_check_scrap_current_0165(checked_kind text, checked_fact uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE fact jsonb; source_table text; root_id uuid; person uuid;
    root public.stock_loss_dispositions%ROWTYPE; parent public.stock_operation_orders%ROWTYPE;
    account public.stock_accounts%ROWTYPE; location public.stock_locations%ROWTYPE;
    custody public.custody_assignments%ROWTYPE; policy public.material_inventory_policies%ROWTYPE;
    effective timestamptz; checked_now timestamptz;
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' OR checked_fact IS NULL THEN
        RAISE EXCEPTION '0165 current scrap fact and read committed required' USING ERRCODE='23514'; END IF;
    source_table:=CASE checked_kind WHEN 'original' THEN 'stock_loss_dispositions'
        WHEN 'correction' THEN 'stock_loss_correction_executions' WHEN 'inverse' THEN 'stock_loss_disposition_reversals' END;
    IF source_table IS NULL THEN
        RAISE EXCEPTION '0165 explicit current scrap fact kind required' USING ERRCODE='23514'; END IF;
    PERFORM id FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 current scrap ledger required' USING ERRCODE='23514'; END IF;
    EXECUTE format('SELECT to_jsonb(f) FROM public.%I f WHERE id=$1',source_table) INTO fact USING checked_fact;
    root_id:=CASE checked_kind WHEN 'original' THEN checked_fact ELSE (fact->>'root_disposition_id')::uuid END;
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=root_id;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT * INTO account FROM public.stock_accounts WHERE id=root.source_account_id;
    person:=(CASE checked_kind WHEN 'original' THEN fact->>'executor_person_id' ELSE fact->>'actor_person_id' END)::uuid;
    effective:=(fact->>'created_at')::timestamptz;
    IF fact IS NULL OR root.id IS NULL OR parent.id IS NULL OR account.id IS NULL OR person IS NULL
        OR parent.operation_type IS DISTINCT FROM 'loss_report' OR account.availability_bucket IS DISTINCT FROM 'frozen'
        OR account.custodian_person_id IS DISTINCT FROM parent.requester_id
        OR account.location_id IS DISTINCT FROM parent.source_location_id
        OR effective IS NULL OR effective>clock_timestamp()
        OR (checked_kind IN ('original','correction') AND fact->>'disposition' IS DISTINCT FROM 'scrap')
        OR (checked_kind='inverse' AND fact->>'scrap_line_id' IS NULL) THEN
        RAISE EXCEPTION '0165 exact current scrap context required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_lock_formal_principal_graph_0026(ARRAY[fact->>'actor_user_id']);
    IF checked_kind='original' THEN
        PERFORM public.rsc_assert_loss_disposition_authority_0150(fact->>'actor_user_id',
            (fact->>'authorization_version')::bigint,person,account.owner_org_id);
    ELSIF checked_kind='correction' THEN
        PERFORM public.rsc_assert_loss_correction_authority_0159(fact->>'actor_user_id',
            (fact->>'authorization_version')::bigint,person,account.owner_org_id,'correct_loss');
    ELSE
        PERFORM public.rsc_assert_scrap_recovery_authority_0165(fact->>'actor_user_id',
            (fact->>'authorization_version')::bigint,person,account.owner_org_id,
            account.location_id,parent.requester_id,'execute');
    END IF;
    PERFORM public.rsc_check_scrap_history_0165(checked_kind,checked_fact);
    PERFORM public.rsc_check_scrap_coordinates_0165(checked_kind,checked_fact);
    PERFORM public.rsc_check_loss_history_graph_0159(root.id);
    PERFORM public.rsc_check_loss_hold_0145(account.id);
    SELECT * INTO location FROM public.stock_locations WHERE id=account.location_id FOR UPDATE;
    PERFORM id FROM public.custody_assignments WHERE location_id=location.id ORDER BY id FOR SHARE;
    PERFORM id FROM public.materials WHERE id=account.material_id FOR SHARE;
    PERFORM id FROM public.material_inventory_policies WHERE material_id=account.material_id ORDER BY id FOR SHARE;
    checked_now:=clock_timestamp();
    SELECT * INTO custody FROM public.custody_assignments WHERE id=(fact->>'custody_assignment_id')::uuid;
    IF location.id IS NULL OR location.status IS DISTINCT FROM 'active' OR location.location_type IS DISTINCT FROM 'personal'
        OR location.owner_org_id IS DISTINCT FROM account.owner_org_id
        OR location.custodian_person_id IS DISTINCT FROM parent.requester_id
        OR custody.id IS NULL OR custody.location_id IS DISTINCT FROM location.id
        OR custody.custodian_person_id IS DISTINCT FROM parent.requester_id
        OR custody.valid_from>checked_now OR (custody.valid_to IS NOT NULL AND custody.valid_to<=checked_now)
        OR (SELECT count(*) FROM public.custody_assignments WHERE location_id=location.id
            AND valid_from<=checked_now AND (valid_to IS NULL OR valid_to>checked_now))<>1
        OR NOT EXISTS(SELECT 1 FROM public.materials WHERE id=account.material_id AND status='active') THEN
        RAISE EXCEPTION '0165 current scrap custody or material changed' USING ERRCODE='23514'; END IF;
    SELECT * INTO policy FROM public.material_inventory_policies WHERE material_id=account.material_id
        AND effective_from<=checked_now AND (effective_to IS NULL OR effective_to>checked_now);
    IF policy.id IS NULL OR (SELECT count(*) FROM public.material_inventory_policies WHERE material_id=account.material_id
        AND effective_from<=checked_now AND (effective_to IS NULL OR effective_to>checked_now))<>1
        OR policy.id::text IS DISTINCT FROM fact#>>'{plan_jsonb,policy_fingerprint,0,1}' THEN
        RAISE EXCEPTION '0165 current scrap tracking policy changed' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.inventory_freezes f
        JOIN public.stocktake_scopes s ON s.id=f.stocktake_scope_id AND s.task_id=f.task_id
        WHERE f.status IN ('active','released','cancelled') AND f.freeze_mode='hard'
          AND ((f.valid_from<=checked_now AND (f.valid_to IS NULL OR f.valid_to>checked_now))
            OR (f.valid_from<=effective AND (f.valid_to IS NULL OR f.valid_to>effective)))
          AND s.owner_org_id=account.owner_org_id AND s.location_id=account.location_id
          AND (s.scope_mode='location_all' OR (s.scope_mode='filtered'
            AND (s.material_id IS NULL OR s.material_id=account.material_id)
            AND (s.condition_code IS NULL OR s.condition_code=account.condition_code)
            AND (s.availability_bucket IS NULL OR s.availability_bucket=account.availability_bucket)))) THEN
        RAISE EXCEPTION '0165 scrap account is hard frozen' USING ERRCODE='23514'; END IF;
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_check_scrap_current_0165(text,uuid)
FROM PUBLIC,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox,star_oam_backup;

CREATE OR REPLACE FUNCTION public.rsc_check_loss_disposition_0150(checked_fact uuid, require_current boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE root public.stock_loss_dispositions%ROWTYPE;
BEGIN
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=checked_fact;
    IF root.id IS NULL OR require_current IS NULL THEN
        RAISE EXCEPTION '0159 exact root and current-proof mode required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_check_loss_history_graph_0159(root.id);
    IF root.disposition='return_to_region' THEN
        PERFORM public.rsc_check_loss_return_0152(root.id,require_current);
    ELSIF root.disposition='scrap' AND require_current THEN
        PERFORM public.rsc_check_scrap_current_0165('original',root.id);
    ELSIF require_current THEN
        PERFORM public.rsc_check_loss_current_normal_original_0159(root.id);
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_dispatch_stock_return_0100()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
    checked_order uuid;
    scrap record;
    checked_cancel uuid;
    checked_tx uuid;
    tx public.inventory_transactions%ROWTYPE;
BEGIN
    -- Unrelated event aggregates are an existing no-op, before any lock.
    IF TG_TABLE_NAME IN ('audit_events','outbox_events','state_transition_events') THEN
        IF NEW.aggregate_type NOT IN ('stock_operation_order','stock_operation_cancellation','inventory_transaction') THEN RETURN NULL; END IF;
    END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key = 'inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0100 inventory ledger head missing' USING ERRCODE = '23514'; END IF;
    IF TG_TABLE_NAME = 'stock_operation_orders' THEN checked_order := NEW.id;
    ELSIF TG_TABLE_NAME = 'stock_operation_lines' THEN checked_order := NEW.operation_id;
    ELSIF TG_TABLE_NAME = 'stock_operation_serials' THEN
        SELECT operation_id INTO checked_order FROM public.stock_operation_lines WHERE id = NEW.line_id;
    ELSIF TG_TABLE_NAME = 'stock_operation_cancellations' THEN checked_order := NEW.operation_id; checked_cancel := NEW.id;
    ELSIF TG_TABLE_NAME IN ('inventory_transactions','inventory_movements','inventory_movement_serials') THEN
        IF TG_TABLE_NAME = 'inventory_transactions' THEN checked_tx := NEW.id; ELSE checked_tx := NEW.transaction_id; END IF;
    ELSE
        IF NEW.aggregate_type = 'stock_operation_order' THEN checked_order := NEW.aggregate_id::uuid;
        ELSIF NEW.aggregate_type = 'stock_operation_cancellation' THEN
            SELECT operation_id, id INTO checked_order, checked_cancel FROM public.stock_operation_cancellations WHERE id = NEW.aggregate_id::uuid;
            IF checked_order IS NULL THEN RAISE EXCEPTION '0100 cancellation event detached from its command' USING ERRCODE = '23514'; END IF;
        ELSIF NEW.aggregate_type = 'inventory_transaction' THEN checked_tx := NEW.aggregate_id::uuid;
        ELSE RETURN NULL; END IF;
    END IF;
    IF checked_tx IS NOT NULL THEN
        SELECT * INTO tx FROM public.inventory_transactions WHERE id = checked_tx;
        IF NOT FOUND THEN RAISE EXCEPTION '0100 return evidence has no stock transaction' USING ERRCODE = '23514'; END IF;
        PERFORM public.rsc_check_loss_transaction_0145(tx.id);
        IF tx.source_document_type='stock_operation_loss' THEN RETURN NULL; END IF;
        -- The complete current loss proof above already checks this posting.
        -- Admit only a retained original loss-return inverse with its exact
        -- stop witness; ordinary return and generic reversals remain blocked.
        IF tx.source_document_type='stock_loss_disposition_reversal' AND EXISTS(
            SELECT 1 FROM public.stock_loss_disposition_reversals inverse
            JOIN public.stock_loss_dispositions root ON root.id=inverse.root_disposition_id
            JOIN public.stock_loss_return_stops stop ON stop.reversal_id=inverse.id
                AND stop.root_disposition_id=root.id AND stop.return_operation_id=root.return_operation_id
            WHERE inverse.posting_transaction_id=tx.id AND inverse.reversed_correction_id IS NULL
                AND root.disposition='return_to_region' AND root.posting_transaction_id=tx.reversed_transaction_id
                AND inverse.original_transaction_id=tx.reversed_transaction_id) THEN
            PERFORM public.rsc_check_loss_return_stop_0163((SELECT id
                FROM public.stock_loss_disposition_reversals WHERE posting_transaction_id=tx.id));
            RETURN NULL;
        END IF;
        IF tx.reversed_transaction_id IS NOT NULL THEN
            IF EXISTS (SELECT 1 FROM public.inventory_transactions original WHERE original.id = tx.reversed_transaction_id
                  AND original.source_document_type = 'stock_operation_return')
               OR EXISTS (SELECT 1 FROM public.stock_operation_orders WHERE posting_transaction_id = tx.reversed_transaction_id)
               OR EXISTS (SELECT 1 FROM public.stock_operation_cancellations WHERE posting_transaction_id = tx.reversed_transaction_id) THEN
                RAISE EXCEPTION '0100 return stock cannot use generic reversal' USING ERRCODE = '23514'; END IF;
            IF EXISTS (SELECT 1 FROM public.stock_operation_lines line
                JOIN public.work_order_material_lines origin ON origin.id = line.source_recovery_line_id
                JOIN public.work_order_material_operations recovery ON recovery.id = origin.operation_id
                JOIN public.stock_operation_orders parent ON parent.id = line.operation_id
                JOIN public.inventory_transactions reserved ON reserved.id = parent.posting_transaction_id
                WHERE recovery.posting_transaction_id = tx.reversed_transaction_id AND reserved.ledger_cursor < tx.ledger_cursor
                  AND NOT EXISTS (SELECT 1 FROM public.stock_operation_cancellations cancelled
                    JOIN public.inventory_transactions released ON released.id = cancelled.posting_transaction_id
                    WHERE cancelled.operation_id = parent.id AND released.ledger_cursor < tx.ledger_cursor)) THEN
                RAISE EXCEPTION '0100 active return prevents reversal of its original recovery' USING ERRCODE = '23514'; END IF;
        END IF;
        IF tx.source_document_type='stock_operation_return_outbound' THEN
            SELECT id INTO checked_order FROM public.stock_operation_outbounds WHERE posting_transaction_id=tx.id;
            IF checked_order IS NULL THEN RAISE EXCEPTION '0103 detached return departure' USING ERRCODE='23514'; END IF;
            PERFORM public.rsc_check_stock_return_outbound_0103(checked_order);
            RETURN NULL;
        END IF;
        IF tx.source_document_type = 'stock_operation_return' THEN
            SELECT id INTO checked_order FROM public.stock_operation_orders WHERE posting_transaction_id = tx.id;
            IF checked_order IS NULL THEN
                SELECT operation_id, id INTO checked_order, checked_cancel FROM public.stock_operation_cancellations WHERE posting_transaction_id = tx.id;
            END IF;
            IF checked_order IS NULL THEN RAISE EXCEPTION '0100 detached return inventory transaction' USING ERRCODE = '23514'; END IF;
        ELSIF EXISTS (SELECT 1 FROM public.inventory_movements movement
            JOIN public.stock_operation_lines line ON line.reserved_account_id IN (movement.from_account_id,movement.to_account_id)
            WHERE movement.transaction_id = tx.id AND line.operation_type='return') THEN
            RAISE EXCEPTION '0100 held return stock requires its exact business document' USING ERRCODE = '23514';
        ELSE RETURN NULL; END IF;
    END IF;
    IF checked_order IS NULL THEN RAISE EXCEPTION '0100 return evidence is detached' USING ERRCODE = '23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_operation_orders WHERE id=checked_order AND operation_type='scrap') THEN
        IF checked_cancel IS NOT NULL OR (SELECT count(*) FROM public.stock_scrap_lines WHERE operation_id=checked_order)<>1 THEN
            RAISE EXCEPTION '0165 exact scrap order requires its dedicated fact' USING ERRCODE='23514'; END IF;
        SELECT source_kind,CASE source_kind WHEN 'original' THEN root_disposition_id ELSE correction_execution_id END AS fact_id
            INTO scrap FROM public.stock_scrap_lines WHERE operation_id=checked_order;
        PERFORM public.rsc_check_scrap_current_0165(scrap.source_kind,scrap.fact_id);
        RETURN NULL;
    END IF;
    IF EXISTS(SELECT 1 FROM public.stock_operation_orders WHERE id=checked_order AND operation_type='loss_report') THEN
        IF checked_cancel IS NOT NULL THEN RAISE EXCEPTION '0145 loss requires its dedicated reversal' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_check_loss_submission_0145(checked_order);
        RETURN NULL;
    END IF;
    PERFORM public.rsc_check_stock_return_0100(checked_order, checked_cancel);
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_check_serial_lifecycle_0092(checked_serial uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
    serial public.inventory_serials%ROWTYPE;
    position public.serial_current_positions%ROWTYPE;
    move record;
    scrap record;
    recovery_id uuid;
    original_move public.inventory_movements%ROWTYPE;
    snapshots jsonb := '{}'::jsonb;
    prior jsonb;
    expected_account uuid := NULL;
    expected_owner uuid := NULL;
    expected_movement uuid := NULL;
    expected_cursor bigint := 0;
    expected_status text := 'active';
    terminal_time timestamptz := NULL;
BEGIN
    SELECT * INTO serial FROM public.inventory_serials WHERE id = checked_serial;
    IF NOT FOUND THEN
        RAISE EXCEPTION '0092 serial identity missing' USING ERRCODE = '23514';
    END IF;
    FOR move IN
        SELECT movement.*, tx.ledger_cursor, tx.movement_type, tx.source_document_type, tx.reversed_transaction_id,
               source.owner_org_id AS source_owner, target.owner_org_id AS target_owner, tx.effective_at, source.material_id AS source_material, target.material_id AS target_material,
               source.lot_id AS source_lot, target.lot_id AS target_lot
        FROM public.inventory_movement_serials sn
        JOIN public.inventory_movements movement ON movement.id = sn.movement_id AND movement.transaction_id = sn.transaction_id
        JOIN public.inventory_transactions tx ON tx.id = movement.transaction_id AND tx.status = 'posted'
        LEFT JOIN public.stock_accounts source ON source.id = movement.from_account_id
        LEFT JOIN public.stock_accounts target ON target.id = movement.to_account_id
        WHERE sn.serial_id = checked_serial ORDER BY tx.ledger_cursor, movement.line_no
    LOOP
        IF move.movement_type='reversal' AND move.source_document_type='stock_loss_disposition_reversal'
            AND expected_status='scrapped' THEN
            SELECT * INTO original_move FROM public.inventory_movements WHERE id=expected_movement;
            prior:=snapshots->expected_movement::text;
            SELECT id INTO recovery_id FROM public.stock_loss_disposition_reversals
                WHERE posting_transaction_id=move.transaction_id AND original_movement_id=expected_movement
                  AND scrap_line_id IS NOT NULL AND scrap_recovery_execution_id IS NOT NULL;
            IF original_move.id IS NULL OR recovery_id IS NULL OR prior IS NULL
                OR move.ledger_cursor<=expected_cursor OR expected_account IS NOT NULL
                OR move.from_account_id IS NOT NULL OR move.to_account_id IS NULL
                OR original_move.transaction_id IS DISTINCT FROM move.reversed_transaction_id
                OR original_move.to_account_id IS NOT NULL OR original_move.from_account_id IS DISTINCT FROM move.to_account_id
                OR move.quantity IS DISTINCT FROM original_move.quantity
                OR move.external_boundary_code IS DISTINCT FROM 'stock_operation_scrap'
                OR original_move.external_boundary_code IS DISTINCT FROM move.external_boundary_code
                OR prior->>'status' IS DISTINCT FROM 'active'
                OR (prior->>'account')::uuid IS DISTINCT FROM move.to_account_id
                OR (prior->>'owner')::uuid IS DISTINCT FROM move.target_owner
                OR move.target_material IS DISTINCT FROM serial.material_id OR move.target_lot IS DISTINCT FROM serial.lot_id THEN
                RAISE EXCEPTION '0165 serial recovery requires the last exact scrap edge' USING ERRCODE='23514'; END IF;
            PERFORM public.rsc_check_scrap_history_0165('inverse',recovery_id);
            expected_status:='active'; terminal_time:=move.created_at;
            expected_owner:=(prior->>'owner')::uuid; expected_account:=move.to_account_id;
            expected_movement:=move.id; expected_cursor:=move.ledger_cursor;
            CONTINUE;
        END IF;
        IF move.movement_type = 'reversal' AND move.source_document_type = 'work_order_material' THEN
            SELECT * INTO original_move FROM public.inventory_movements WHERE id = expected_movement;
            prior := snapshots->expected_movement::text;
            IF NOT FOUND OR prior IS NULL OR original_move.transaction_id IS DISTINCT FROM move.reversed_transaction_id
               OR move.ledger_cursor <= expected_cursor OR move.from_account_id IS DISTINCT FROM expected_account
               OR move.from_account_id IS DISTINCT FROM original_move.to_account_id
               OR move.to_account_id IS DISTINCT FROM original_move.from_account_id
               OR move.quantity <> original_move.quantity OR move.external_boundary_code IS DISTINCT FROM original_move.external_boundary_code
               OR (move.from_account_id IS NOT NULL AND (move.source_material IS DISTINCT FROM serial.material_id OR move.source_lot IS DISTINCT FROM serial.lot_id))
               OR (move.to_account_id IS NOT NULL AND (move.target_material IS DISTINCT FROM serial.material_id OR move.target_lot IS DISTINCT FROM serial.lot_id))
               OR move.quantity <> (SELECT count(*) FROM public.inventory_movement_serials WHERE movement_id = move.id)
               OR (SELECT count(*) FROM public.material_inventory_policies policy WHERE policy.material_id = serial.material_id
                    AND policy.effective_from <= move.effective_at AND (policy.effective_to IS NULL OR policy.effective_to > move.effective_at)
                    AND policy.tracking_mode IN ('serial','lot_and_serial')) <> 1
               OR NOT EXISTS (SELECT 1 FROM public.work_order_reversal_items item
                    JOIN public.work_order_material_operations original ON original.id = item.original_operation_id
                    JOIN public.work_order_material_operations inverse ON inverse.id = item.inverse_operation_id
                    JOIN public.work_order_reversals parent ON parent.id = item.reversal_id
                    WHERE original.posting_transaction_id = move.reversed_transaction_id AND inverse.posting_transaction_id = move.transaction_id
                      AND inverse.operation_type = 'reverse' AND original.operation_type <> 'reverse'
                      AND original.oam_work_order_id = parent.oam_work_order_id AND inverse.oam_work_order_id = parent.oam_work_order_id)
               OR (prior->>'account')::uuid IS DISTINCT FROM move.to_account_id THEN
                RAISE EXCEPTION '0098 serial inverse requires the last exact original movement' USING ERRCODE = '23514'; END IF;
            IF expected_status IS DISTINCT FROM prior->>'status' THEN terminal_time := move.created_at; END IF;
            expected_status := prior->>'status';
            expected_owner := (prior->>'owner')::uuid;
            expected_account := move.to_account_id;
            expected_movement := move.id;
            expected_cursor := move.ledger_cursor;
            CONTINUE;
        END IF;
        snapshots := snapshots || jsonb_build_object(move.id::text,jsonb_build_object(
            'status',expected_status,'owner',expected_owner::text,'account',expected_account::text));
        IF move.ledger_cursor <= expected_cursor OR move.from_account_id IS DISTINCT FROM expected_account
           OR (expected_status <> 'active' AND NOT (
               expected_status = 'consumed' AND move.movement_type = 'inbound'
               AND move.source_document_type = 'work_order_material' AND move.external_boundary_code IS NOT DISTINCT FROM 'work_order_material_recover'
               AND move.from_account_id IS NULL AND move.to_account_id IS NOT NULL AND move.target_owner IS NOT DISTINCT FROM expected_owner
               AND EXISTS (SELECT 1 FROM public.work_order_replacements replacement
                   JOIN public.work_order_material_operations recovery ON recovery.id = replacement.recover_operation_id
                     AND recovery.replacement_id = replacement.id
                   JOIN public.work_order_replacement_pairs pair ON pair.replacement_id = replacement.id
                     AND pair.operation_id = replacement.consume_operation_id AND pair.removed_serial_id = checked_serial
                   WHERE recovery.posting_transaction_id = move.transaction_id)))
           OR (move.from_account_id IS NULL AND move.to_account_id IS NULL)
           OR (move.from_account_id IS NOT NULL AND (move.source_material IS DISTINCT FROM serial.material_id OR move.source_lot IS DISTINCT FROM serial.lot_id))
           OR (move.to_account_id IS NOT NULL AND (move.target_material IS DISTINCT FROM serial.material_id OR move.target_lot IS DISTINCT FROM serial.lot_id))
           OR move.quantity <> (SELECT count(*) FROM public.inventory_movement_serials WHERE movement_id = move.id)
           OR (SELECT count(*) FROM public.material_inventory_policies policy
               WHERE policy.material_id = serial.material_id AND policy.effective_from <= move.effective_at
                 AND (policy.effective_to IS NULL OR policy.effective_to > move.effective_at)
                 AND policy.tracking_mode IN ('serial', 'lot_and_serial')) <> 1 THEN
            RAISE EXCEPTION '0092 serial ledger chain or dimensions invalid' USING ERRCODE = '23514';
        END IF;
        IF expected_status = 'consumed' THEN
            expected_status := 'active';
            terminal_time := move.created_at;
        END IF;
        IF move.movement_type = 'consume' THEN
            IF move.source_document_type <> 'work_order_material'
               OR move.external_boundary_code IS DISTINCT FROM 'work_order_material_consume'
               OR move.from_account_id IS NULL OR move.to_account_id IS NOT NULL THEN
                RAISE EXCEPTION '0092 serial consumption requires original work order' USING ERRCODE = '23514';
            END IF;
            expected_status := 'consumed';
            terminal_time := move.created_at;
        ELSIF move.movement_type = 'scrap' THEN
            SELECT source_kind,CASE source_kind WHEN 'original' THEN root_disposition_id
                ELSE correction_execution_id END AS fact_id INTO scrap
                FROM public.stock_scrap_lines WHERE posting_movement_id=move.id AND posting_transaction_id=move.transaction_id;
            IF scrap.fact_id IS NULL OR move.from_account_id IS NULL OR move.to_account_id IS NOT NULL
                OR move.external_boundary_code IS DISTINCT FROM 'stock_operation_scrap'
                OR move.source_document_type IS DISTINCT FROM (CASE scrap.source_kind
                    WHEN 'original' THEN 'stock_loss_disposition' ELSE 'stock_loss_correction_execution' END) THEN
                RAISE EXCEPTION '0165 serial scrap requires its exact retained fact' USING ERRCODE='23514'; END IF;
            PERFORM public.rsc_check_scrap_history_0165(scrap.source_kind,scrap.fact_id);
            expected_status:='scrapped'; terminal_time:=move.created_at;
        END IF;
        expected_account := move.to_account_id;
        expected_movement := move.id;
        expected_owner := CASE WHEN move.to_account_id IS NOT NULL THEN move.target_owner ELSE move.source_owner END;
        expected_cursor := move.ledger_cursor;
    END LOOP;
    SELECT * INTO position FROM public.serial_current_positions WHERE serial_id = checked_serial;
    IF serial.lifecycle_status <> expected_status
       OR (terminal_time IS NOT NULL AND serial.updated_at IS DISTINCT FROM terminal_time)
       OR (expected_movement IS NULL AND FOUND)
       OR (expected_movement IS NOT NULL AND (NOT FOUND
           OR position.last_movement_id IS DISTINCT FROM expected_movement
           OR position.stock_account_id IS DISTINCT FROM expected_account)) THEN
        RAISE EXCEPTION '0092 serial lifecycle or position projection drift' USING ERRCODE = '23514';
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_check_loss_current_correction_0159(checked_fact uuid, required_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE fact jsonb; source_table text; root public.stock_loss_dispositions%ROWTYPE;
    parent public.stock_operation_orders%ROWTYPE; source public.stock_accounts%ROWTYPE;
    target public.stock_accounts%ROWTYPE; location public.stock_locations%ROWTYPE;
    custody public.custody_assignments%ROWTYPE; policy public.material_inventory_policies%ROWTYPE;
    effective timestamptz; checked_now timestamptz; account_ids uuid[];
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0159 correction COMMIT requires read committed' USING ERRCODE='23514'; END IF;
    source_table:=CASE required_action WHEN 'reverse_loss' THEN 'stock_loss_disposition_reversals'
        WHEN 'approve_loss_correction' THEN 'stock_loss_correction_decisions'
        WHEN 'correct_loss' THEN 'stock_loss_correction_executions' END;
    IF source_table IS NULL OR checked_fact IS NULL THEN
        RAISE EXCEPTION '0159 exact correction action and fact required' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0159 correction ledger required' USING ERRCODE='23514'; END IF;
    EXECUTE format('SELECT to_jsonb(f) FROM public.%I f WHERE id=$1',source_table) INTO fact USING checked_fact;
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=(fact->>'root_disposition_id')::uuid;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    IF fact IS NULL OR root.id IS NULL OR parent.id IS NULL OR parent.operation_type<>'loss_report' THEN
        RAISE EXCEPTION '0159 exact retained correction context required' USING ERRCODE='23514'; END IF;
    IF required_action='reverse_loss' AND fact->>'scrap_line_id' IS NOT NULL THEN
        PERFORM public.rsc_check_scrap_current_0165('inverse',checked_fact); RETURN;
    ELSIF required_action='correct_loss' AND fact->>'disposition'='scrap' THEN
        PERFORM public.rsc_check_scrap_current_0165('correction',checked_fact); RETURN;
    END IF;
    SELECT * INTO source FROM public.stock_accounts WHERE id=root.source_account_id;
    PERFORM public.rsc_lock_formal_principal_graph_0026(ARRAY[fact->>'actor_user_id']::text[]);
    PERFORM public.rsc_assert_loss_correction_authority_0159(fact->>'actor_user_id',(fact->>'authorization_version')::bigint,
        (fact->>'actor_person_id')::uuid,source.owner_org_id,required_action);
    IF required_action='approve_loss_correction' AND
        (fact->>'actor_user_id'=parent.actor_user_id OR fact->>'actor_person_id'=parent.requester_id::text) THEN
        RAISE EXCEPTION '0159 independent correction approval required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_check_loss_history_graph_0159(root.id);
    PERFORM public.rsc_check_loss_correction_coordinates_0159(fact,required_action);
    PERFORM public.rsc_check_loss_hold_0145(root.source_account_id);
    -- Approval is a stock-neutral independent fact. Inventory admission below
    -- belongs to the writer that actually moves the approved stock.
    IF required_action='approve_loss_correction' THEN RETURN; END IF;
    effective:=(fact->>'created_at')::timestamptz;
    SELECT * INTO source FROM public.stock_accounts WHERE id=(fact->>'source_account_id')::uuid;
    SELECT * INTO target FROM public.stock_accounts WHERE id=(fact->>'target_account_id')::uuid;
    IF source.id IS NULL OR target.id IS NULL OR source.location_id IS DISTINCT FROM target.location_id
       OR source.material_id IS DISTINCT FROM target.material_id OR source.owner_org_id IS DISTINCT FROM target.owner_org_id
       OR source.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR target.custodian_person_id IS DISTINCT FROM parent.requester_id THEN
        RAISE EXCEPTION '0159 exact current correction accounts required' USING ERRCODE='23514'; END IF;
    account_ids:=ARRAY[source.id,target.id];
    SELECT * INTO location FROM public.stock_locations WHERE id=source.location_id FOR UPDATE;
    PERFORM id FROM public.custody_assignments WHERE location_id=location.id ORDER BY id FOR SHARE;
    PERFORM id FROM public.materials WHERE id=source.material_id FOR SHARE;
    PERFORM id FROM public.material_inventory_policies WHERE material_id=source.material_id ORDER BY id FOR SHARE;
    checked_now:=clock_timestamp();
    SELECT * INTO custody FROM public.custody_assignments WHERE id=(fact->>'custody_assignment_id')::uuid;
    IF location.id IS NULL OR location.status<>'active' OR location.location_type<>'personal'
       OR location.owner_org_id IS DISTINCT FROM source.owner_org_id
       OR location.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR custody.id IS NULL OR custody.location_id IS DISTINCT FROM location.id
       OR custody.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR custody.valid_from>checked_now OR (custody.valid_to IS NOT NULL AND custody.valid_to<=checked_now)
       OR (SELECT count(*) FROM public.custody_assignments c WHERE c.location_id=location.id
            AND c.valid_from<=checked_now AND (c.valid_to IS NULL OR c.valid_to>checked_now))<>1
       OR NOT EXISTS(SELECT 1 FROM public.materials WHERE id=source.material_id AND status='active') THEN
        RAISE EXCEPTION '0159 current correction custody or material changed' USING ERRCODE='23514'; END IF;
    SELECT * INTO policy FROM public.material_inventory_policies WHERE material_id=source.material_id
        AND effective_from<=checked_now AND (effective_to IS NULL OR effective_to>checked_now);
    IF policy.id IS NULL OR (SELECT count(*) FROM public.material_inventory_policies WHERE material_id=source.material_id
        AND effective_from<=checked_now AND (effective_to IS NULL OR effective_to>checked_now))<>1
       OR policy.id::text IS DISTINCT FROM fact->'plan_jsonb'->'policy_fingerprint'->0->>1 THEN
        RAISE EXCEPTION '0159 current correction tracking policy changed' USING ERRCODE='23514'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.inventory_opening_establishments e
        JOIN public.stocktake_postings p ON p.id=e.posting_id AND p.task_id=e.task_id AND p.round_id=e.round_id
        WHERE e.owner_org_id=source.owner_org_id AND e.location_id=source.location_id AND e.established_at<=effective
          AND public.rsc_loss_opening_history_complete_0159(e.task_id,p.inventory_transaction_id)) THEN
        RAISE EXCEPTION '0159 complete established opening required' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.inventory_freezes f JOIN public.stocktake_scopes s ON s.id=f.stocktake_scope_id AND s.task_id=f.task_id
        JOIN public.stock_accounts a ON a.id=ANY(account_ids)
        WHERE f.status IN ('active','released','cancelled') AND f.freeze_mode='hard'
          AND ((f.valid_from<=checked_now AND (f.valid_to IS NULL OR f.valid_to>checked_now))
            OR (f.valid_from<=effective AND (f.valid_to IS NULL OR f.valid_to>effective)))
          AND s.owner_org_id=a.owner_org_id AND s.location_id=a.location_id
          AND (s.scope_mode='location_all' OR (s.scope_mode='filtered'
            AND (s.material_id IS NULL OR s.material_id=a.material_id)
            AND (s.condition_code IS NULL OR s.condition_code=a.condition_code)
            AND (s.availability_bucket IS NULL OR s.availability_bucket=a.availability_bucket)))) THEN
        RAISE EXCEPTION '0159 correction source or target is hard frozen' USING ERRCODE='23514'; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_check_loss_correction_admission_0159()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE parent_actor text; requester uuid; owner_id uuid; required_action text;
    seal public.stock_loss_inverse_request_seals%ROWTYPE; other_table text; collision boolean;
BEGIN
    IF TG_OP<>'INSERT' OR TG_TABLE_SCHEMA<>'public' THEN
        RAISE EXCEPTION '0159 invalid admission trigger' USING ERRCODE='23514'; END IF;
    required_action:=CASE TG_TABLE_NAME
        WHEN 'stock_loss_disposition_reversals' THEN 'reverse_loss'
        WHEN 'stock_loss_correction_decisions' THEN 'approve_loss_correction'
        WHEN 'stock_loss_correction_executions' THEN 'correct_loss'
        WHEN 'stock_loss_inverse_request_seals' THEN 'reverse_loss' WHEN 'stock_loss_correction_approval_seals' THEN 'approve_loss_correction' WHEN 'stock_loss_correction_execution_seals' THEN 'correct_loss' END;
    SELECT p.actor_user_id,p.requester_id,l.owner_org_id INTO parent_actor,requester,owner_id
        FROM public.stock_loss_dispositions r JOIN public.stock_operation_orders p ON p.id=r.operation_id
        JOIN public.stock_locations l ON l.id=p.source_location_id
        WHERE r.id=NEW.root_disposition_id AND p.operation_type='loss_report';
    IF required_action IS NULL OR owner_id IS NULL OR requester IS NULL OR parent_actor IS NULL
       OR (required_action='approve_loss_correction' AND
            (NEW.actor_user_id=parent_actor OR NEW.actor_person_id=requester)) THEN
        RAISE EXCEPTION '0159 exact loss context and independent approver required' USING ERRCODE='23514'; END IF;
    IF TG_TABLE_NAME='stock_loss_disposition_reversals' AND to_jsonb(NEW)->>'scrap_line_id' IS NOT NULL THEN
        PERFORM public.rsc_check_scrap_current_0165('inverse',NEW.id);
    ELSE
    PERFORM public.rsc_assert_loss_correction_authority_0159(NEW.actor_user_id,NEW.authorization_version,
        NEW.actor_person_id,owner_id,required_action);
    END IF;
    IF TG_TABLE_NAME='stock_loss_inverse_request_seals' THEN
        SELECT * INTO seal FROM public.stock_loss_inverse_request_seals WHERE id=NEW.id;
        IF seal.id IS NULL THEN
            RAISE EXCEPTION '0159 retained inverse seal required' USING ERRCODE='23514'; END IF;
        FOREACH other_table IN ARRAY ARRAY['stock_loss_disposition_reversals',
                'stock_loss_correction_decisions','stock_loss_correction_executions'] LOOP
            EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE idempotency_key_hash=ANY($1) '
                'OR (actor_user_id=$2 AND request_id=$3))',other_table)
                INTO collision USING ARRAY[seal.reversal_key_hash,seal.approval_key_hash,seal.correction_key_hash],
                    seal.actor_user_id,seal.request_id;
            IF collision THEN RAISE EXCEPTION '0159 written request cannot be sealed' USING ERRCODE='23514'; END IF;
        END LOOP;
    ELSIF EXISTS(SELECT 1 FROM public.stock_loss_inverse_request_seals s
        WHERE NEW.idempotency_key_hash IN (s.reversal_key_hash,s.approval_key_hash,s.correction_key_hash)
            OR (s.actor_user_id=NEW.actor_user_id AND s.request_id=NEW.request_id)) THEN
        RAISE EXCEPTION '0159 sealed request cannot be written' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_dispatch_stock_return_0100()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
    checked_order uuid;
    scrap record;
    checked_cancel uuid;
    checked_tx uuid;
    tx public.inventory_transactions%ROWTYPE;
BEGIN
    -- Unrelated event aggregates are an existing no-op, before any lock.
    IF TG_TABLE_NAME IN ('audit_events','outbox_events','state_transition_events') THEN
        IF NEW.aggregate_type NOT IN ('stock_operation_order','stock_operation_cancellation','inventory_transaction') THEN RETURN NULL; END IF;
    END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key = 'inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0100 inventory ledger head missing' USING ERRCODE = '23514'; END IF;
    IF TG_TABLE_NAME = 'stock_operation_orders' THEN checked_order := NEW.id;
    ELSIF TG_TABLE_NAME = 'stock_operation_lines' THEN checked_order := NEW.operation_id;
    ELSIF TG_TABLE_NAME = 'stock_operation_serials' THEN
        SELECT operation_id INTO checked_order FROM public.stock_operation_lines WHERE id = NEW.line_id;
    ELSIF TG_TABLE_NAME = 'stock_operation_cancellations' THEN checked_order := NEW.operation_id; checked_cancel := NEW.id;
    ELSIF TG_TABLE_NAME IN ('inventory_transactions','inventory_movements','inventory_movement_serials') THEN
        IF TG_TABLE_NAME = 'inventory_transactions' THEN checked_tx := NEW.id; ELSE checked_tx := NEW.transaction_id; END IF;
    ELSE
        IF NEW.aggregate_type = 'stock_operation_order' THEN checked_order := NEW.aggregate_id::uuid;
        ELSIF NEW.aggregate_type = 'stock_operation_cancellation' THEN
            SELECT operation_id, id INTO checked_order, checked_cancel FROM public.stock_operation_cancellations WHERE id = NEW.aggregate_id::uuid;
            IF checked_order IS NULL THEN RAISE EXCEPTION '0100 cancellation event detached from its command' USING ERRCODE = '23514'; END IF;
        ELSIF NEW.aggregate_type = 'inventory_transaction' THEN checked_tx := NEW.aggregate_id::uuid;
        ELSE RETURN NULL; END IF;
    END IF;
    IF checked_tx IS NOT NULL THEN
        SELECT * INTO tx FROM public.inventory_transactions WHERE id = checked_tx;
        IF NOT FOUND THEN RAISE EXCEPTION '0100 return evidence has no stock transaction' USING ERRCODE = '23514'; END IF;
        PERFORM public.rsc_check_loss_transaction_0145(tx.id);
        IF tx.source_document_type='stock_operation_loss' THEN RETURN NULL; END IF;
        -- The complete current loss proof above already checks this posting.
        -- Admit only a retained original loss-return inverse with its exact
        -- stop witness; ordinary return and generic reversals remain blocked.
        IF tx.source_document_type='stock_loss_disposition_reversal' AND EXISTS(
            SELECT 1 FROM public.stock_loss_disposition_reversals inverse
            JOIN public.stock_loss_dispositions root ON root.id=inverse.root_disposition_id
            JOIN public.stock_loss_return_stops stop ON stop.reversal_id=inverse.id
                AND stop.root_disposition_id=root.id AND stop.return_operation_id=root.return_operation_id
            WHERE inverse.posting_transaction_id=tx.id AND inverse.reversed_correction_id IS NULL
                AND root.disposition='return_to_region' AND root.posting_transaction_id=tx.reversed_transaction_id
                AND inverse.original_transaction_id=tx.reversed_transaction_id) THEN
            PERFORM public.rsc_check_loss_return_stop_0163((SELECT id
                FROM public.stock_loss_disposition_reversals WHERE posting_transaction_id=tx.id));
            RETURN NULL;
        END IF;
        IF tx.source_document_type='stock_loss_disposition_reversal' AND EXISTS(
            SELECT 1 FROM public.stock_loss_disposition_reversals inverse
            JOIN public.stock_scrap_recovery_executions recovery ON recovery.id=inverse.scrap_recovery_execution_id
                AND recovery.reversal_id=inverse.id AND recovery.scrap_line_id=inverse.scrap_line_id
            WHERE inverse.posting_transaction_id=tx.id AND inverse.original_transaction_id=tx.reversed_transaction_id
                AND tx.source_document_id=inverse.id::text) THEN
            PERFORM public.rsc_check_scrap_current_0165('inverse',(SELECT id
                FROM public.stock_loss_disposition_reversals WHERE posting_transaction_id=tx.id));
            RETURN NULL;
        END IF;
        IF tx.reversed_transaction_id IS NOT NULL THEN
            IF EXISTS (SELECT 1 FROM public.inventory_transactions original WHERE original.id = tx.reversed_transaction_id
                  AND original.source_document_type = 'stock_operation_return')
               OR EXISTS (SELECT 1 FROM public.stock_operation_orders WHERE posting_transaction_id = tx.reversed_transaction_id)
               OR EXISTS (SELECT 1 FROM public.stock_operation_cancellations WHERE posting_transaction_id = tx.reversed_transaction_id) THEN
                RAISE EXCEPTION '0100 return stock cannot use generic reversal' USING ERRCODE = '23514'; END IF;
            IF EXISTS (SELECT 1 FROM public.stock_operation_lines line
                JOIN public.work_order_material_lines origin ON origin.id = line.source_recovery_line_id
                JOIN public.work_order_material_operations recovery ON recovery.id = origin.operation_id
                JOIN public.stock_operation_orders parent ON parent.id = line.operation_id
                JOIN public.inventory_transactions reserved ON reserved.id = parent.posting_transaction_id
                WHERE recovery.posting_transaction_id = tx.reversed_transaction_id AND reserved.ledger_cursor < tx.ledger_cursor
                  AND NOT EXISTS (SELECT 1 FROM public.stock_operation_cancellations cancelled
                    JOIN public.inventory_transactions released ON released.id = cancelled.posting_transaction_id
                    WHERE cancelled.operation_id = parent.id AND released.ledger_cursor < tx.ledger_cursor)) THEN
                RAISE EXCEPTION '0100 active return prevents reversal of its original recovery' USING ERRCODE = '23514'; END IF;
        END IF;
        IF tx.source_document_type='stock_operation_return_outbound' THEN
            SELECT id INTO checked_order FROM public.stock_operation_outbounds WHERE posting_transaction_id=tx.id;
            IF checked_order IS NULL THEN RAISE EXCEPTION '0103 detached return departure' USING ERRCODE='23514'; END IF;
            PERFORM public.rsc_check_stock_return_outbound_0103(checked_order);
            RETURN NULL;
        END IF;
        IF tx.source_document_type = 'stock_operation_return' THEN
            SELECT id INTO checked_order FROM public.stock_operation_orders WHERE posting_transaction_id = tx.id;
            IF checked_order IS NULL THEN
                SELECT operation_id, id INTO checked_order, checked_cancel FROM public.stock_operation_cancellations WHERE posting_transaction_id = tx.id;
            END IF;
            IF checked_order IS NULL THEN RAISE EXCEPTION '0100 detached return inventory transaction' USING ERRCODE = '23514'; END IF;
        ELSIF EXISTS (SELECT 1 FROM public.inventory_movements movement
            JOIN public.stock_operation_lines line ON line.reserved_account_id IN (movement.from_account_id,movement.to_account_id)
            WHERE movement.transaction_id = tx.id AND line.operation_type='return') THEN
            RAISE EXCEPTION '0100 held return stock requires its exact business document' USING ERRCODE = '23514';
        ELSE RETURN NULL; END IF;
    END IF;
    IF checked_order IS NULL THEN RAISE EXCEPTION '0100 return evidence is detached' USING ERRCODE = '23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_operation_orders WHERE id=checked_order AND operation_type='scrap') THEN
        IF checked_cancel IS NOT NULL OR (SELECT count(*) FROM public.stock_scrap_lines WHERE operation_id=checked_order)<>1 THEN
            RAISE EXCEPTION '0165 exact scrap order requires its dedicated fact' USING ERRCODE='23514'; END IF;
        SELECT source_kind,CASE source_kind WHEN 'original' THEN root_disposition_id ELSE correction_execution_id END AS fact_id
            INTO scrap FROM public.stock_scrap_lines WHERE operation_id=checked_order;
        PERFORM public.rsc_check_scrap_current_0165(scrap.source_kind,scrap.fact_id);
        RETURN NULL;
    END IF;
    IF EXISTS(SELECT 1 FROM public.stock_operation_orders WHERE id=checked_order AND operation_type='loss_report') THEN
        IF checked_cancel IS NOT NULL THEN RAISE EXCEPTION '0145 loss requires its dedicated reversal' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_check_loss_submission_0145(checked_order);
        RETURN NULL;
    END IF;
    PERFORM public.rsc_check_stock_return_0100(checked_order, checked_cancel);
    RETURN NULL;
END;
$function$

-- Retain all three immutable legacy aliases. A dedicated nullable column binds
-- the real recovery namespace without disguising it as a legacy reversal key.
ALTER TABLE public.stock_loss_request_key_bindings ADD COLUMN recovery_key_hash varchar(64);
ALTER TABLE public.stock_loss_request_key_bindings ADD COLUMN scrap_key_hash varchar(64);
ALTER TABLE public.stock_loss_request_key_bindings ADD CONSTRAINT ck_loss_binding_recovery_0165 CHECK (
    recovery_key_hash IS NULL OR (binding_kind='inverse' AND recovery_key_hash ~ '^[a-f0-9]{64}$'
        AND recovery_key_hash NOT IN (reversal_key_hash,approval_key_hash,correction_key_hash)));
ALTER TABLE public.stock_loss_request_key_bindings ADD CONSTRAINT uq_loss_binding_recovery_0165 UNIQUE (recovery_key_hash);
ALTER TABLE public.stock_loss_request_key_bindings ADD CONSTRAINT ck_loss_binding_scrap_0165 CHECK (
    scrap_key_hash IS NULL OR (binding_kind='correction' AND recovery_key_hash IS NULL
        AND scrap_key_hash ~ '^[a-f0-9]{64}$'
        AND scrap_key_hash NOT IN (reversal_key_hash,approval_key_hash,correction_key_hash)));
ALTER TABLE public.stock_loss_request_key_bindings ADD CONSTRAINT uq_loss_binding_scrap_0165 UNIQUE (scrap_key_hash);
-- Existing table privileges continue to prohibit API INSERT/UPDATE/DELETE.
-- The only writer remains the typed, client-key-verifying SECDEF registrar.
DO $install$
DECLARE name text;
BEGIN
    FOREACH name IN ARRAY ARRAY['stock_scrap_recovery_requests','stock_scrap_recovery_regional_reviews',
        'stock_scrap_recovery_headquarters_reviews','stock_scrap_recovery_executions'] LOOP
        EXECUTE format('CREATE CONSTRAINT TRIGGER trg_recovery_binding_fence_0165 AFTER INSERT ON public.%I '
            'DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.rsc_fence_loss_request_binding_0159()',name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER trg_recovery_binding_fence_0165',name);
    END LOOP;
END;
$install$;

CREATE OR REPLACE FUNCTION public.rsc_register_loss_request_binding_0159(checked_kind text, checked_fact uuid, client_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE source_table text; fact jsonb; action text; hashes text[]; token text; expected text;
    prior public.stock_loss_request_key_bindings%ROWTYPE; recovery_hash text; scrap_hash text;
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' OR client_key IS NULL
       OR client_key !~ '^[A-Za-z0-9._:-]{8,200}$' THEN
        RAISE EXCEPTION '0159 exact client key and read committed required' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0159 request binding ledger required' USING ERRCODE='23514'; END IF;
    source_table:=CASE checked_kind WHEN 'inverse' THEN 'stock_loss_disposition_reversals' WHEN 'approval' THEN 'stock_loss_correction_decisions' WHEN 'correction' THEN 'stock_loss_correction_executions' WHEN 'inverse_seal' THEN 'stock_loss_inverse_request_seals' WHEN 'approval_seal' THEN 'stock_loss_correction_approval_seals' WHEN 'correction_seal' THEN 'stock_loss_correction_execution_seals' END; action:=CASE checked_kind WHEN 'inverse' THEN 'reverse_loss' WHEN 'approval' THEN 'approve_loss_correction' WHEN 'correction' THEN 'correct_loss' WHEN 'inverse_seal' THEN 'reverse_loss' WHEN 'approval_seal' THEN 'approve_loss_correction' WHEN 'correction_seal' THEN 'correct_loss' END;
    IF source_table IS NULL OR checked_fact IS NULL THEN
        RAISE EXCEPTION '0159 exact typed request fact required' USING ERRCODE='23514'; END IF;
    EXECUTE format('SELECT to_jsonb(f) FROM public.%I f WHERE id=$1',source_table) INTO fact USING checked_fact;
    SELECT array_agg(encode(sha256(convert_to('cloud_oam.inventory.idempotency.v1','UTF8')||decode('00','hex')
        ||convert_to('stock-loss:'||a.name||':'||client_key,'UTF8')),'hex') ORDER BY a.ordinal)
        INTO hashes FROM (VALUES ('reverse_loss',1),('approve_loss_correction',2),('correct_loss',3)) a(name,ordinal);
    token:=encode(sha256(convert_to('cloud_oam.loss.correction.key.v1','UTF8')||decode('00','hex')||convert_to(client_key,'UTF8')),'hex');
    expected:=CASE action WHEN 'approve_loss_correction' THEN hashes[2] WHEN 'correct_loss' THEN hashes[3] ELSE hashes[1] END;
    IF checked_kind='inverse' AND fact->>'scrap_line_id' IS NOT NULL THEN
        IF fact#>>'{command_jsonb,action}' IS DISTINCT FROM 'execute_scrap_recovery' THEN
            RAISE EXCEPTION '0165 exact recovery binding action required' USING ERRCODE='23514'; END IF;
        recovery_hash:=encode(sha256(convert_to('cloud_oam.inventory.idempotency.v1','UTF8')||decode('00','hex')
            ||convert_to('stock-scrap-recovery:'||client_key,'UTF8')),'hex');
        expected:=recovery_hash;
    ELSIF checked_kind='correction' AND fact->>'disposition'='scrap' THEN
        IF fact#>>'{command_jsonb,action}' IS DISTINCT FROM 'scrap' THEN
            RAISE EXCEPTION '0165 exact corrected scrap binding action required' USING ERRCODE='23514'; END IF;
        scrap_hash:=encode(sha256(convert_to('cloud_oam.inventory.idempotency.v1','UTF8')||decode('00','hex')
            ||convert_to('stock-scrap:'||client_key,'UTF8')),'hex');
        expected:=scrap_hash;
    END IF;
    IF fact IS NULL OR fact->>'idempotency_key_hash' IS DISTINCT FROM expected
       OR (checked_kind IN ('inverse_seal','approval_seal','correction_seal') AND (fact->>'reversal_key_hash' IS DISTINCT FROM hashes[1]
            OR fact->>'approval_key_hash' IS DISTINCT FROM hashes[2] OR fact->>'correction_key_hash' IS DISTINCT FROM hashes[3])) THEN
        RAISE EXCEPTION '0159 client key does not prove stored action hashes' USING ERRCODE='23514'; END IF;
    SELECT * INTO prior FROM public.stock_loss_request_key_bindings WHERE fact_id=checked_fact;
    IF prior.fact_id IS NOT NULL THEN
        IF prior.binding_kind IS DISTINCT FROM checked_kind OR prior.key_token IS DISTINCT FROM token
           OR prior.reversal_key_hash IS DISTINCT FROM hashes[1] OR prior.approval_key_hash IS DISTINCT FROM hashes[2]
           OR prior.correction_key_hash IS DISTINCT FROM hashes[3]
           OR prior.recovery_key_hash IS DISTINCT FROM recovery_hash
           OR prior.scrap_key_hash IS DISTINCT FROM scrap_hash THEN
            RAISE EXCEPTION '0159 immutable request binding conflict' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_check_loss_request_binding_0159(checked_kind,checked_fact);
        RETURN;
    END IF;
    INSERT INTO public.stock_loss_request_key_bindings(fact_id,binding_kind,root_disposition_id,actor_user_id,
        request_id,request_hash,key_token,reversal_key_hash,approval_key_hash,correction_key_hash,
        inverse_id,approval_id,correction_id,seal_id,approval_seal_id,correction_seal_id,recovery_key_hash,scrap_key_hash,created_at)
    VALUES(checked_fact,checked_kind,(fact->>'root_disposition_id')::uuid,fact->>'actor_user_id',fact->>'request_id',
        fact->>'request_hash',token,hashes[1],hashes[2],hashes[3],
        CASE WHEN checked_kind='inverse' THEN checked_fact END,CASE WHEN checked_kind='approval' THEN checked_fact END,
        CASE WHEN checked_kind='correction' THEN checked_fact END,CASE WHEN checked_kind='inverse_seal' THEN checked_fact END,
        CASE WHEN checked_kind='approval_seal' THEN checked_fact END,CASE WHEN checked_kind='correction_seal' THEN checked_fact END,recovery_hash,scrap_hash,(fact->>'created_at')::timestamptz);
    PERFORM public.rsc_check_loss_request_binding_0159(checked_kind,checked_fact);
    IF checked_kind='inverse_seal' THEN PERFORM public.rsc_check_loss_inverse_seal_0159(checked_fact);
    ELSIF checked_kind='approval_seal' THEN PERFORM public.rsc_check_loss_approval_seal_0161(checked_fact);
    ELSIF checked_kind='correction_seal' THEN PERFORM public.rsc_check_loss_execution_seal_0161(checked_fact);
    ELSE PERFORM public.rsc_check_loss_current_correction_0159(checked_fact,action); END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_fence_loss_request_binding_0159()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE kind text; identifier uuid; raw jsonb:=to_jsonb(NEW); actor text; request text; key text; item record;
BEGIN
    IF TG_OP<>'INSERT' OR TG_TABLE_SCHEMA<>'public' THEN
        RAISE EXCEPTION '0159 request binding insert fence only' USING ERRCODE='23514'; END IF;
    kind:=CASE TG_TABLE_NAME WHEN 'stock_loss_disposition_reversals' THEN 'inverse' WHEN 'stock_loss_correction_decisions' THEN 'approval' WHEN 'stock_loss_correction_executions' THEN 'correction' WHEN 'stock_loss_inverse_request_seals' THEN 'inverse_seal' WHEN 'stock_loss_correction_approval_seals' THEN 'approval_seal' WHEN 'stock_loss_correction_execution_seals' THEN 'correction_seal' END;
    IF TG_TABLE_NAME='stock_loss_request_key_bindings' THEN kind:=NEW.binding_kind;identifier:=NEW.fact_id;
    ELSIF kind IS NOT NULL THEN identifier:=NEW.id; END IF;
    IF kind IS NOT NULL THEN
        PERFORM public.rsc_check_loss_request_binding_0159(kind,identifier); RETURN NULL; END IF;
    actor:=raw->>'actor_user_id';request:=raw->>'request_id';key:=raw->>'idempotency_key_hash';
    IF key IS NULL AND (actor IS NULL OR request IS NULL) THEN RETURN NULL; END IF;
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0159 request alias fence requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    FOR item IN SELECT binding_kind,fact_id FROM public.stock_loss_request_key_bindings b
        WHERE key IN (b.reversal_key_hash,b.approval_key_hash,b.correction_key_hash,b.recovery_key_hash,b.scrap_key_hash)
            OR (actor=b.actor_user_id AND request=b.request_id)
    LOOP PERFORM public.rsc_check_loss_request_binding_0159(item.binding_kind,item.fact_id); END LOOP;
    RETURN NULL;
END;
$function$

-- Four previously unregistered actions. Legacy inverse/correction bindings and
-- their three aliases retain their original values, ownership and meaning.
CREATE TABLE public.stock_scrap_request_key_bindings (
    fact_id uuid PRIMARY KEY,
    binding_kind varchar(24) NOT NULL,
    root_disposition_id uuid NOT NULL REFERENCES public.stock_loss_dispositions(id) ON DELETE RESTRICT,
    actor_user_id varchar(36) NOT NULL REFERENCES public.users(id) ON DELETE RESTRICT,
    actor_person_id uuid NOT NULL REFERENCES public.people(id) ON DELETE RESTRICT,
    request_id varchar(160) NOT NULL CHECK (request_id ~ '^[A-Za-z0-9._:-]{8,160}$'),
    request_hash varchar(64) NOT NULL CHECK (request_hash ~ '^[a-f0-9]{64}$'),
    key_token varchar(64) NOT NULL UNIQUE CHECK (key_token ~ '^[a-f0-9]{64}$'),
    reversal_key_hash varchar(64) NOT NULL UNIQUE CHECK (reversal_key_hash ~ '^[a-f0-9]{64}$'),
    approval_key_hash varchar(64) NOT NULL UNIQUE CHECK (approval_key_hash ~ '^[a-f0-9]{64}$'),
    correction_key_hash varchar(64) NOT NULL UNIQUE CHECK (correction_key_hash ~ '^[a-f0-9]{64}$'),
    recovery_key_hash varchar(64) NOT NULL UNIQUE CHECK (recovery_key_hash ~ '^[a-f0-9]{64}$'),
    scrap_key_hash varchar(64) NOT NULL UNIQUE CHECK (scrap_key_hash ~ '^[a-f0-9]{64}$'),
    original_id uuid REFERENCES public.stock_loss_dispositions(id) ON DELETE RESTRICT,
    application_id uuid REFERENCES public.stock_scrap_recovery_requests(id) ON DELETE RESTRICT,
    regional_id uuid REFERENCES public.stock_scrap_recovery_regional_reviews(id) ON DELETE RESTRICT,
    headquarters_id uuid REFERENCES public.stock_scrap_recovery_headquarters_reviews(id) ON DELETE RESTRICT,
    created_at timestamptz NOT NULL,
    UNIQUE(actor_user_id,request_id),
    CHECK ((binding_kind='original' AND original_id IS NOT NULL AND original_id=fact_id
            AND original_id=root_disposition_id AND application_id IS NULL AND regional_id IS NULL AND headquarters_id IS NULL)
        OR (binding_kind='apply' AND application_id IS NOT NULL AND application_id=fact_id
            AND original_id IS NULL AND regional_id IS NULL AND headquarters_id IS NULL)
        OR (binding_kind='regional' AND regional_id IS NOT NULL AND regional_id=fact_id
            AND original_id IS NULL AND application_id IS NULL AND headquarters_id IS NULL)
        OR (binding_kind='headquarters' AND headquarters_id IS NOT NULL AND headquarters_id=fact_id
            AND original_id IS NULL AND application_id IS NULL AND regional_id IS NULL)),
    CHECK (reversal_key_hash NOT IN (approval_key_hash,correction_key_hash,recovery_key_hash,scrap_key_hash)
        AND approval_key_hash NOT IN (correction_key_hash,recovery_key_hash,scrap_key_hash)
        AND correction_key_hash NOT IN (recovery_key_hash,scrap_key_hash) AND recovery_key_hash<>scrap_key_hash)
);
REVOKE ALL ON public.stock_scrap_request_key_bindings
FROM PUBLIC,star_oam_api,star_oam_backup,star_oam_projector,star_oam_edge,edge_inbox;
GRANT SELECT ON public.stock_scrap_request_key_bindings TO star_oam_api,star_oam_backup;

CREATE FUNCTION public.rsc_scrap_binding_fact_0165(checked_kind text, checked_fact uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE source_table text; fact jsonb; root uuid;
BEGIN
    source_table:=CASE checked_kind WHEN 'original' THEN 'stock_loss_dispositions'
        WHEN 'apply' THEN 'stock_scrap_recovery_requests' WHEN 'regional' THEN 'stock_scrap_recovery_regional_reviews'
        WHEN 'headquarters' THEN 'stock_scrap_recovery_headquarters_reviews' END;
    IF source_table IS NULL OR checked_fact IS NULL THEN
        RAISE EXCEPTION '0165 exact typed scrap binding required' USING ERRCODE='23514'; END IF;
    EXECUTE format('SELECT to_jsonb(f) FROM public.%I f WHERE id=$1',source_table) INTO fact USING checked_fact;
    IF checked_kind='original' THEN
        root:=checked_fact;
        IF fact->>'disposition' IS DISTINCT FROM 'scrap' OR fact#>>'{command_jsonb,action}' IS DISTINCT FROM 'scrap'
           OR fact#>>'{command_jsonb,intent,source,kind}' IS DISTINCT FROM 'original' THEN
            RAISE EXCEPTION '0165 original scrap binding source required' USING ERRCODE='23514'; END IF;
        fact:=fact||jsonb_build_object('actor_person_id',fact->>'executor_person_id');
    ELSE
        SELECT root_disposition_id INTO root FROM public.stock_scrap_lines WHERE id=(fact->>'scrap_line_id')::uuid;
        IF fact#>>'{command_jsonb,action}' IS DISTINCT FROM (CASE checked_kind
            WHEN 'apply' THEN 'apply_scrap_recovery' WHEN 'regional' THEN 'review_scrap_recovery_region'
            WHEN 'headquarters' THEN 'review_scrap_recovery_headquarters' END) THEN
            RAISE EXCEPTION '0165 recovery binding action required' USING ERRCODE='23514'; END IF;
    END IF;
    IF fact IS NULL OR root IS NULL OR fact->>'actor_person_id' IS NULL THEN
        RAISE EXCEPTION '0165 complete scrap binding fact required' USING ERRCODE='23514'; END IF;
    RETURN fact||jsonb_build_object('root_disposition_id',root,'source_table',source_table);
END;
$function$;

CREATE FUNCTION public.rsc_check_scrap_request_binding_0165(checked_kind text, checked_fact uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE binding public.stock_scrap_request_key_bindings%ROWTYPE; fact jsonb; keys text[];
    other_table text; collision boolean;
BEGIN
    SELECT * INTO binding FROM public.stock_scrap_request_key_bindings WHERE fact_id=checked_fact AND binding_kind=checked_kind;
    IF binding.fact_id IS NULL THEN
        RAISE EXCEPTION '0165 exact database-owned scrap binding required' USING ERRCODE='23514'; END IF;
    fact:=public.rsc_scrap_binding_fact_0165(checked_kind,checked_fact);
    keys:=ARRAY[binding.reversal_key_hash,binding.approval_key_hash,binding.correction_key_hash,binding.recovery_key_hash,binding.scrap_key_hash];
    IF (fact->>'root_disposition_id')::uuid IS DISTINCT FROM binding.root_disposition_id
        OR fact->>'actor_user_id' IS DISTINCT FROM binding.actor_user_id
        OR (fact->>'actor_person_id')::uuid IS DISTINCT FROM binding.actor_person_id
        OR fact->>'request_id' IS DISTINCT FROM binding.request_id OR fact->>'request_hash' IS DISTINCT FROM binding.request_hash
        OR (fact->>'created_at')::timestamptz IS DISTINCT FROM binding.created_at
        OR fact->>'idempotency_key_hash' IS DISTINCT FROM (CASE WHEN checked_kind='original' THEN keys[5] ELSE keys[4] END) THEN
        RAISE EXCEPTION '0165 scrap binding differs from exact fact' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_request_key_bindings b WHERE b.key_token=binding.key_token
        OR (b.actor_user_id=binding.actor_user_id AND b.request_id=binding.request_id)
        OR ARRAY[b.reversal_key_hash,b.approval_key_hash,b.correction_key_hash,b.recovery_key_hash,b.scrap_key_hash]::text[] && keys)
       OR EXISTS(SELECT 1 FROM public.stock_scrap_request_key_bindings b WHERE b.fact_id<>checked_fact
        AND (b.key_token=binding.key_token OR (b.actor_user_id=binding.actor_user_id AND b.request_id=binding.request_id)
        OR ARRAY[b.reversal_key_hash,b.approval_key_hash,b.correction_key_hash,b.recovery_key_hash,b.scrap_key_hash]::text[] && keys)) THEN
        RAISE EXCEPTION '0165 raw request key reused across registries' USING ERRCODE='23514'; END IF;
    FOREACH other_table IN ARRAY ARRAY['stock_operation_orders','stock_loss_dispositions','stock_loss_regional_reviews',
        'stock_loss_headquarters_reviews','stock_loss_request_seals','stock_loss_review_request_seals',
        'stock_loss_disposition_request_seals','stock_operation_cancellations','stock_operation_command_seals',
        'stock_operation_outbounds','stock_operation_shipments','stock_operation_receipts','stock_operation_return_inbounds',
        'stock_operation_return_inbound_seals','stock_loss_disposition_reversals','stock_loss_correction_decisions',
        'stock_loss_correction_executions','stock_loss_inverse_request_seals','stock_loss_correction_approval_seals',
        'stock_loss_correction_execution_seals','stock_scrap_recovery_requests','stock_scrap_recovery_regional_reviews',
        'stock_scrap_recovery_headquarters_reviews','stock_scrap_recovery_executions'] LOOP
        -- JSON extraction also handles old seal tables without a primary hash.
        -- Only this source and its exact original-scrap child may share keys.
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I f WHERE '
            '((to_jsonb(f)->>''actor_user_id''=$2 AND to_jsonb(f)->>''request_id''=$3) OR '
            'ARRAY[to_jsonb(f)->>''idempotency_key_hash'',to_jsonb(f)->>''reversal_key_hash'', '
            'to_jsonb(f)->>''approval_key_hash'',to_jsonb(f)->>''correction_key_hash''] && $1)'
            ||CASE WHEN other_table=fact->>'source_table' THEN ' AND id<>$4' ELSE '' END
            ||CASE WHEN checked_kind='original' AND other_table='stock_operation_orders'
                THEN ' AND id IS DISTINCT FROM $5' ELSE '' END||')',other_table)
            INTO collision USING keys,binding.actor_user_id,binding.request_id,checked_fact,(fact->>'scrap_operation_id')::uuid;
        IF collision THEN RAISE EXCEPTION '0165 scrap request key reused across actions' USING ERRCODE='23514'; END IF;
    END LOOP;
    IF EXISTS(SELECT 1 FROM public.inventory_transactions WHERE idempotency_key_hash=ANY(keys)
        AND id::text IS DISTINCT FROM fact->>'posting_transaction_id')
        OR EXISTS(SELECT 1 FROM public.shipments WHERE idempotency_key_hash=ANY(keys))
        OR EXISTS(SELECT 1 FROM public.receipts WHERE idempotency_key_hash=ANY(keys)) THEN
        RAISE EXCEPTION '0165 scrap request aliases contain detached posting' USING ERRCODE='23514'; END IF;
END;
$function$;

CREATE FUNCTION public.rsc_register_scrap_request_binding_0165(checked_kind text, checked_fact uuid, client_key text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE fact jsonb; hashes text[]; token text; prior public.stock_scrap_request_key_bindings%ROWTYPE; source record;
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' OR client_key IS NULL
        OR client_key !~ '^[A-Za-z0-9._:-]{8,200}$' THEN
        RAISE EXCEPTION '0165 exact client key and read committed required' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 request binding ledger required' USING ERRCODE='23514'; END IF;
    fact:=public.rsc_scrap_binding_fact_0165(checked_kind,checked_fact);
    SELECT array_agg(encode(sha256(convert_to('cloud_oam.inventory.idempotency.v1','UTF8')||decode('00','hex')
        ||convert_to(a.prefix||client_key,'UTF8')),'hex') ORDER BY a.ordinal) INTO hashes
        FROM (VALUES ('stock-loss:reverse_loss:',1),('stock-loss:approve_loss_correction:',2),
            ('stock-loss:correct_loss:',3),('stock-scrap-recovery:',4),('stock-scrap:',5)) a(prefix,ordinal);
    token:=encode(sha256(convert_to('cloud_oam.loss.correction.key.v1','UTF8')||decode('00','hex')||convert_to(client_key,'UTF8')),'hex');
    IF fact->>'idempotency_key_hash' IS DISTINCT FROM (CASE WHEN checked_kind='original' THEN hashes[5] ELSE hashes[4] END) THEN
        RAISE EXCEPTION '0165 client key does not prove stored scrap action hash' USING ERRCODE='23514'; END IF;
    SELECT * INTO prior FROM public.stock_scrap_request_key_bindings WHERE fact_id=checked_fact;
    IF prior.fact_id IS NOT NULL THEN
        IF prior.binding_kind IS DISTINCT FROM checked_kind OR prior.key_token IS DISTINCT FROM token
            OR ARRAY[prior.reversal_key_hash,prior.approval_key_hash,prior.correction_key_hash,prior.recovery_key_hash,prior.scrap_key_hash]::text[]
                IS DISTINCT FROM hashes THEN
            RAISE EXCEPTION '0165 immutable scrap request binding conflict' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_check_scrap_request_binding_0165(checked_kind,checked_fact);
        RETURN;
    END IF;
    INSERT INTO public.stock_scrap_request_key_bindings(fact_id,binding_kind,root_disposition_id,actor_user_id,actor_person_id,
        request_id,request_hash,key_token,reversal_key_hash,approval_key_hash,correction_key_hash,recovery_key_hash,scrap_key_hash,
        original_id,application_id,regional_id,headquarters_id,created_at)
    VALUES(checked_fact,checked_kind,(fact->>'root_disposition_id')::uuid,fact->>'actor_user_id',(fact->>'actor_person_id')::uuid,
        fact->>'request_id',fact->>'request_hash',token,hashes[1],hashes[2],hashes[3],hashes[4],hashes[5],
        CASE WHEN checked_kind='original' THEN checked_fact END,CASE WHEN checked_kind='apply' THEN checked_fact END,
        CASE WHEN checked_kind='regional' THEN checked_fact END,CASE WHEN checked_kind='headquarters' THEN checked_fact END,
        (fact->>'created_at')::timestamptz);
    PERFORM public.rsc_check_scrap_request_binding_0165(checked_kind,checked_fact);
    IF checked_kind='original' THEN
        PERFORM public.rsc_check_scrap_current_0165('original',checked_fact);
    ELSE
        SELECT * INTO source FROM public.rsc_scrap_recovery_source_0165((fact->>'scrap_line_id')::uuid);
        PERFORM public.rsc_assert_scrap_recovery_authority_0165(fact->>'actor_user_id',(fact->>'authorization_version')::bigint,
            (fact->>'actor_person_id')::uuid,source.owner_org_id,source.location_id,source.requester_id,checked_kind);
        PERFORM public.rsc_check_scrap_recovery_approvals_0165((fact->>'scrap_line_id')::uuid);
    END IF;
END;
$function$;

CREATE FUNCTION public.rsc_fence_scrap_request_bindings_0165()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE raw jsonb:=to_jsonb(NEW); kind text; keys text[]; item record;
BEGIN
    IF TG_OP<>'INSERT' OR TG_TABLE_SCHEMA<>'public' OR current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0165 scrap binding insert fence requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0165 request binding ledger required' USING ERRCODE='23514'; END IF;
    kind:=CASE TG_TABLE_NAME WHEN 'stock_loss_dispositions' THEN CASE WHEN raw->>'disposition'='scrap' THEN 'original' END
        WHEN 'stock_scrap_recovery_requests' THEN 'apply' WHEN 'stock_scrap_recovery_regional_reviews' THEN 'regional'
        WHEN 'stock_scrap_recovery_headquarters_reviews' THEN 'headquarters' END;
    IF kind IS NOT NULL THEN PERFORM public.rsc_check_scrap_request_binding_0165(kind,(raw->>'id')::uuid); END IF;
    keys:=array_remove(ARRAY[raw->>'idempotency_key_hash',raw->>'reversal_key_hash',raw->>'approval_key_hash',
        raw->>'correction_key_hash',raw->>'recovery_key_hash',raw->>'scrap_key_hash'],NULL);
    FOR item IN SELECT binding_kind,fact_id FROM public.stock_scrap_request_key_bindings b
        WHERE b.key_token=raw->>'key_token' OR (b.actor_user_id=raw->>'actor_user_id' AND b.request_id=raw->>'request_id')
        OR ARRAY[b.reversal_key_hash,b.approval_key_hash,b.correction_key_hash,b.recovery_key_hash,b.scrap_key_hash]::text[] && keys
    LOOP PERFORM public.rsc_check_scrap_request_binding_0165(item.binding_kind,item.fact_id); END LOOP;
    RETURN NULL;
END;
$function$;

REVOKE ALL ON FUNCTION public.rsc_scrap_binding_fact_0165(text,uuid),
    public.rsc_check_scrap_request_binding_0165(text,uuid),public.rsc_fence_scrap_request_bindings_0165(),
    public.rsc_register_scrap_request_binding_0165(text,uuid,text)
FROM PUBLIC,star_oam_api,star_oam_backup,star_oam_projector,star_oam_edge,edge_inbox;
GRANT EXECUTE ON FUNCTION public.rsc_register_scrap_request_binding_0165(text,uuid,text) TO star_oam_api;
CREATE TRIGGER trg_scrap_binding_immutable_0165 BEFORE UPDATE OR DELETE ON public.stock_scrap_request_key_bindings
FOR EACH ROW EXECUTE FUNCTION public.rsc_scrap_facts_append_only_0165();
CREATE TRIGGER trg_scrap_binding_no_truncate_0165 BEFORE TRUNCATE ON public.stock_scrap_request_key_bindings
FOR EACH STATEMENT EXECUTE FUNCTION public.rsc_scrap_facts_append_only_0165();
ALTER TABLE public.stock_scrap_request_key_bindings ENABLE ALWAYS TRIGGER trg_scrap_binding_immutable_0165;
ALTER TABLE public.stock_scrap_request_key_bindings ENABLE ALWAYS TRIGGER trg_scrap_binding_no_truncate_0165;
DO $install$
DECLARE name text;
BEGIN
    FOREACH name IN ARRAY ARRAY['stock_scrap_request_key_bindings','stock_loss_request_key_bindings',
        'stock_operation_orders','stock_loss_dispositions','stock_loss_regional_reviews','stock_loss_headquarters_reviews',
        'stock_loss_request_seals','stock_loss_review_request_seals','stock_loss_disposition_request_seals',
        'stock_operation_cancellations','stock_operation_command_seals','stock_operation_outbounds','stock_operation_shipments',
        'stock_operation_receipts','stock_operation_return_inbounds','stock_operation_return_inbound_seals',
        'stock_loss_disposition_reversals','stock_loss_correction_decisions','stock_loss_correction_executions',
        'stock_loss_inverse_request_seals','stock_loss_correction_approval_seals','stock_loss_correction_execution_seals',
        'stock_scrap_recovery_requests','stock_scrap_recovery_regional_reviews','stock_scrap_recovery_headquarters_reviews',
        'stock_scrap_recovery_executions','inventory_transactions','shipments','receipts'] LOOP
        EXECUTE format('CREATE CONSTRAINT TRIGGER trg_scrap_binding_fence_0165 AFTER INSERT ON public.%I '
            'DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.rsc_fence_scrap_request_bindings_0165()',name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER trg_scrap_binding_fence_0165',name);
    END LOOP;
END;
$install$;

-- Private input proof for the controlled seal writer. This does not prove
-- source existence, authority, absence or audit, and creates no seal rows.
-- Never grant this component as a business endpoint or treat its result as
-- a posting/closure permit. The eventual registrar must compose all proofs.
CREATE FUNCTION public.rsc_scrap_seal_canonical_0165(checked_kind text, command jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE source jsonb; expected_source jsonb; body jsonb; expected jsonb; evidence jsonb;
    reason text; request text; plan text; action text; value text; field text;
    ids text[]; digests text[]; files jsonb;
BEGIN
    IF checked_kind IS NULL OR checked_kind NOT IN ('original','correction','apply','regional','headquarters','execute')
       OR command IS NULL OR jsonb_typeof(command)<>'object' THEN
        RAISE EXCEPTION '0165 explicit seal kind and command required' USING ERRCODE='23514';
    END IF;
    request:=command->>'request_id';
    IF checked_kind IN ('original','correction') THEN
        body:=command->'intent';
        reason:=body->>'execution_reason';
        source:=body->'source';
        files:=body->'evidence_file_ids';
        plan:=command->>'expected_plan_hash';
        IF checked_kind='original' THEN
            ids:=ARRAY['headquarters_decision_id'];
            digests:=ARRAY['expected_headquarters_review_hash','expected_submission_plan_hash'];
        ELSE
            ids:=ARRAY['root_disposition_id','reversal_id','correction_decision_id'];
            digests:=ARRAY['expected_root_request_hash','expected_submission_plan_hash',
                'expected_reversal_hash','expected_correction_decision_hash'];
        END IF;
        expected_source:=jsonb_build_object('kind',checked_kind);
    ELSE
        body:=command;
        reason:=command->>'reason';
        source:=command->'source';
        ids:=ARRAY['scrap_line_id']; digests:=ARRAY['expected_scrap_request_hash'];
        expected_source:='{}'::jsonb;
        IF checked_kind='apply' THEN files:=command->'evidence_file_ids'; END IF;
        IF checked_kind='execute' THEN plan:=command->>'expected_plan_hash'; END IF;
    END IF;
    IF NOT COALESCE(request ~ '^[A-Za-z0-9._:-]{8,160}$'
        AND length(reason) BETWEEN 1 AND 500
        AND btrim(reason,chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(28)||chr(29)||chr(30)||chr(31)||chr(32)||chr(133)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288))=reason
        AND jsonb_typeof(source)='object',false)
       OR EXISTS(SELECT 1 FROM generate_series(1,length(reason)) p
           WHERE ascii(substr(reason,p,1))<32 AND ascii(substr(reason,p,1)) NOT IN (9,10)) THEN
        RAISE EXCEPTION '0165 exact canonical seal request identity required' USING ERRCODE='23514';
    END IF;
    FOREACH field IN ARRAY ids LOOP
        value:=source->>field;
        IF value IS NULL OR value::uuid='00000000-0000-0000-0000-000000000000'::uuid THEN
            RAISE EXCEPTION '0165 nonzero seal source identifier required' USING ERRCODE='23514'; END IF;
        expected_source:=expected_source||jsonb_build_object(field,value::uuid::text);
    END LOOP;
    FOREACH field IN ARRAY digests LOOP
        value:=source->>field;
        IF value IS NULL OR value !~ '^[a-f0-9]{64}$' THEN
            RAISE EXCEPTION '0165 exact seal source hash required' USING ERRCODE='23514'; END IF;
        expected_source:=expected_source||jsonb_build_object(field,value);
    END LOOP;
    IF checked_kind IN ('original','correction','execute') AND
        (plan IS NULL OR plan !~ '^[a-f0-9]{64}$') THEN
        RAISE EXCEPTION '0165 retain the original seal plan hash' USING ERRCODE='23514'; END IF;
    IF checked_kind IN ('original','correction','apply') THEN
        IF files IS NULL OR jsonb_typeof(files)<>'array' THEN
            RAISE EXCEPTION '0165 canonical seal evidence identifiers required' USING ERRCODE='23514'; END IF;
        IF jsonb_array_length(files) NOT BETWEEN 1 AND 20
           OR EXISTS(SELECT 1 FROM jsonb_array_elements(files) f WHERE jsonb_typeof(f)<>'string') THEN
            RAISE EXCEPTION '0165 canonical seal evidence list required' USING ERRCODE='23514'; END IF;
        SELECT jsonb_agg(f.identifier::uuid::text ORDER BY f.identifier::uuid::text COLLATE "C") INTO evidence
            FROM jsonb_array_elements_text(files) AS f(identifier);
        IF evidence IS DISTINCT FROM files
           OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(files) AS f(identifier)
               WHERE f.identifier::uuid='00000000-0000-0000-0000-000000000000'::uuid)
           OR (SELECT count(DISTINCT f.identifier) FROM jsonb_array_elements_text(files) AS f(identifier))<>jsonb_array_length(files) THEN
            RAISE EXCEPTION '0165 sorted unique nonzero seal evidence required' USING ERRCODE='23514'; END IF;
    END IF;
    IF checked_kind IN ('original','correction') THEN
        expected:=jsonb_build_object('schema_version',1,'action','scrap',
            'intent',jsonb_build_object('source',expected_source,'execution_reason',reason,'evidence_file_ids',evidence),
            'request_id',request,'expected_plan_hash',plan);
    ELSE
        action:=CASE checked_kind WHEN 'apply' THEN 'apply_scrap_recovery'
            WHEN 'regional' THEN 'review_scrap_recovery_region'
            WHEN 'headquarters' THEN 'review_scrap_recovery_headquarters' ELSE 'execute_scrap_recovery' END;
        expected:=jsonb_build_object('action',action,'source',expected_source,'reason',reason,'request_id',request);
        IF checked_kind='apply' THEN
            expected:=expected||jsonb_build_object('evidence_file_ids',evidence);
        ELSE
            ids:=ARRAY['recovery_request_id']; digests:=ARRAY['expected_request_hash'];
            IF checked_kind='headquarters' THEN
                ids:=ids||'regional_review_id'::text; digests:=digests||'expected_regional_hash'::text;
            ELSIF checked_kind='execute' THEN
                ids:=ids||'headquarters_review_id'::text; digests:=digests||'expected_headquarters_hash'::text;
            END IF;
            FOREACH field IN ARRAY ids LOOP
                value:=command->>field;
                IF value IS NULL OR value::uuid='00000000-0000-0000-0000-000000000000'::uuid THEN
                    RAISE EXCEPTION '0165 exact seal review ancestor required' USING ERRCODE='23514'; END IF;
                expected:=expected||jsonb_build_object(field,value::uuid::text);
            END LOOP;
            FOREACH field IN ARRAY digests LOOP
                value:=command->>field;
                IF value IS NULL OR value !~ '^[a-f0-9]{64}$' THEN
                    RAISE EXCEPTION '0165 exact seal review hash required' USING ERRCODE='23514'; END IF;
                expected:=expected||jsonb_build_object(field,value);
            END LOOP;
            IF checked_kind='execute' THEN
                expected:=expected||jsonb_build_object('expected_plan_hash',plan);
            ELSE
                value:=command->>'decision';
                IF value IS NULL OR NOT (checked_kind='regional' AND value IN ('verified','needs_evidence')
                    OR checked_kind='headquarters' AND value IN ('approve','request_regional_review')) THEN
                    RAISE EXCEPTION '0165 exact seal review decision required' USING ERRCODE='23514'; END IF;
                expected:=expected||jsonb_build_object('decision',value);
            END IF;
        END IF;
    END IF;
    IF command IS DISTINCT FROM expected
       OR public.rsc_canonical_reconciliation_json_0026(command) IS DISTINCT FROM
          public.rsc_canonical_reconciliation_json_0026(expected) THEN
        RAISE EXCEPTION '0165 complete canonical seal command required' USING ERRCODE='23514'; END IF;
    RETURN jsonb_build_object('kind',checked_kind,'command_jsonb',expected,'request_id',request,'reason',reason,
        'plan_hash',plan,'request_hash',encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex'));
EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION '0165 canonical seal identifier invalid' USING ERRCODE='23514';
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_scrap_seal_canonical_0165(text,jsonb)
FROM PUBLIC,star_oam_api,star_oam_backup,star_oam_projector,star_oam_edge,edge_inbox;

-- Real key derivation belongs only to the write boundary. Retained proof does
-- not store, invent, or recover plaintext client keys.
CREATE FUNCTION public.rsc_prepare_scrap_seal_request_0165(checked_kind text, command jsonb, client_key text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE prepared jsonb; hashes text[]; token text;
BEGIN
    IF client_key IS NULL OR client_key !~ '^[A-Za-z0-9._:-]{8,200}$' THEN
        RAISE EXCEPTION '0165 real client key required' USING ERRCODE='23514'; END IF;
    prepared:=public.rsc_scrap_seal_canonical_0165(checked_kind,command);
    SELECT array_agg(encode(sha256(convert_to('cloud_oam.inventory.idempotency.v1','UTF8')||decode('00','hex')
        ||convert_to(a.prefix||client_key,'UTF8')),'hex') ORDER BY a.ordinal) INTO hashes
        FROM (VALUES ('stock-loss:reverse_loss:',1),('stock-loss:approve_loss_correction:',2),
            ('stock-loss:correct_loss:',3),('stock-scrap-recovery:',4),('stock-scrap:',5)) a(prefix,ordinal);
    token:=encode(sha256(convert_to('cloud_oam.loss.correction.key.v1','UTF8')||decode('00','hex')||convert_to(client_key,'UTF8')),'hex');
    RETURN prepared||jsonb_build_object('key_token',token,'reversal_key_hash',hashes[1],'approval_key_hash',hashes[2],
        'correction_key_hash',hashes[3],'recovery_key_hash',hashes[4],'scrap_key_hash',hashes[5],
        'idempotency_key_hash',CASE WHEN checked_kind IN ('original','correction') THEN hashes[5] ELSE hashes[4] END);
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_prepare_scrap_seal_request_0165(text,jsonb,text)
FROM PUBLIC,star_oam_api,star_oam_backup,star_oam_projector,star_oam_edge,edge_inbox;

-- Private persisted-source proof for seal registration, not an authorization
-- or absence proof. Historical sources remain valid after later executions.
CREATE FUNCTION public.rsc_scrap_seal_source_0165(checked_kind text, command jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE prepared jsonb; source jsonb; anchors jsonb; source_fact jsonb; source_time timestamptz;
    original_decision public.stock_loss_headquarters_decisions%ROWTYPE;
    headquarters_review public.stock_loss_headquarters_reviews%ROWTYPE;
    loss_order public.stock_operation_orders%ROWTYPE; loss_line public.stock_operation_lines%ROWTYPE;
    root public.stock_loss_dispositions%ROWTYPE; inverse public.stock_loss_disposition_reversals%ROWTYPE;
    correction public.stock_loss_correction_decisions%ROWTYPE; account public.stock_accounts%ROWTYPE;
    scrap public.stock_scrap_lines%ROWTYPE; application public.stock_scrap_recovery_requests%ROWTYPE;
    region public.stock_scrap_recovery_regional_reviews%ROWTYPE;
    final public.stock_scrap_recovery_headquarters_reviews%ROWTYPE;
BEGIN
    prepared:=public.rsc_scrap_seal_canonical_0165(checked_kind,command);
    anchors:=jsonb_build_object('root_disposition_id',NULL,'original_decision_id',NULL,
        'reversal_id',NULL,'correction_decision_id',NULL,'scrap_line_id',NULL,'recovery_request_id',NULL,
        'regional_review_id',NULL,'headquarters_review_id',NULL,'regional_decision',NULL,'headquarters_decision',NULL);
    IF checked_kind IN ('original','correction') THEN source:=command#>'{intent,source}';
    ELSE source:=command->'source'; END IF;
    IF checked_kind='original' THEN
        SELECT * INTO original_decision FROM public.stock_loss_headquarters_decisions WHERE id=(source->>'headquarters_decision_id')::uuid;
        SELECT * INTO headquarters_review FROM public.stock_loss_headquarters_reviews WHERE id=original_decision.review_id;
        SELECT * INTO loss_line FROM public.stock_operation_lines WHERE id=original_decision.line_id;
        SELECT * INTO loss_order FROM public.stock_operation_orders WHERE id=loss_line.operation_id;
        IF original_decision.id IS NULL OR headquarters_review.id IS NULL
           OR original_decision.disposition IS DISTINCT FROM 'scrap'
           OR headquarters_review.operation_id IS DISTINCT FROM loss_order.id
           OR headquarters_review.request_hash IS DISTINCT FROM source->>'expected_headquarters_review_hash'
           OR loss_order.plan_hash IS DISTINCT FROM source->>'expected_submission_plan_hash' THEN
            RAISE EXCEPTION '0165 exact original seal approval required' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_loss_inventory_audit_members_0159();
        PERFORM public.rsc_check_loss_submission_history_0159(loss_order.id);
        PERFORM public.rsc_check_loss_regional_history_0159(headquarters_review.regional_review_id);
        PERFORM public.rsc_check_loss_headquarters_history_0159(headquarters_review.id);
        -- No root is fabricated or returned, even if another request later
        -- executes this decision. Existing histories must still be complete.
        FOR root IN SELECT * FROM public.stock_loss_dispositions WHERE headquarters_decision_id=original_decision.id LOOP
            PERFORM public.rsc_check_loss_history_graph_0159(root.id);
        END LOOP;
        anchors:=anchors||jsonb_build_object('original_decision_id',original_decision.id);
        source_time:=headquarters_review.created_at;
    ELSIF checked_kind='correction' THEN
        SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=(source->>'root_disposition_id')::uuid;
        SELECT * INTO inverse FROM public.stock_loss_disposition_reversals WHERE id=(source->>'reversal_id')::uuid;
        SELECT * INTO correction FROM public.stock_loss_correction_decisions WHERE id=(source->>'correction_decision_id')::uuid;
        SELECT * INTO loss_line FROM public.stock_operation_lines WHERE id=root.line_id;
        SELECT * INTO loss_order FROM public.stock_operation_orders WHERE id=root.operation_id;
        IF root.id IS NULL OR inverse.id IS NULL OR correction.id IS NULL
           OR root.request_hash IS DISTINCT FROM source->>'expected_root_request_hash'
           OR loss_order.plan_hash IS DISTINCT FROM source->>'expected_submission_plan_hash'
           OR inverse.root_disposition_id IS DISTINCT FROM root.id
           OR inverse.request_hash IS DISTINCT FROM source->>'expected_reversal_hash'
           OR correction.root_disposition_id IS DISTINCT FROM root.id
           OR correction.reversal_id IS DISTINCT FROM inverse.id
           OR correction.expected_reversal_hash IS DISTINCT FROM inverse.request_hash
           OR correction.request_hash IS DISTINCT FROM source->>'expected_correction_decision_hash'
           OR correction.disposition IS DISTINCT FROM 'scrap' THEN
            RAISE EXCEPTION '0165 exact corrected seal approval required' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_check_loss_history_graph_0159(root.id);
        anchors:=anchors||jsonb_build_object('root_disposition_id',root.id,'reversal_id',inverse.id,
            'correction_decision_id',correction.id);
        source_time:=correction.created_at;
    ELSE
        SELECT * INTO scrap FROM public.stock_scrap_lines WHERE id=(source->>'scrap_line_id')::uuid;
        SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=scrap.root_disposition_id;
        SELECT * INTO loss_line FROM public.stock_operation_lines WHERE id=scrap.loss_line_id;
        SELECT * INTO loss_order FROM public.stock_operation_orders WHERE id=root.operation_id;
        IF scrap.id IS NULL OR root.id IS NULL THEN
            RAISE EXCEPTION '0165 exact seal scrap source required' USING ERRCODE='23514'; END IF;
        IF scrap.source_kind='original' THEN source_fact:=to_jsonb(root);
        ELSE
            SELECT to_jsonb(c) INTO source_fact FROM public.stock_loss_correction_executions c WHERE c.id=scrap.correction_execution_id;
        END IF;
        IF source_fact IS NULL OR source_fact->>'request_hash' IS DISTINCT FROM source->>'expected_scrap_request_hash' THEN
            RAISE EXCEPTION '0165 seal scrap request hash differs' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_scrap_recovery_source_0165(scrap.id);
        PERFORM public.rsc_check_loss_history_graph_0159(root.id);
        PERFORM public.rsc_check_scrap_recovery_approvals_0165(scrap.id);
        anchors:=anchors||jsonb_build_object('root_disposition_id',root.id,'scrap_line_id',scrap.id);
        source_time:=scrap.created_at;
        IF checked_kind<>'apply' THEN
            SELECT * INTO application FROM public.stock_scrap_recovery_requests WHERE id=(command->>'recovery_request_id')::uuid;
            IF application.id IS NULL OR application.scrap_line_id IS DISTINCT FROM scrap.id
               OR application.request_hash IS DISTINCT FROM command->>'expected_request_hash' THEN
                RAISE EXCEPTION '0165 exact seal recovery application required' USING ERRCODE='23514'; END IF;
            anchors:=anchors||jsonb_build_object('recovery_request_id',application.id);
            source_time:=application.created_at;
            IF checked_kind='headquarters' THEN
                SELECT * INTO region FROM public.stock_scrap_recovery_regional_reviews WHERE id=(command->>'regional_review_id')::uuid;
                IF region.id IS NULL OR region.scrap_line_id IS DISTINCT FROM scrap.id
                   OR region.recovery_request_id IS DISTINCT FROM application.id OR region.decision IS DISTINCT FROM 'verified'
                   OR region.request_hash IS DISTINCT FROM command->>'expected_regional_hash' THEN
                    RAISE EXCEPTION '0165 exact verified seal regional source required' USING ERRCODE='23514'; END IF;
                anchors:=anchors||jsonb_build_object('regional_review_id',region.id,'regional_decision','verified');
                source_time:=region.created_at;
            ELSIF checked_kind='execute' THEN
                SELECT * INTO final FROM public.stock_scrap_recovery_headquarters_reviews WHERE id=(command->>'headquarters_review_id')::uuid;
                IF final.id IS NULL OR final.scrap_line_id IS DISTINCT FROM scrap.id
                   OR final.recovery_request_id IS DISTINCT FROM application.id OR final.decision IS DISTINCT FROM 'approve'
                   OR final.request_hash IS DISTINCT FROM command->>'expected_headquarters_hash' THEN
                    RAISE EXCEPTION '0165 exact approved seal headquarters source required' USING ERRCODE='23514'; END IF;
                anchors:=anchors||jsonb_build_object('headquarters_review_id',final.id,'headquarters_decision','approve');
                source_time:=final.created_at;
            END IF;
        END IF;
    END IF;
    SELECT * INTO account FROM public.stock_accounts WHERE id=loss_line.reserved_account_id;
    IF loss_order.id IS NULL OR loss_line.id IS NULL OR account.id IS NULL OR source_time IS NULL
       OR source_time>clock_timestamp() OR loss_line.operation_id IS DISTINCT FROM loss_order.id
       OR loss_order.operation_type IS DISTINCT FROM 'loss_report' OR loss_line.operation_type IS DISTINCT FROM 'loss_report'
       OR account.location_id IS DISTINCT FROM loss_order.source_location_id
       OR account.custodian_person_id IS DISTINCT FROM loss_order.requester_id
       OR account.availability_bucket IS DISTINCT FROM 'frozen' THEN
        RAISE EXCEPTION '0165 exact original loss scope for seal required' USING ERRCODE='23514'; END IF;
    RETURN prepared||anchors||jsonb_build_object('loss_operation_id',loss_order.id,'loss_line_id',loss_line.id,
        'scrap_disposition','scrap','source_created_at',source_time,'owner_org_id',account.owner_org_id,
        'location_id',account.location_id,'requester_id',loss_order.requester_id,
        'applicant_user_id',application.actor_user_id,'applicant_person_id',application.actor_person_id,
        'regional_user_id',region.actor_user_id,'regional_person_id',region.actor_person_id);
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_scrap_seal_source_0165(text,jsonb)
FROM PUBLIC,star_oam_api,star_oam_backup,star_oam_projector,star_oam_edge,edge_inbox;

CREATE FUNCTION public.rsc_prepare_scrap_seal_source_0165(checked_kind text, command jsonb, client_key text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
BEGIN
    RETURN public.rsc_prepare_scrap_seal_request_0165(checked_kind,command,client_key)
        ||public.rsc_scrap_seal_source_0165(checked_kind,command);
END;
$function$;
REVOKE ALL ON FUNCTION public.rsc_prepare_scrap_seal_source_0165(text,jsonb,text)
FROM PUBLIC,star_oam_api,star_oam_backup,star_oam_projector,star_oam_edge,edge_inbox;

-- Private current seal authority over a database-derived historical source.
-- The registrar must additionally prove absence, acquire the ledger lock,
-- write exactly one audit and repeat this proof at COMMIT. No stock permit,
-- seal fact, API grant or relaxation of physical recovery guards is created.
CREATE FUNCTION public.rsc_scrap_seal_authority_0165(
    actor_id text, actor_version bigint, actor_person uuid, checked_kind text, command jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
DECLARE actor public.users%ROWTYPE; person public.people%ROWTYPE; actor_org public.organizations%ROWTYPE;
    prepared jsonb; owner_id uuid; requester_id uuid; at timestamptz; ancestors uuid[]; latest uuid[];
    invalid_tree boolean; target_org uuid; required_role text; required_scope text; required_scope_id text;
    required_action text; checked_action text;
BEGIN
    IF current_setting('transaction_isolation')<>'read committed'
       OR checked_kind IS NULL OR checked_kind NOT IN ('original','correction','apply','regional','headquarters','execute') THEN
        RAISE EXCEPTION '0165 explicit seal kind and read committed required' USING ERRCODE='23514'; END IF;
    prepared:=public.rsc_scrap_seal_source_0165(checked_kind,command);
    owner_id:=(prepared->>'owner_org_id')::uuid;
    requester_id:=(prepared->>'requester_id')::uuid;
    PERFORM public.rsc_lock_formal_principal_graph_0026(ARRAY[actor_id]::text[]);
    SELECT * INTO actor FROM public.users WHERE id=actor_id;
    SELECT * INTO person FROM public.people WHERE id=actor.person_id;
    SELECT * INTO actor_org FROM public.organizations WHERE id=person.organization_id FOR SHARE;
    IF actor.id IS NULL OR person.id IS NULL OR actor_org.id IS NULL
       OR NOT actor.is_active OR actor.account_status IS DISTINCT FROM 'active'
       OR person.employment_status IS DISTINCT FROM 'active'
       OR actor.person_id IS DISTINCT FROM actor_person OR actor.authorization_version IS DISTINCT FROM actor_version
       OR actor_org.status IS DISTINCT FROM 'active' OR actor_org.org_type NOT IN ('headquarters','region_company','department')
       OR NOT EXISTS(SELECT 1 FROM public.auth_identities WHERE user_id=actor.id
            AND status='active' AND verified_at IS NOT NULL AND revoked_at IS NULL) THEN
        RAISE EXCEPTION '0165 current recovery identity invalid' USING ERRCODE='23514'; END IF;
    IF checked_kind='apply' THEN
        IF actor_person IS DISTINCT FROM requester_id THEN
            RAISE EXCEPTION '0165 recovery applicant must be original custodian' USING ERRCODE='23514'; END IF;
        required_role:='technician'; required_scope:='person'; required_scope_id:=requester_id::text;
        required_action:='apply_scrap_recovery'; target_org:=person.organization_id;
    ELSIF checked_kind='regional' THEN
        required_role:='provincial_manager'; required_scope:='organization'; required_scope_id:=owner_id::text;
        required_action:='review_scrap_recovery_regional'; target_org:=owner_id;
    ELSE
        required_role:='admin'; required_scope:='national'; required_scope_id:='*'; target_org:=owner_id;
        required_action:=CASE checked_kind WHEN 'original' THEN 'dispose_loss'
            WHEN 'correction' THEN 'correct_loss' WHEN 'headquarters' THEN 'review_scrap_recovery_headquarters'
            ELSE 'execute_scrap_recovery' END;
    END IF;
    -- Organization-deny semantics follow the target: the applicant's person
    -- scope uses their organization; regional/HQ actions use the asset owner.
    WITH RECURSIVE tree AS (
        SELECT id,parent_id,status,ARRAY[id] visited,false cycle FROM public.organizations WHERE id=target_org
        UNION ALL SELECT o.id,o.parent_id,o.status,t.visited||o.id,o.id=ANY(t.visited)
            FROM public.organizations o JOIN tree t ON o.id=t.parent_id WHERE NOT t.cycle
    ) SELECT array_agg(id ORDER BY id),bool_or(cycle OR status<>'active') INTO ancestors,invalid_tree FROM tree;
    IF COALESCE(invalid_tree,true) THEN
        RAISE EXCEPTION '0165 recovery scope hierarchy invalid' USING ERRCODE='23514'; END IF;
    PERFORM id FROM public.organizations WHERE id=ANY(ancestors) OR id=owner_id
       OR id::text IN (SELECT scope_id FROM public.role_assignments WHERE user_id=actor_id AND scope_type='organization')
       ORDER BY id FOR SHARE;
    WITH RECURSIVE tree AS (
        SELECT id,parent_id,status,ARRAY[id] visited,false cycle FROM public.organizations WHERE id=target_org
        UNION ALL SELECT o.id,o.parent_id,o.status,t.visited||o.id,o.id=ANY(t.visited)
            FROM public.organizations o JOIN tree t ON o.id=t.parent_id WHERE NOT t.cycle
    ) SELECT array_agg(id ORDER BY id),bool_or(cycle OR status<>'active') INTO latest,invalid_tree FROM tree;
    IF COALESCE(invalid_tree,true) OR ancestors IS DISTINCT FROM latest
       OR NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=owner_id AND org_type='region_company' AND status='active') THEN
        RAISE EXCEPTION '0165 recovery owner or scope changed' USING ERRCODE='23514'; END IF;
    -- Closing a historical request never authorizes stock movement. Current
    -- custody and current executable stock plans belong to physical writers.
    -- Reviewer independence is derived from exact persisted source ancestors.
    IF checked_kind IN ('regional','headquarters') AND (
        actor_id IS NOT DISTINCT FROM prepared->>'applicant_user_id'
        OR actor_person IS NOT DISTINCT FROM (prepared->>'applicant_person_id')::uuid
        OR (checked_kind='headquarters' AND (
            actor_id IS NOT DISTINCT FROM prepared->>'regional_user_id'
            OR actor_person IS NOT DISTINCT FROM (prepared->>'regional_person_id')::uuid))) THEN
        RAISE EXCEPTION '0165 seal reviewers must be independent' USING ERRCODE='23514'; END IF;
    at:=clock_timestamp();
    IF EXISTS(SELECT 1 FROM public.role_assignments a JOIN public.roles r ON r.id=a.role_id
        LEFT JOIN public.organizations scope ON scope.id::text=a.scope_id
        WHERE a.user_id=actor.id AND a.status IN ('active','scheduled') AND a.revoked_at IS NULL
          AND a.valid_from<=at AND (a.valid_to IS NULL OR a.valid_to>at) AND r.status='active'
          AND NOT CASE r.code
            WHEN 'admin' THEN NOT r.is_external AND a.scope_type='national' AND a.scope_id='*' AND actor_org.org_type='headquarters'
            WHEN 'provincial_manager' THEN NOT r.is_external AND a.scope_type='organization' AND scope.id IS NOT NULL
                AND scope.org_type='region_company' AND scope.status='active'
            WHEN 'technician' THEN NOT r.is_external AND a.scope_type='person' AND a.scope_id=person.id::text
            ELSE false END) THEN
        RAISE EXCEPTION '0165 recovery role graph invalid' USING ERRCODE='23514'; END IF;
    FOREACH checked_action IN ARRAY ARRAY['read',required_action] LOOP
    IF NOT EXISTS(SELECT 1 FROM public.role_assignments a JOIN public.roles r ON r.id=a.role_id
        JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id
        WHERE a.user_id=actor.id AND a.status IN ('active','scheduled') AND a.revoked_at IS NULL
          AND a.valid_from<=at AND (a.valid_to IS NULL OR a.valid_to>at)
          AND r.status='active' AND r.code=required_role AND NOT r.is_external
          AND a.scope_type=required_scope AND a.scope_id=required_scope_id
          AND rp.effect='allow' AND p.resource='stock_operation' AND p.action=checked_action AND p.field_code='')
       OR EXISTS(SELECT 1 FROM public.role_assignments a JOIN public.roles r ON r.id=a.role_id
        JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id
        WHERE a.user_id=actor.id AND a.status IN ('active','scheduled') AND a.revoked_at IS NULL
          AND a.valid_from<=at AND (a.valid_to IS NULL OR a.valid_to>at) AND r.status='active'
          AND rp.effect='deny' AND p.resource='stock_operation' AND p.action=checked_action AND p.field_code=''
          AND ((a.scope_type='national' AND a.scope_id='*')
            OR (a.scope_type='organization' AND a.scope_id IN (SELECT value::text FROM unnest(ancestors) value))
            OR (checked_kind='apply' AND a.scope_type='person' AND a.scope_id=requester_id::text))) THEN
        RAISE EXCEPTION '0165 current seal read and action permission required' USING ERRCODE='23514'; END IF;
    END LOOP;
    RETURN prepared;
END;
$function$;
