FROM PUBLIC,star_oam_backup,star_oam_api,star_oam_projector,star_oam_edge,edge_inbox;

CREATE FUNCTION public.rsc_prepare_scrap_seal_authority_0165(
    actor_id text, actor_version bigint, actor_person uuid, checked_kind text, command jsonb, client_key text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public
AS $function$
BEGIN
