CREATE OR REPLACE FUNCTION public.rsc_assert_scrap_domain_events_0165(fact jsonb, aggregate text, kind text, body jsonb, recipient uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
