CREATE OR REPLACE FUNCTION public.rsc_check_loss_correction_admission_0159()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE parent_actor text; requester uuid; owner_id uuid; required_action text;
    seal public.stock_loss_inverse_request_seals%ROWTYPE; other_table text; collision boolean;
BEGIN
    IF TG_OP<>'INSERT' OR TG_TABLE_SCHEMA<>'public' THEN
        RAISE EXCEPTION '0159 invalid admission trigger' USING ERRCODE='23514'; END IF;
    required_action:=CASE TG_TABLE_NAME
        WHEN 'stock_loss_disposition_reversals' THEN 'reverse_loss'
        WHEN 'stock_loss_correction_decisions' THEN 'approve_loss_correction'
        WHEN 'stock_loss_correction_executions' THEN 'correct_loss'
        WHEN 'stock_loss_inverse_request_seals' THEN 'reverse_loss' WHEN 'stock_loss_correction_approval_seals' THEN 'approve_loss_correction' WHEN 'stock_loss_correction_execution_seals' THEN 'correct_loss' END;
    SELECT p.actor_user_id,p.requester_id,l.owner_org_id INTO parent_actor,requester,owner_id
        FROM public.stock_loss_dispositions r JOIN public.stock_operation_orders p ON p.id=r.operation_id
        JOIN public.stock_locations l ON l.id=p.source_location_id
        WHERE r.id=NEW.root_disposition_id AND p.operation_type='loss_report';
    IF required_action IS NULL OR owner_id IS NULL OR requester IS NULL OR parent_actor IS NULL
       OR (required_action='approve_loss_correction' AND
            (NEW.actor_user_id=parent_actor OR NEW.actor_person_id=requester)) THEN
        RAISE EXCEPTION '0159 exact loss context and independent approver required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_assert_loss_correction_authority_0159(NEW.actor_user_id,NEW.authorization_version,
        NEW.actor_person_id,owner_id,required_action);
    IF TG_TABLE_NAME='stock_loss_inverse_request_seals' THEN
        SELECT * INTO seal FROM public.stock_loss_inverse_request_seals WHERE id=NEW.id;
        IF seal.id IS NULL THEN
            RAISE EXCEPTION '0159 retained inverse seal required' USING ERRCODE='23514'; END IF;
        FOREACH other_table IN ARRAY ARRAY['stock_loss_disposition_reversals',
                'stock_loss_correction_decisions','stock_loss_correction_executions'] LOOP
            EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE idempotency_key_hash=ANY($1) '
                'OR (actor_user_id=$2 AND request_id=$3))',other_table)
                INTO collision USING ARRAY[seal.reversal_key_hash,seal.approval_key_hash,seal.correction_key_hash],
                    seal.actor_user_id,seal.request_id;
            IF collision THEN RAISE EXCEPTION '0159 written request cannot be sealed' USING ERRCODE='23514'; END IF;
        END LOOP;
    ELSIF EXISTS(SELECT 1 FROM public.stock_loss_inverse_request_seals s
        WHERE NEW.idempotency_key_hash IN (s.reversal_key_hash,s.approval_key_hash,s.correction_key_hash)
            OR (s.actor_user_id=NEW.actor_user_id AND s.request_id=NEW.request_id)) THEN
        RAISE EXCEPTION '0159 sealed request cannot be written' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
