CREATE OR REPLACE FUNCTION public.rsc_loss_requests_with_proof_0165(checked_root uuid, checked_proof jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE root public.stock_loss_dispositions%ROWTYPE; parent public.stock_operation_orders%ROWTYPE;
    inverse public.stock_loss_disposition_reversals%ROWTYPE;
    approval public.stock_loss_correction_decisions%ROWTYPE;
    target jsonb; item record; body jsonb; intent jsonb; expected jsonb; snapshot jsonb;
    all_requests jsonb; returned_requests jsonb:='[]'::jsonb;
BEGIN
    -- This also takes the shared inventory head lock and validates all future
    -- edges; an early historical cursor cannot conceal a malformed successor.
    snapshot:=public.rsc_loss_chain_projection_0159(checked_root,NULL);
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=checked_root;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT jsonb_agg(q.body ORDER BY q.kind,q.body->>'id') INTO all_requests FROM (
        SELECT 'reverse_loss' AS kind,to_jsonb(r) AS body FROM public.stock_loss_disposition_reversals r
        UNION ALL SELECT 'approve_loss_correction',to_jsonb(d) FROM public.stock_loss_correction_decisions d
        UNION ALL SELECT 'correct_loss',to_jsonb(c) FROM public.stock_loss_correction_executions c) q;
    FOR item IN
        SELECT 'reverse_loss' AS kind,to_jsonb(r) AS body FROM public.stock_loss_disposition_reversals r WHERE root_disposition_id=root.id
        UNION ALL SELECT 'approve_loss_correction',to_jsonb(d) FROM public.stock_loss_correction_decisions d WHERE root_disposition_id=root.id
        UNION ALL SELECT 'correct_loss',to_jsonb(c) FROM public.stock_loss_correction_executions c WHERE root_disposition_id=root.id
    LOOP
        body:=item.body;
        IF NOT COALESCE(
            body->>'request_id' ~ '^[A-Za-z0-9._:-]{8,160}$'
            AND body->>'request_hash' ~ '^[a-f0-9]{64}$'
            AND body->>'idempotency_key_hash' ~ '^[a-f0-9]{64}$'
            AND body->>'actor_user_id' ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
            AND body->>'actor_user_id'<>'00000000-0000-0000-0000-000000000000'
            AND body->>'actor_person_id'<>'00000000-0000-0000-0000-000000000000'
            AND (body->>'authorization_version')::bigint>0
            AND (body->>'created_at')::timestamptz>=root.created_at
            AND (body->>'created_at')::timestamptz<=clock_timestamp()
            AND length(body->>'reason') BETWEEN 1 AND 500
            AND btrim(body->>'reason',chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(28)||chr(29)||chr(30)||chr(31)||chr(32)||chr(133)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288))=body->>'reason',false)
           OR EXISTS(SELECT 1 FROM generate_series(1,length(body->>'reason')) p
                WHERE ascii(substr(body->>'reason',p,1))<32 AND ascii(substr(body->>'reason',p,1)) NOT IN (9,10))
           OR (SELECT count(*) FROM jsonb_array_elements(all_requests) r WHERE
                r->>'idempotency_key_hash'=body->>'idempotency_key_hash')<>1
           OR (SELECT count(*) FROM jsonb_array_elements(all_requests) r WHERE
                r->>'actor_user_id'=body->>'actor_user_id' AND r->>'request_id'=body->>'request_id')<>1 THEN
            RAISE EXCEPTION '0159 complete unique historical request context required' USING ERRCODE='23514'; END IF;
        IF (item.kind='reverse_loss' AND body->>'scrap_line_id' IS NOT NULL)
            OR (item.kind='correct_loss' AND body->>'disposition'='scrap') THEN
            PERFORM public.rsc_scrap_history_from_proof_0165(
                CASE item.kind WHEN 'reverse_loss' THEN 'inverse' ELSE 'correction' END,(body->>'id')::uuid,root.id,checked_proof);
            returned_requests:=returned_requests||jsonb_build_array(jsonb_build_object(
                'id',body->>'id','action',body#>>'{command_jsonb,action}','request_hash',body->>'request_hash'));
            CONTINUE;
        END IF;
        intent:=jsonb_build_object('root_disposition_id',root.id::text,'expected_root_request_hash',root.request_hash,
            'expected_submission_plan_hash',parent.plan_hash,'reason',body->>'reason');
        IF item.kind='reverse_loss' THEN
            IF body->>'reversed_correction_id' IS NULL THEN target:=to_jsonb(root);
            ELSE SELECT to_jsonb(c) INTO target FROM public.stock_loss_correction_executions c
                WHERE c.id=(body->>'reversed_correction_id')::uuid AND c.root_disposition_id=root.id; END IF;
            IF target IS NULL OR body->>'original_transaction_id' IS DISTINCT FROM target->>'posting_transaction_id'
               OR body->>'original_movement_id' IS DISTINCT FROM target->>'posting_movement_id'
