CREATE OR REPLACE FUNCTION public.rsc_scrap_upstream_with_audit_0165(checked_root uuid, audit_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE root public.stock_loss_dispositions%ROWTYPE; decision public.stock_loss_headquarters_decisions%ROWTYPE;
    review public.stock_loss_headquarters_reviews%ROWTYPE;
BEGIN
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=checked_root;
    SELECT * INTO decision FROM public.stock_loss_headquarters_decisions WHERE id=root.headquarters_decision_id;
    SELECT * INTO review FROM public.stock_loss_headquarters_reviews WHERE id=decision.review_id;
    IF root.id IS NULL OR decision.id IS NULL OR review.id IS NULL OR review.operation_id<>root.operation_id
       OR decision.line_id<>root.line_id OR decision.disposition<>root.disposition THEN
        RAISE EXCEPTION '0159 exact upstream loss lineage required' USING ERRCODE='23514'; END IF;
    IF audit_ids IS NULL OR cardinality(audit_ids)=0 THEN
        RAISE EXCEPTION '0165 fresh root audit proof required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_check_loss_submission_history_0159(root.operation_id);
    PERFORM public.rsc_check_loss_regional_history_0159(review.regional_review_id);
    PERFORM public.rsc_check_loss_headquarters_history_0159(review.id);
END;
$function$

